window.HB_TR["numbers"]["fa"]=["۱. و خداوند در بیابان سینا، در خیمه جماعت، در روز اول ماه دوم، در سال دوم پس از خروج از سرزمین مصر، به موسی گفت:\n۲. مجموع همه جماعت بنی اسرائیل، پس از خانواده هایشان، به نام خانه پدرانشان، با تعداد {نام های} آن ها، هر مرد را بر اساس شماره هایشان بپذیرید؛\n۳. از بیست سالگی به بعد، هر کسی که قادر به جنگ در اسرائیل است، تو و هارون آن ها را بر اساس لشکرهایشان شمارش کن.\n۴. و با تو مردی از هر قبیله خواهد بود؛ هر یک رئیس خاندان پدرانش.\n۵. و این ها نام مردانی است که با تو خواهند ایستاد: قبیله روبن؛ الیزور، پسر شدیور.\n۶. از سیمئون؛ شلومیئل، پسر زوری شادای.\n۷. یهودا؛ ناحشون، پسر امیناداب.\n۸. از ایساکار؛ نتانئیل پسر زوار.\n۹. زبولون؛ الیاب پسر هلون.\n۱۰. از فرزندان یوسف: از افرایم؛ الیشامه پسر امیهود: از مناشی؛ گمالیئل، پسر پداهزور.\n۱۱. از بنجامین؛ ابیدان، پسر گیدئونی.\n۱۲. از دن؛ آهیزر پسر امیشادای.\n۱۳. آشر؛ پاگیل، پسر اوکران.\n۱۴. از گاد؛ الیاساف، پسر دویل. {دویل: همچنین روئل}\n۱۵. از نفتالی؛ آهیرا، پسر عنان.\n۱۶. این ها {بودند} برجسته های جماعت، شاهزادگان قبایل نیاکان خود، سران هزاران نفر در اسرائیل.\n۱۷. و موسی و هارون این مردان را که با نام های {آنها} بیان شده اند، برداشتند:\n۱۸. و همه جماعت را در روز اول ماه دوم گرد هم آوردند و شجره نامه خود را بر اساس خانواده هایشان، از خاندان پدرانشان، بر اساس تعداد نام ها از بیست سال به بالا، بر اساس شمارش نامه هایشان اعلام کردند.\n۱۹. چنان که خداوند به موسی فرمان داد، آنان را نیز در بیابان سینا شمرد.\n20. و فرزندان روبن، پسر بزرگ اسرائیل، به نسل های خود، پس از خانواده هایشان، به خاندان های پدرشان، بر اساس تعداد نام ها، بر اساس تعداد اسامی شان، هر مرد از بیست سال به بالا، همه کسانی که قادر به رفتن به جنگ بودند؛\n۲۱. کسانی که شمارش شده بودند، {حتی} از قبیله روبن، چهل و شش هزار و پانصد نفر بودند.\n۲۲. از فرزندان سیمئون، به نسل هایشان، پس از خانواده هایشان، به خاندان پدرانشان، کسانی که بر اساس تعداد نام ها، بر اساس تعداد نامهایشان، هر مرد از بیست سال به بالا، هر مردی که می توانست به جنگ برود، شمارش می شد؛\n۲۳. کسانی که شمارش شده بودند، {حتی} از قبیله سیمئون، {پنجاه و نه هزار و سیصد} بودند.\n۲۴. از فرزندان گاد، بر اساس نسل هایشان، بر اساس خانواده هایشان، به خاندان های پدرشان، بر اساس تعداد نام ها، از بیست سال به بالا، همه کسانی که قادر به رفتن به جنگ بودند؛\n۲۵. کسانی که شمارش شدند، {حتی} از قبیله گاد، چهل و پنج هزار و ششصد و پنجاه نفر بودند.\n۲۶. از فرزندان یهودا، بر اساس نسل هایشان، پس از خانواده هایشان، به خاندان پدرانشان، بر اساس تعداد نام ها، از بیست سال به بالا، همه کسانی که قادر به رفتن به جنگ بودند؛\n۲۷. کسانی که شمارش شده بودند، {حتی} از قبیله یهودا، {۶۰} و چهارده هزار و ششصد نفر بودند.\n۲۸. از فرزندان یساکار، بر اساس نسل هایشان، پس از خانواده هایشان، به خاندان پدرانشان، بر اساس تعداد نام ها، از بیست سال به بالا، همه کسانی که قادر به رفتن به جنگ بودند؛\n۲۹. کسانی که شمارش شده بودند، {حتی} از قبیله ایساکار، {پنجاه و چهار هزار و چهارصد} بودند.\n۳۰. از فرزندان زبولون، بر اساس نسل هایشان، پس از خانواده هایشان، به خاندان پدرانشان، بر اساس تعداد نام ها، از بیست سال به بالا، همه کسانی که قادر به رفتن به جنگ بودند؛\n۳۱. کسانی که شمارش شدند، حتی از قبیله زبولون، پنجاه و هفت هزار و چهارصد نفر بودند.\n۳۲. از فرزندان یوسف، {یعنی} از فرزندان افرایم، به نسل های خود، پس از خانواده هایشان، به خاندان پدرانشان، بر اساس تعداد نام ها، از بیست سال به بالا، همه کسانی که قادر به رفتن به جنگ بودند؛\n۳۳. کسانی که از قبیله افریم شمار می شدند، {حتی} از قبیله افریم {بودند} چهل هزار و پانصد نفر.\n۳۴. از فرزندان مناسی، به نسل های خود، پس از خانواده هایشان، به خاندان پدرانشان، بر اساس تعداد نام ها، از بیست سال به بالا، همه کسانی که قادر به رفتن به جنگ بودند؛\n۳۵. کسانی که شمارش شدند، {حتی} از قبیله مناسی، {سی} و دو هزار و دویست نفر بودند.\n۳۶. از فرزندان بنیامین، بر اساس نسل هایشان، پس از خانواده هایشان، به خاندان پدرانشان، بر اساس تعداد نام ها، از بیست سال به بالا، همه کسانی که قادر به رفتن به جنگ بودند؛\n۳۷. کسانی که شمارش شده بودند، {حتی} از قبیله بنیامین، {۳} و پنج هزار و چهارصد نفر بودند.\n۳۸. از فرزندان دان، بر اساس نسل هایشان، پس از خانواده هایشان، به خاندان پدرانشان، بر اساس تعداد نام ها، از بیست سال به بالا، همه کسانی که قادر به رفتن به جنگ بودند؛\n۳۹. کسانی که شمارش شده بودند، {حتی} از قبیله دان، {سیصد] و دو هزار و هفتصد نفر بودند.\n۴۰. از فرزندان آشر، بر اساس نسل هایشان، پس از خانواده هایشان، به خاندان پدرانشان، بر اساس تعداد نام ها، از بیست سال به بالا، همه کسانی که قادر به رفتن به جنگ بودند؛\n۴۱. کسانی که شمارش شدند، {حتی} از قبیله آشر، {چهل} هزار و پانصد نفر بودند.\n۴۲. از فرزندان نفتالی، در طول نسل هایشان، پس از خانواده هایشان، از خاندان پدرانشان، بر اساس تعداد نام ها، از بیست سال به بالا، همه کسانی که قادر به جنگ بودند؛\n۴۳. کسانی که شمارش شدند، حتی از قبیله نفتالی، پنجاه و سه هزار و چهارصد نفر بودند.\n۴۴. این ها کسانی هستند که شماره گذاری شدند و موسی و هارون آن ها را شمارش کردند، و شاهزادگان اسرائیل که دوازده مرد بودند: هر یک برای خاندان پدرانش بود.\n۴۵. همچنین همه کسانی که از بنی اسرائیل از خاندان پدرانشان از بیست سال به بالا شمارش شده بودند، همه کسانی که قادر به جنگ در اسرائیل بودند؛\n۴۶. حتی همه کسانی که شمارش شده بودند، ششصد هزار و سه هزار و پانصد و پنجاه بودند.\n۴۷. اما لاویان پس از قبیله پدرانشان در میان آن ها شمارش نشدند.\n۴۸. زیرا خداوند با موسی سخن گفته بود:\n۴۹. فقط قبیله لاوی را شمارش نکن و مجموع آن ها را در میان بنی اسرائیل برنشناس:\n۵۰. اما لاویان را بر خیمه شهادت و بر همه ظروف آن و بر همه چیزهایی که متعلق به آن است، منصوب کن؛ آنان خیمه و همه ظروف آن را حمل خواهند کرد؛ و آن ها به آن خدمت خواهند کرد و اطراف خیمه اردو خواهند زد.\n۵۱. و وقتی خیمه به جلو نشست، لاویان آن را پایین خواهند آورد؛ و وقتی قرار است خیمه برپا شود، لاویان آن را برپا خواهند کرد و غریبه ای که نزدیک شود کشته خواهد شد.\n۵۲. و بنی اسرائیل چادرهای خود را برپا خواهند کرد، هر به اردوگاه خود و هر به پرچم خود، در میان لشکریان خود.\n۵۳. اما لاویان دور خیمه شهادت خواهند چرخاند تا خشم بر جماعت بنی اسرائیل نازل نشود و لاویان مسئولیت تابناک شهادت را حفظ کنند.\n۵۴. و بنی اسرائیل طبق همه آنچه خداوند به موسی فرمان داده بود، انجام دادند.","۱. و خداوند به موسی و هارون گفت و گفت:\n۲. هر مرد از بنی اسرائیل باید با پرچم خود، با پرچم خانه پدرش، پرتاب کند: دور از خیمه جماعت باید پرتاب کند. {دور...: عبری. در مقابل}\n۳. و در سمت شرق، به سوی طلوع خورشید، پرچم اردوگاه یهودا در سراسر ارتش های خود خواهند ایستاد و ناحشون پسر امیناداب فرمانده فرزندان یهودا خواهد بود.\n۴. و لشکرش و کسانی که شمارش شده بودند، سیصد و چهارده هزار و ششصد نفر بودند.\n۵. و کسانی که در کنار او پرتاب کنند، قبیله یساکار خواهند بود؛ و نتانئیل پسر زوار فرمانده فرزندان عیساکار خواهد بود.\n۶. و لشکرش و کسانی که شمارش شده بودند، پنجاه و چهار هزار و چهارصد نفر بودند.\n۷. {سپس} قبیله زبولون: و الیاب پسر حلون {خواهد بود} فرمانده فرزندان زبولون.\n۸. و لشکر او و کسانی که شمارش شده بودند، پنجاه و هفت هزار و چهارصد نفر بودند.\n۹. همه کسانی که در اردوگاه یهودا بودند، صد هزار و شصت هزار و شش هزار و چهارصد نفر در سراسر ارتش هایشان بودند. این ها ابتدا حرکت خواهند کرد.\n۱۰. در سمت جنوب، پرچم اردوگاه روبن بر اساس ارتش هایشان قرار خواهد گرفت؛ و فرمانده فرزندان روبن الیزور، پسر شدور خواهد بود.\n۱۱. و لشکرش و کسانی که شمارش می شدند، چهل و شش هزار و پانصد نفر بودند.\n۱۲. و کسانی که با او بازی کنند {قبیله شمعون خواهند بود}؛ و فرمانده فرزندان شمعون {خواهد بود} شلومیئل، پسر زوریشادای.\n۱۳. و لشکرش و کسانی که شمارش می شدند، پنجاه و نه هزار و سیصد نفر بودند.\n۱۴. آنگاه قبیله گاد: و فرمانده فرزندان گاد {خواهد بود} الیاساف، پسر روئیل. {روئل: همچنین دوئل نامیده می شود}\n۱۵. و لشکرش و کسانی که شمارش شده بودند، چهل و پنج هزار و ششصد و پنجاه نفر بودند.\n۱۶. همه کسانی که در اردوگاه روبن بودند، در سراسر ارتش هایشان صد هزار و پنجاه هزار و چهارصد و پنجاه نفر بودند. و آن ها در ردیف دوم حرکت خواهند کرد.\n۱۷. سپس خیمه جماعت همراه با اردوگاه لاویان در وسط اردوگاه حرکت خواهد کرد: همان طور که اردو می زنند، هر به جای خود طبق پرچم های خود به جلو خواهد ایستاد.\n۱۸. در سمت غرب پرچم اردوگاه افرایم بر اساس ارتش هایشان قرار خواهد گرفت و فرمانده پسران افرایم الیشاما پسر امیهود خواهد بود.\n۱۹. و لشکرش و کسانی که از آن ها بودند، چهل هزار و پانصد نفر بودند.\n۲۰. و به او قبیله مناسی خواهد بود؛ و فرمانده فرزندان منسی جمالیئل، پسر پدازور خواهد بود.\n۲۱. و لشکرش و کسانی که شمارش می شدند، سی و دو هزار و دویست نفر بودند.\n۲۲. سپس قبیله بنیامین: و فرمانده پسران بنیامین {خواهد بود} عابدان، پسر جدعونی.\n۲۳. و سپاه او و کسانی که شمارش شده بودند، سی و پنج هزار و چهارصد نفر بودند.\n۲۴. همه کسانی که در اردوگاه افرایم شمارش می شدند، صد هزار و هشت هزار و صد نفر بودند، در سراسر ارتش هایشان. و آن ها در ردیف سوم به جلو خواهند رفت.\n۲۵. پرچم اردوگاه دان {باید} در سمت شمال توسط ارتش هایشان باشد؛ و فرمانده فرزندان دان {خواهد بود} آهیزر پسر آمیشادای.\n۲۶. و لشکرش و کسانی که شمارش می شدند، سیصد و دو هزار و هفتصد نفر بودند.\n۲۷. و کسانی که در کنار او اردو می زنند، قبیله آشر خواهند بود؛ و فرمانده فرزندان آشر پاگیل، پسر اوکران خواهد بود.\n۲۸. و لشکرش و کسانی که شمارش می شدند، چهل و هزار و پانصد نفر بودند.\n۲۹. سپس قبیله نفتالی: و فرمانده فرزندان نفتالی {خواهد بود} آهیرا، پسر عنان.\n۳۰. و لشکرش و کسانی که شمارش می شدند، پنجاه و سه هزار و چهارصد نفر بودند.\n۳۱. همه کسانی که در اردوگاه دان بودند، صد هزار و پنجاه و هفت هزار و ششصد نفر بودند. آن ها در معیارهای خود بسیار عقب تر خواهند بود.\n۳۲. این ها کسانی هستند که از بنی اسرائیل توسط خاندان پدرانشان شمارش شده اند: همه کسانی که در اردوگاه ها در سراسر لشکرشان شمارش شده بودند، ششصد هزار و سه هزار و پانصد و پنجاه بودند.\n۳۳. اما لاویان در میان بنی اسرائیل شمرده نشدند؛ چنان که خداوند به موسی فرمان داد.\n۳۴. و بنی اسرائیل همه آنچه خداوند به موسی فرمان داده بود را انجام دادند: پس بر اساس معیارهای خود گام برداشتند و هر یک به دنبال خانواده های خود طبق خانه پدران خود حرکت کردند.","۱. این ها همچنین نسل های هارون و موسی در روزگاری که خداوند در کوه سینا با موسی سخن گفت، هستند.\n۲. و این ها نام های پسران هارون هستند؛ ناداب نخست زاده و آبیهو، الیعازر و ایتامار.\n۳. این ها نام های پسران هارون هستند، کاهنانی که مسح شدند و او آن ها را برای خدمت در مقام کاهن تقدیس کرد. {که...: عبری. دست چه کسی را پر کرد}\n۴. و ناداب و ابیهو در برابر خداوند مردند، زمانی که در بیابان سینا آتش عجیبی در برابر خداوند تقدیم کردند و فرزندی نداشتند؛ و الیعازر و ایتامار در منصب کاهن در حضور هارون پدرشان خدمت کردند.\n۵. و خداوند به موسی گفت:\n۶. قبیله لاوی را نزدیک بیاور و آن ها را نزد هارون کاهن بگذار تا به او خدمت کنند.\n۷. و مسئولیت او و مسئولیت کل جماعت را در برابر خیمه جماعت برای انجام مراسم خیمه حفظ خواهند کرد.\n۸. و همه وسایل خیمه جماعت و مسئولیت بنی اسرائیل را برای انجام خدمت در خیمه نگهداری خواهند کرد.\n۹. و لاویان را به هارون و پسرانش بسپاری: آن ها کاملاً از بنی اسرائیل به او داده شده اند.\n۱۰. و هارون و پسرانش را منصوب کن و آن ها در منصب کاهن خود منتظر خواهند بود و بیگانه ای که نزدیک شود کشته خواهد شد.\n۱۱. و خداوند به موسی گفت:\n۱۲. و من، اینک، لاویان را از میان بنی اسرائیل برداشته ام، نه همه نخست زاده هایی که در میان بنی اسرائیل ماتریکس را باز می کنند؛ پس لاویان از آن من خواهند بود؛\n۱۳. چون همه نخستین فرزندان {هستند} از آن من؛ {زیرا} در روزی که همه نخستگان سرزمین مصر را شکست دادم، همه نخستگان اسرائیل، چه انسان و چه حیوان، را برای خود مقدس کردم: آن ها مال من خواهند بود: من {هستم} خداوند.\n۱۴. و خداوند در بیابان سینا به موسی گفت:\n۱۵. فرزندان لاوی را بر اساس خانه پدران شان بر اساس خانواده هایشان شماره گذاری کن: هر مرد از یک ماهه و بالاتر باید آن ها را بشماری.\n۱۶. و موسی آن ها را طبق کلام خداوند شمرد، همان گونه که به او فرمان داده شده بود. {کلمه: عبری. دهان}\n۱۷. و این ها پسران لاوی به نام هایشان بودند؛ گرشون، و کوهات، و مراری.\n۱۸. و این ها نام های پسران گرشون از خانواده هایشان هستند؛ لبنی و شیمئی.\n۱۹. و پسران کوهات از خانواده هایشان؛ عمرام، و ایزهار، حبرون و عزیل.\n۲۰. و پسران مراری از خانواده هایشان؛ ماهلی و موشی. این ها خانواده های لاویان بر اساس خاندان پدرانشان هستند.\n۲۱. از گرشون {بود} خانواده لیبنیت ها و خانواده شیمی ها: این ها {هستند} خانواده های گرشونیان.\n۲۲. کسانی که از آن ها شماره گذاری شده بودند، بر اساس تعداد همه نرها، از یک ماهه به بالا، {حتی} کسانی که شمارش شده بودند {هفت} هزار و پانصد نفر بودند.\n۲۳. خانواده های گرشونی باید پشت خیمه به سمت غرب قیام کنند.\n۲۴. و رئیس خاندان پدر گرشونیان {خواهد بود} الیاساف، پسر لائل.\n۲۵. و مسئولیت پسران گرشون در خیمه جماعت {باید باشد} خیمه، چادر، پوشش آن و دار زدن درب خیمه جماعت،\n۲۶. و آویزان های حیاط و پرده در حیاط که کنار خیمه و محراب اطراف و طناب های آن برای تمام خدمات آن قرار دارد.\n۲۷. و از کوحات {بود} خانواده امرامیان، و خانواده ایزهاریان، و خانواده هبرونیان و خانواده عزیلیان: این ها {هستند} خانواده های کوهاتیان.\n۲۸. در تعداد همه نرها، از یک ماهه به بالا، هشت هزار و ششصد نفر بودند که مسئولیت محراب را حفظ می کردند.\n۲۹. خانواده های پسران کوهات باید در کنار تابوت به سمت جنوب کوبیده شوند.\n۳۰. و رئیس خاندان پدر خاندان های کوحاتی {خواهد بود} الیزافان، پسر عزیل.\n۳۱. و مسئولیت آن ها بر صندوق، میز، شمعدان، قربانگاه ها، ظروف محراب که با آن خدمت می کنند، دار زدن و تمام خدمات آن ها خواهد بود.\n۳۲. و العازر، پسر هارون، کاهن، رئیس رئیس لاویان خواهد بود و بر کسانی که مسئولیت حرم را دارند، نظارت خواهد داشت.\n۳۳. از مراری {بود} خانواده ماهلی ها و خانواده موشی ها: این ها {هستند} خانواده های مراری.\n۳۴. و آن هایی که از آن ها به حساب تعداد همه نرها از یک ماه به بالا بودند، شش هزار و دویست نفر بودند.\n۳۵. و رئیس خانه پدر خانواده های مراری {بود} زورئیل پسر ابیحیل: {این ها} باید در کنار خیمه به سمت شمال بکوبند.\n۳۶. و {زیر} نگهداری و مسئولیت پسران مراری {باید تخته های خیمه مقدس، و میله های آن، و ستون های آن، و حفره های آن، و تمام ظروف آن و هر آنچه به آن خدمت می کند} {زیر...: عبری. دفتر مسئولیت}\n۳۷. و ستون های حیاط اطراف، و حفره هایشان، سنجاق ها و طناب هایشان.\n۳۸. اما کسانی که در برابر خیمه به سمت شرق اردو می زنند، {حتی} پیش از خیمه جماعت به سمت شرق، {موسی} و هارون و پسرانش خواهند بود که مسئولیت مقدس را برای فرزندان اسرائیل نگه می دارند؛ و بیگانه ای که نزدیک شود، کشته خواهد شد.\n۳۹. همه لاویان که موسی و هارون به فرمان خداوند آن ها را شمارش کردند، در سراسر خانواده هایشان، همه مردان از سن یک ماهه به بالا، بیست و دو هزار نفر بودند.\n۴۰. و خداوند به موسی فرمود: همه نخستین فرزندان پسران بنی اسرائیل را از یک ماهه به بالا بشمارید و نام های آن ها را بشمارید.\n۴۱. و تو لاویان را برای من (من خداوند هستم) به جای همه نخستگان بنی اسرائیل بپذیر؛ و گاوهای لاویان به جای همه نخستین گاویان بنی اسرائیل.\n۴۲. و موسی، همان طور که خداوند به او فرمان داده بود، همه نخست زادگان بنی اسرائیل را شمارش کرد.\n۴۳. و همه پسران نخست زاده به تعداد نام ها، از سن یک ماهه و بالاتر، از میان کسانی که شمارش شده بودند، بیست و دو هزار و دویست و سیصد و سیزده نفر بودند.\n۴۴. و خداوند به موسی گفت:\n۴۵. لاویان را به جای همه نخست زادگان بنی اسرائیل و گاوهای لاویان را به جای گاوهایشان؛ و لاویان مال من خواهند بود: من خداوند هستم.\n۴۶. و برای کسانی که قرار است از دویست و سیصد و سیزده نخست فرزند بنی اسرائیل که بیش از لاویان هستند، رهایی یابند؛\n۴۷. حتی پنج شکل به ازای هر پول می گیری، پس از شکل مقدس باید آن ها را بگیری: (شکل {برابر} بیست گره است:)\n۴۸. و پولی را که تعداد فرد آن ها باید با آن بازخرید شود، به هارون و پسرانش بده.\n۴۹. و موسی پول رستگاری کسانی را که بالاتر از آنان بودند و لاویان رهایی داده بودند، گرفت:\n۵۰. از نخستین فرزند بنی اسرائیل پول را گرفت؛ هزار و سیصد و شصت و پنج شکل، پس از شکل عبادت:\n۵۱. و موسی پول رهایی یافته ها را به هارون و پسرانش داد، طبق کلام خداوند، همان گونه که خداوند به موسی فرمان داده بود.","۱. و خداوند به موسی و هارون گفت و گفت:\n۲. مجموع پسران کوحات را از میان پسران لاوی، پس از خانواده هایشان، به خانه پدرانشان بگیر،\n۳. از سی سالگی به بالا تا پنجاه سالگی، همه کسانی که وارد میزبان می شوند تا کار را در خیمه جماعت انجام دهند.\n۴. این خدمت فرزندان کوهات در خیمه جماعت، دربارهٔ مقدس ترین امور خواهد بود:\n۵. و زمانی که اردوگاه به جلو برمی گردد، هارون و پسرانش خواهند آمد و پرده پوششی را برمی دارند و صندوق شهادت را با آن می پوشانند:\n۶. و روی آن پوست گورکن ها را می پوشانم و پارچه ای کاملا آبی روی آن می پهن می کنم و در چوب های آن می گذارم.\n۷. و بر روی سفره نان شیو، پارچه ای آبی می پهن می کنند و ظرف ها، قاشق ها، کاسه ها و روکش ها را روی آن می گذارند تا همه را بپوشانند؛ و نان دائمی روی آن قرار می گیرد: {بپوشان...: یا بریزید}\n۸. و پارچه ای سرخ روی آن ها می پهن می کنند و آن را با پوست گورکن می پوشانند و در چوب های آن می گذارند.\n۹. و پارچه ای آبی برمی دارند و شمعدان نور، چراغ ها، انبرک ها، ظرف های تنبوکش و همه ظروف روغن آن را که به آن خدمت می کنند، می پوشانند:\n۱۰. و آن را و تمام ظروف آن را در پوششی از پوست گورکن قرار می دهند و آن را روی میله ای قرار می دهند.\n۱۱. و بر روی محراب طلایی پارچه ای آبی پهن می کنند و آن را با پوست گورکن می پوشانند و روی چوب های آن می گذارند:\n۱۲. و همه ابزارهای خدمت را که در محراب خدمت می کنند، برمی دارند و در پارچه ای آبی می پوشانند و با پوششی از پوست گورکن ها می پوشانند و روی میله ای می گذارند:\n۱۳. و خاکستر را از محراب برمی دارند و پارچه ای بنفش بر آن می پهن می کنند:\n۱۴. و همه ظروف آن را که با آن ها خدمت می کنند، حتی عودسازها، قلاب های گوشت و بیل ها و حوضچه ها، همه ظروف محراب، بر آن خواهند گذاشت؛ و آن ها پوششی از پوست گورکن ها را روی آن می پزند و به چوب های آن می چسبانند. {حوضچه ها: طلایی، کاسه ها}\n۱۵. و وقتی هارون و پسرانش پوشاندن محراب و همه ظروف مقدس را به پایان رساندند، همانطور که اردوگاه قرار است پیش برود؛ پس از آن، پسران کوهات خواهند آمد تا آن را به دنیا بیاورند اما نباید به هیچ چیز مقدسی دست بزنند، مبادا بمیرند. این ها بار فرزندان کوهات در خیمه جماعت است.\n۱۶. و به مقام الیعازر پسر هارون کاهن، روغن برای نور، و عود شیرین، و نذورات روزانه و روغن مسح و نظارت بر تمام خیمه و هر آنچه در آن است، در محراب و ظروف آن.\n۱۷. و خداوند به موسی و هارون گفت و گفت:\n۱۸. قبیله خاندان های کوهاثیان را از لاویان جدا نکنید:\n۱۹. اما چنین بر آنان بگذار تا زنده بمانند و نمیرند، وقتی به مقدس ترین امور نزدیک می شوند: هارون و پسرانش وارد می شوند و هر یک را به خدمت و بار خود می سپارند:\n۲۰. اما نباید وارد شوند تا ببینند چه زمانی چیزهای مقدس پوشیده شده اند، مبادا بمیرند.\n۲۱. و خداوند به موسی گفت و گفت:\n۲۲. همچنین مجموع پسران گرشون را در سراسر خاندان های پدرانشان از خانواده هایشان بپذیرید؛\n۲۳. از سی سالگی به بالا تا پنجاه سالگی باید آن ها را بشماری؛ همه کسانی که برای انجام مراسم و انجام کار در خیمه جماعت وارد می شوند. {برای اجرا...: عبری. برای جنگ جنگی}\n۲۴. این خدمت خانواده های گرشونی، خدمت و بارهایی است: {بارها: یا، حمل}\n۲۵. و پرده های خیمه و خیمه جماعت، پوشش او و پوشش پوست گورکن ها که بالای آن است و آویزان در خیمه جماعت را بر عهده خواهند داشت.\n۲۶. و دار زدن های حیاط، و دار زدن برای در دروازه حیاط که کنار خیمه و محراب اطراف است، و طناب هایشان، و همه ابزارهای خدمتشان و هر آنچه برایشان ساخته شده، چنین خدمت خواهند کرد.\n۲۷. در انتصاب هارون و پسرانش، تمام خدمات پسران گرشونیان، در همه بارهایشان و در همه خدمتشان، انجام خواهد شد و تو مسئول همه بارهایشان به آنان خواهی بود. {وقت ملاقات: عبری. دهان}\n۲۸. این خدمت خانواده های پسران گرشون در خیمه جماعت است؛ و مسئولیت آن ها به دست ایتامار پسر هارون کاهن خواهد بود.\n۲۹. اما پسران مراری، آن ها را بر اساس خانواده هایشان، به خانه پدرانشان بشمار؛\n۳۰. از سی سالگی و حتی به بالا تا پنجاه سالگی، هر کسی که وارد خدمت می شود، باید آن ها را بشماری تا کار خیمه جماعت را انجام دهد. {سرویس: عبری. جنگ}\n۳۱. و این بار بار آن هاست، بر اساس تمام خدمتشان در خیمه جماعت؛ تخته های خیمه و میله های آن، ستون های آن و حفره های آن،\n۳۲. و ستون های حیاط اطراف، و سوکت هایشان، و سنجاق ها و طناب هایشان، همراه با همه ابزارهایشان و با تمام خدماتشان؛ و به نام باید ابزارهای بار آن ها را حساب کنید.\n۳۳. این خدمت خانواده های پسران مراری است، بر اساس تمام خدماتشان، در خیمه جماعت، به دست ایتامار پسر هارون کشیش.\n۳۴. و موسی و هارون و رئیس جماعت، پسران کوهاثی را بر اساس خانواده هایشان و به نام خاندان پدرانشان شمارش کردند،\n۳۵. از سی سالگی و حتی به بالا تا پنجاه سالگی، هر کسی که وارد خدمت می شود، برای کار در خیمه جماعت:\n۳۶. و کسانی که خانواده هایشان شمارش می کردند، دو هزار و هفتصد و پنجاه بودند.\n۳۷. این ها کسانی بودند که از خانواده های کوحاتی شمارش می شدند، همه کسانی که می توانستند در خیمه جماعت خدمت کنند، که موسی و هارون طبق فرمان خداوند به دست موسی آن ها را شمارش کردند.\n۳۸. و کسانی که از پسران گرشون در سراسر خانواده هایشان و از خاندان پدران شان شمرده شده بودند،\n۳۹. از سی سالگی و حتی به بالا تا پنجاه سالگی، هر کسی که برای کار در خیمه جماعت وارد خدمت شود،\n۴۰. حتی کسانی که در خانواده هایشان به خاندان های پدرانشان شمارش شده بودند، دو هزار و ششصد و سی نفر بودند.\n۴۱. این ها کسانی هستند که از خانواده های پسران گرشون شمارش می شدند، از همه کسانی که در خیمه جماعت خدمت می کردند و موسی و هارون آن ها را طبق فرمان خداوند شمارش کردند.\n۴۲. و کسانی که از خانواده های پسران مراری بودند، در سراسر خانواده هایشان، بر اساس خاندان پدرانشان،\n۴۳. از سی سالگی و حتی به بالا تا پنجاه سالگی، هر کسی که برای کار در خیمه جماعت وارد خدمت شود،\n۴۴. حتی کسانی که به نام خانواده هایشان شمارش شده بودند، سه هزار و دویست نفر بودند.\n۴۵. این ها کسانی هستند که از خاندان های پسران مراری شمارش شده اند، کسانی که موسی و هارون آن ها را بر اساس کلام خداوند به دست موسی شمارش کردند.\n۴۶. همه کسانی که از لاویان شمش شده بودند، که موسی و هارون و رئیس اسرائیل آن ها را بر اساس خانواده هایشان و به نام خاندان پدرانشان شمرده می کردند،\n۴۷. از سی سالگی و حتی به بالا تا پنجاه سالگی، هر کسی که برای انجام خدمت خدمت و خدمت به بار در خیمه جماعت می آمد،\n۴۸. حتی کسانی که شمارش شدند، هشت هزار و پانصد و چهارصد و هشتاد بودند.\n۴۹. طبق فرمان خداوند، آن ها به دست موسی شماره گذاری شدند، هر یک بر اساس خدمتش و بر اساس بارش؛ بدین گونه که خداوند به موسی فرمان داده بود، از او شمرده شدند.","۱. و خداوند به موسی گفت و گفت:\n۲. به بنی اسرائیل فرمان بده که هر جذمی و هر کسی که فرزندی دارد و هر که توسط مردگان آلوده شده باشد، از اردوگاه بیرون کنند:\n۳. هم مرد و هم زن را بیرون کنید، بدون اردوگاه آن ها را بگذارید؛ که اردوگاه های خود را که در میان آن ها زندگی می کنم، آلوده نمی کنند.\n۴. و بنی اسرائیل این کار را کردند و آن ها را بدون اردوگاه بیرون کردند؛ چنان که خداوند به موسی گفت، بنی اسرائیل نیز چنین کردند.\n۵. و خداوند به موسی گفت:\n۶. به بنی اسرائیل سخن بگویید، وقتی مرد یا زنی مرتکب گناهی می شود که مردان مرتکب شده اند، به دلیل خطا در برابر خداوند و آن شخص گناهکار است؛\n۷. سپس گناه خود را اعتراف خواهند کرد و او گناه خود را با اصل آن جبران خواهد کرد و بخش پنجم آن را به آن اضافه خواهد کرد و آن را به کسی که به او تجاوز کرده خواهد داد.\n۸. اما اگر مرد خویشاوندی برای جبران خطا ندارد، گناه به خداوند جبران شود، {حتی} به کشیش؛ کنار بره کفاره، که با آن برای او کفاره داده خواهد شد.\n۹. و هر قربانی از همه چیزهای مقدس بنی اسرائیل که به کاهن می آورند، از آن او خواهد بود. {هدیه: یا، نذری را بالا بکش}\n۱۰. و امور مقدس هر انسان متعلق به او خواهد بود: هرچه کسی به کشیش بدهد، مال او خواهد بود.\n۱۱. و خداوند به موسی گفت:\n۱۲. با بنی اسرائیل سخن بگو و به آنان بگو: اگر زن مردی کنار رفت و به او تجاوز کرد،\n۱۳. و مردی با او رابطه جنسی داشته باشد و آن را از چشم شوهرش پنهان کند و نزدیک نگه داشته شود، و او آلوده شود و هیچ شاهدی علیه او نباشد، و نه با این رفتار گرفته شود؛\n۱۴. و روح حسادت بر او نازل شود و او به همسرش حسادت کند و او آلوده شود؛ یا اگر روح حسادت بر او نازل شود و به همسرش حسادت کند و او آلوده نشود:\n۱۵. سپس مرد همسرش را نزد کشیش می آورد و برای او نذری می آورد، دهمین قسمت یک افه آرد جو؛ بر آن روغن نریزد و کندر روی آن نگذارد؛ زیرا این {است} قربانی حسادت، قربانی یادبود است که گناه را به یادآوری می آورد.\n۱۶. و کشیش او را نزدیک خواهد آورد و در برابر خداوند قرار خواهد داد:\n۱۷. و کشیش آب مقدس را در ظرف خاکی می نوشد؛ و از گرد و خاکی که در کف خیمه است، کشیش آن را برمی دارد و در آب می ریزد:\n۱۸. و کشیش زن را پیش خداوند قرار می دهد و سر زن را برمی دارد و قربانی یادبود را در دستانش می گذارد که همان قربانی حسادت است؛ و کشیش آب تلخی که باعث نفرین می شود را در دست خواهد داشت:\n۱۹. و کشیش او را با سوگندی مأمور می کند و به زن می گوید: اگر هیچ مردی با تو نبوده و تو به جای شوهرت به ناپاکی نرفته ای، از این آب تلخ که نفرین را می آورد آزاد باش: {با دیگری...: یا اگر در اختیار شوهرت باشی:  عبری. زیر نظر شوهرت}\n۲۰. اما اگر به جای شوهرت به دیگری رفته باشی، و اگر آلوده شوی و مردی کنار شوهرت با تو خوابیده باشد:\n۲۱. سپس کشیش زن را به سوگند نفرین محکوم می کند و کشیش به زن می گوید: «خداوند تو را در میان مردمت نفرین و سوگند قرار دهد، وقتی خداوند رانت را پوسیده و شکمت را ورم می دهد؛ {rot: عبری. پاییز}\n۲۲. و این آبی که نفرین را می آورد، به روده هایت می رود تا شکمت را ورم کند و رانت را فاسد کند: و زن خواهد گفت: آمین، آمین.\n۲۳. و کشیش این نفرین ها را در کتابی خواهد نوشت و آن ها را با آب تلخ پاک خواهد کرد:\n۲۴. و زن را به آب تلخی که نفرین را می آورد می نوشد و آبی که نفرین را می آورد وارد او می شود و تلخ می گردد.\n۲۵. سپس کشیش قربانی حسادت را از دست زن برمی دارد و قربانی را در برابر خداوند تکان می دهد و بر محراب تقدیم می کند:\n۲۶. و کشیش باید مشت از قربانی را بردارد، حتی یادبود آن، و آن را بر محراب بسوزاند و سپس زن را وادار به نوشیدن آب کند.\n۲۷. و زمانی که او را وادار کرد آب را بنوشد، آن وقت خواهد بود که اگر او آلوده شود و به شوهرش تجاوز کند، آبی که نفرین را ایجاد می کند وارد او شود، تلخ گردد، شکمش ورم کند و رانش پوسیده شود؛ و زن در میان قومش نفرین خواهد شد.\n۲۸. و اگر زن آلوده نشود، بلکه پاک باشد؛ آنگاه آزاد خواهد شد و باردار خواهد شد.\n۲۹. این {است} قانون حسادت است، زمانی که زن به جای شوهرش به سوی دیگری می رود و آلوده می شود؛\n۳۰. یا وقتی روح حسادت بر او نازل شود و او به همسرش حسادت کند، زن را پیش خداوند قرار دهد و کشیش همه این قوانین را بر او اجرا کند.\n۳۱. آنگاه مرد از گناه بی گناه خواهد بود و این زن گناه خود را تحمل خواهد کرد.","۱. و خداوند به موسی گفت و گفت:\n۲. با بنی اسرائیل سخن بگو و به آنان بگو: وقتی مرد یا زن از هم جدا شوند تا سوگند یک ناصری را بخورند، خودشان را به خداوند جدا کنند: {جدا شوند...: یا خود را ناصری کنند}\n۳. او باید خود را از شراب و نوشیدنی قوی جدا کند و نباید سرکه شراب یا سرکه نوشیدنی قوی بنوشد، نه مشروب انگور بنوشد، نه انگور مرطوب یا خشک بخورد.\n۴. در تمام روزهای جدایی اش، هیچ چیزی از درخت تاک نخواهد خورد، از دانه ها تا پوسته. {جدایی: یا، ناصریه} {vine...: عبری. تاک شراب}\n۵. در تمام روزهای عهد جدایی، تیغی بر سرش نخواهد افتاد: تا زمانی که روزهایی که در آن خود را از خداوند جدا می کند، کامل نشود، مقدس خواهد بود و موهای سرش رشد خواهد کرد.\n۶. در تمام روزهایی که خود را از خداوند جدا می کند، به جسد نخواهد رسید.\n۷. او نباید خود را برای پدرش، یا مادرش، برادرش یا خواهرش هنگام مرگ ناپاک کند: زیرا تقدیس خدای او بر سرش است. {تقدیس: عبری. جدایی}\n۸. در تمام روزهای جدایی اش، او نزد خداوند مقدس است.\n۹. و اگر کسی ناگهان توسط او بمیرد و سر تقدیس خود را آلوده کرده باشد؛ سپس در روز تطهیر سرش را خواهد تراشید و در روز هفتم آن را خواهد تراشید.\n۱۰. و در روز هشتم، دو لاک پشت یا دو کبوتر جوان را به کشیش و در خیمه جماعت خواهد آورد:\n۱۱. و کشیش یکی را به عنوان قربانی گناه و دیگری را به عنوان قربانی سوختنی تقدیم می کند و برای او کفاره می دهد، به خاطر گناهی که توسط مردگان مرتکب شده، و همان روز سرش را مقدس می کند.\n۱۲. و او روزهای جدایی خود را به خداوند وقف خواهد کرد و بره ای از سال اول را برای قربانی تجاوز خواهد آورد؛ اما روزهای پیشین از دست خواهد رفت، زیرا جدایی او آلوده شده است. {گم شو: عبری. پاییز}\n۱۳. و این قانون ناصری است، وقتی روزهای جدایی اش به پایان برسد: او را به دروازه خیمه جماعت برده می کنند:\n۱۴. و قربانی خود را به خداوند تقدیم خواهد کرد، یکی بره سال اول بی عیب برای قربانی سوختن، و یک بره میش سال اول بی عیب برای قربانی گناه، و یک قوچ بی عیب برای نذورات صلح،\n۱۵. و سبدی از نان بدون خمیرما، کیک های آرد مرغوب مخلوط با روغن، و ویفرهای نان بدون خمیر که با روغن مسح شده اند، و نذورات گوشتی شان و نذورات نوشیدنی هایشان.\n۱۶. و کاهن آنان را نزد خداوند خواهد آورد و قربانی گناه و قربانی سوختنی خود را تقدیم خواهد کرد:\n۱۷. و او قوچ را قربانی صلح به خداوند خواهد کرد، همراه با سبد نان بی خمیرمایی؛ کشیش نیز قربانی گوشت و نوشیدنی خود را تقدیم خواهد کرد.\n۱۸. و ناصری سر جدایی خود را {در در} خیمه جماعت تراشید و موی سر جدایی خود را برداشته و آن را در آتشی که زیر قربانی نذورات صلح است می اندازد.\n۱۹. و کشیش شانه خیس قوچ و یک کیک خمیرمایه از سبد و یک ویفر بدون خمیر را برمی دارد و پس از تراشیدن موی جدایی ناصر، آن ها را بر دستان ناصری می گذارد:\n۲۰. و کاهن آن ها را برای قربانی تکان دادن در برابر خداوند تکان خواهد داد: این برای کاهن مقدس است، با سینه موج دار و شانه بلند شده؛ و پس از آن ناصری ها شراب می نوشند.\n۲۱. این {قانون} ناصری است که سوگند خورده است، {و نذر} خود را به خداوند برای جدایی اش داده است، علاوه بر {آن} که دستش خواهد گرفت: طبق نذری که خورده است، پس از قانون جدایی باید انجام دهد.\n۲۲. و خداوند به موسی گفت:\n۲۳. به هارون و پسرانش بگو و بگو: به این حکمت بنی اسرائیل را برکت بده و به آنان بگو:\n۲۴. خداوند تو را برکت دهد و حفظ کند:\n۲۵. خداوند چهره اش را بر تو بتاباند و بر تو بخشنده باشد:\n۲۶. خداوند چهره اش را بر تو بلند کند و به تو آرامش دهد.\n۲۷. و نام مرا بر بنی اسرائیل خواهند گذاشت؛ و من آن ها را برکت خواهم داد.","۱. و این اتفاق در روزی رخ داد که موسی خیمه را کاملا برپا کرد، آن را مسح کرد و تقدیس نمود و همه وسایلش، هم محراب و هم تمام ظروف آن، و آن ها را مسح کرد و تقدیس نمود؛\n۲. که شاهزادگان اسرائیل، رؤسای خاندان پدرانشان، که شاهزادگان قبایل بودند و بر آنان که شمارش شده بودند پایبند بودند، پیشنهاد دادند: {و بودند: عبری. چه کسی ایستاده بود}\n۳. و آن ها قربانی خود را نزد خداوند آوردند، شش ارابه پوشیده و دوازده گاو؛ یک ارابه برای دو شاهزاده و برای هر کدام یک گاو؛ و آن ها را به پیش خیمه آوردند.\n۴. و خداوند به موسی گفت:\n۵. از آن ها بگیر تا بتوانند در عبادت خیمه جماعت شرکت کنند؛ و آن ها را به لاویان و هر مرد به اندازه خدمتش بده.\n۶. و موسی ارابه ها و گاوها را برداشت و به لاویان داد.\n۷. دو ارابه و چهار گاو نر را به پسران گرشون داد، بر اساس خدمتشان:\n۸. و چهار ارابه و هشت گاو را به فرزندان مراری داد، طبق خدمتشان، به دست ایتامار پسر هارون کاهن.\n۹. اما به پسران کوهات چیزی نداد، زیرا خدمت مقدس متعلق به آنان این بود که باید بر دوش خود بگذارند.\n۱۰. و شاهزادگان برای وقف محراب در روزی که مسح شد، پیشنهاد دادند، حتی شاهزادگان نیز نذری خود را در برابر محراب تقدیم کردند.\n۱۱. و خداوند به موسی گفت: هر شاهزاده در روز خود، قربانی خود را برای وقف محراب تقدیم خواهد کرد.\n۱۲. و کسی که روز اول قربانی خود را تقدیم کرد، نحشون پسر امیناداب از قبیله یهودا بود:\n۱۳. و نذری اش یک کاسه نقره ای بود، وزن آن صد و سی شکل، یک کاسه نقره ای هفتاد شکل، پس از شکل حرم؛ هر دوی آن ها پر از آرد مرغوب مخلوط با روغن برای نذری گوشت بودند:\n۱۴. یک قاشق ده شکل طلا، پر از عود:\n۱۵. یک گاو نر جوان، یک قوچ، یک بره سال اول، برای قربانی سوخته:\n۱۶. یک بچه بز برای قربانی گناه:\n۱۷. و برای قربانی صلح، دو گاو، پنج قوچ، پنج بز، پنج بره سال اول: این نذر ناحشون پسر امیناداب بود.\n۱۸. در روز دوم، نتانئیل پسر زوار، شاهزاده یساکار، ارائه داد:\n۱۹. او به ازای نذر خود یک کاسه نقره ای به وزن آن صد و سی شکل، یک کاسه نقره ای هفتاد شکل، پس از شکل مقدس تقدیم کرد؛ هر دو پر از آرد ریز مخلوط شده با روغن برای نذری گوشت:\n۲۰. یک قاشق طلا ده شکل، پر از عود:\n۲۱. یک گاو نر جوان، یک قوچ، یک بره سال اول، برای قربانی سوخته:\n۲۲. یک بچه بز برای قربانی گناه:\n۲۳. و برای قربانی صلح، دو گاو، پنج قوچ، پنج بز، پنج بره سال اول: این نذر نتانیل پسر زوار بود.\n۲۴. در روز سوم، الیاب پسر حلون، شاهزاده فرزندان زبولون، {پیشنهاد داد}:\n۲۵. نذری او یک کاسه نقره ای بود که وزنش صد و سی شکل، یک کاسه نقره ای هفتاد شکل، پس از شکل حرم؛ هر دو پر از آرد ریز مخلوط شده با روغن برای نذری گوشت:\n۲۶. یک قاشق طلایی ده شکل، پر از عود:\n۲۷. یک گاو نر جوان، یک قوچ، یک بره سال اول، برای قربانی سوخته:\n۲۸. یک بچه بز برای قربانی گناه:\n۲۹. و برای قربانی صلح، دو گاو، پنج قوچ، پنج بز، پنج بره سال اول: این نذر الیاب پسر حلون بود.\n۳۰. در روز چهارم، الیزور پسر شدور، شاهزاده فرزندان روبن، {پیشنهاد داد}:\n۳۱. نذری او یک کاسه نقره ای به وزن صد و سی شکل، یک کاسه نقره ای هفتاد شکل، پس از شکل مقدس بود؛ هر دو پر از آرد ریز مخلوط شده با روغن برای نذری گوشت:\n۳۲. یک قاشق طلایی ده شکل، پر از عود:\n۳۳. یک گاو نر جوان، یک قوچ، یک بره سال اول، برای قربانی سوخته:\n۳۴. یک بچه بز برای قربانی گناه:\n۳۵. و برای قربانی صلح، دو گاو، پنج قوچ، پنج بز، پنج بره سال اول: این نذر الیزور پسر شدور بود.\n۳۶. در روز پنجم، شلومیئل، پسر زوری شادای، شاهزاده فرزندان شمئون، {پیشنهاد داد}:\n۳۷. نذری او یک قاشق نقره ای بود که وزنش صد و سی شکل، یک کاسه نقره ای هفتاد شکل، پس از شکل حرم؛ هر دو پر از آرد ریز مخلوط شده با روغن برای نذری گوشت:\n۳۸. یک قاشق طلایی ده شکل، پر از بخور:\n۳۹. یک گاو نر جوان، یک قوچ، یک بره سال اول، برای قربانی سوخته:\n۴۰. یک بچه بز برای قربانی گناه:\n۴۱. و برای قربانی صلح، دو گاو، پنج قوچ، پنج بز، پنج بره سال اول: این قربانی شلومیئل پسر زوریشادای بود.\n۴۲. در روز ششم، الیاساف پسر دویل، شاهزاده فرزندان گاد، {تقدیم کرد}:\n۴۳. قربانی او {بود} یک کاسه نقره ای به وزن صد و سی شکل}، یک کاسه نقره ای هفتاد شکل، پس از شکل حرم؛ هر دو پر از آرد ریز مخلوط شده با روغن برای نذری گوشت:\n۴۴. یک قاشق طلایی ده شکل، پر از عود:\n۴۵. یک گاو نر جوان، یک قوچ، یک بره سال اول، برای قربانی سوخته:\n۴۶. یک بچه بز برای قربانی گناه:\n۴۷. و برای قربانی صلح، دو گاو، پنج قوچ، پنج بز، پنج بره سال اول: این نذر الیاساف پسر دوئل بود.\n۴۸. در روز هفتم، الیشامه پسر امیهود، شاهزاده فرزندان افرایم، {تقدیم شد}:\n۴۹. قربانی او {بود} یک بار نقره ای به وزن {صد} و سی شکل}، یک کاسه نقره ای هفتاد شکل، پس از شکل حرم؛ هر دو پر از آرد ریز مخلوط شده با روغن برای نذری گوشت:\n۵۰. یک قاشق طلایی ده شکل، پر از عود:\n۵۱. یک گاو نر جوان، یک قوچ، یک بره سال اول، برای قربانی سوخته:\n۵۲. یک بچه بز برای قربانی گناه:\n۵۳. و برای قربانی صلح، دو گاو، پنج قوچ، پنج بز، پنج بره سال اول: این قربانی الیشامه پسر امیهود بود.\n۵۴. در روز هشتم، جمالئیل پسر پدازور، شاهزاده فرزندان منسی، را تقدیم کرد:\n۵۵. نذر او {بود} یک سکه نقره ای به وزن صد و سی شکل، یک کاسه نقره ای هفتاد شکل، پس از شکل حرم؛ هر دو پر از آرد ریز مخلوط شده با روغن برای نذری گوشت:\n۵۶. یک قاشق طلایی ده شکل، پر از بخور:\n۵۷. یک گاو نر جوان، یک قوچ، یک بره سال اول، برای قربانی سوخته:\n۵۸. یک بچه بز برای قربانی گناه:\n۵۹. و برای قربانی صلح، دو گاو، پنج قوچ، پنج بز، پنج بره سال اول: این {بود} قربانی گمالیئل پسر پداهزور.\n۶۰. در روز نهم، ابیدان، پسر جدعونی، شاهزاده فرزندان بنیامین، {تقدیم کرد}:\n۶۱. قربانی او {بود} یک بار نقره ای به وزن آن صد و سی شکل، یک کاسه نقره ای هفتاد شکل، پس از شکل حرم؛ هر دو پر از آرد ریز مخلوط شده با روغن برای نذری گوشت:\n۶۲. یک قاشق طلایی ده شکل، پر از عود:\n۶۳. یک گاو نر جوان، یک قوچ، یک بره سال اول، برای قربانی سوخته:\n۶۴. یک بچه بز برای قربانی گناه:\n۶۵. و برای قربانی صلح، دو گاو، پنج قوچ، پنج بز، پنج بره سال اول: این قربانی ابیدان پسر جدعونی بود.\n۶۶. در روز دهم، آهیزر پسر امیشادای، شاهزاده فرزندان دان، {تقدیم شد}:\n۶۷. نذری او یک قاشق نقره ای بود که وزنش صد و سی شکل، یک کاسه نقره ای هفتاد شکل، پس از شکل حرم؛ هر دو پر از آرد ریز مخلوط شده با روغن برای نذری گوشت:\n۶۸. یک قاشق طلایی ده شکل، پر از بخور:\n۶۹. یک گاو نر جوان، یک قوچ، یک بره سال اول، برای قربانی سوخته:\n۷۰. یک بچه بز برای قربانی گناه:\n۷۱. و برای قربانی صلح، دو گاو، پنج قوچ، پنج بز، پنج بره سال اول: این قربانی آهیعزر پسر امیشادایی بود.\n۷۲. در روز یازدهم، پاگیل، پسر اوکران، شاهزاده فرزندان آشر، {تقدیم کرد}:\n۷۳. قربانی او یک کاسه نقره ای بود که وزنش صد و سی شکل، یک کاسه نقره ای هفتاد شکل، پس از شکل حرم؛ هر دو پر از آرد ریز مخلوط شده با روغن برای نذری گوشت:\n۷۴. یک قاشق طلایی ده شکل، پر از بخور:\n۷۵. یک گاو نر جوان، یک قوچ، یک بره سال اول، برای قربانی سوخته:\n۷۶. یک بچه بز برای قربانی گناه:\n۷۷. و برای قربانی صلح، دو گاو، پنج قوچ، پنج بز، پنج بره سال اول: این {بود} نذر پاگیل پسر اوکران.\n۷۸. در روز دوازدهم، آهیرا پسر عنان، شاهزاده فرزندان نفتالی، {تقدیم شد}:\n۷۹. نذری او یک کاسه نقره ای بود که وزنش صد و سی شکل، یک کاسه نقره ای هفتاد شکل، پس از شکل حرم؛ هر دو پر از آرد ریز مخلوط شده با روغن برای نذری گوشت:\n۸۰. یک قاشق طلایی ده شکل، پر از بخور:\n۸۱. یک گاو نر جوان، یک قوچ، یک بره سال اول، برای قربانی سوخته:\n۸۲. یک بچه بز برای قربانی گناه:\n۸۳. و برای قربانی صلح، دو گاو، پنج قوچ، پنج بز، پنج بره سال اول: این {بود} قربانی آهیرا پسر عنان.\n۸۴. این وقف محراب بود، در روزی که توسط شاهزادگان اسرائیل مسح شد: دوازده کاسه نقره، دوازده کاسه نقره ای، دوازده قاشق طلا:\n۸۵. هر ظرف نقره {وزن} صد و سی شکل}، هر کاسه هفتاد: تمام ظروف نقره {وزن} دو هزار و چهارصد {شکل}، پس از شکل عبادت:\n۸۶. قاشق های طلایی دوازده بودند، پر از عود، هر کدام ده شکل، بر اساس شکل حرم: تمام طلای قاشق ها معادل صد و بیست شکل.\n۸۷. همه گاوهای قربانی سوختنی دوازده گاو، قوچ ها دوازده، بره های سال اول دوازده با قربانی گوشتشان؛ و بچه های بزها برای قربانی گناه دوازده تا.\n۸۸. و همه گاوهای قربانی صلح بیست و چهار گاو، قوچ ها شصت، بزها شصت و بره های سال اول شصت بودند. این {بود} وقف محراب بود و پس از آن مسح شد.\n۸۹. و زمانی که موسی به خیمه جماعت رفت تا با او صحبت کند، صدای کسی را شنید که از جایگاه رحمت که بر تابوت شهادت بود، میان دو کروبی با او سخن می گفت: و با او سخن گفت. {با او: یعنی با خدا}","۱. و خداوند به موسی گفت و گفت:\n۲. با هارون سخن بگو و به او بگو: وقتی چراغ ها را روشن می کنی، هفت چراغ در برابر شمعدان روشن می شوند.\n۳. و هارون چنین کرد؛ او چراغ های آن را بر شمعدان روشن کرد، همان طور که خداوند به موسی فرمان داده بود.\n۴. و این کار شمعدان از طلای کوبیده شده بود، تا ساقه آن، تا گل های آن، کار کوبیده شده بود: طبق الگویی که خداوند به موسی نشان داده بود، شمعدان را ساخت.\n۵. و خداوند به موسی گفت:\n۶. لاویان را از میان بنی اسرائیل بردار و آن ها را پاک کن.\n۷. و این گونه با آنان انجام خواهی داد تا آن ها را پاک کنی: آب تطهیرکننده بر آن ها بپاشید و بگذار تمام گوشت خود را بتراشند، بگذار لباس هایشان را بشویند و خود را پاک کنند. {بگذارید اصلاح کنند...: عبری. بگذارید باعث عبور تیغ شوند و غیره}\n۸. پس بگذار یک گاو نر جوان را با نذری گوشتش ببرند، {حتی} آرد مرغوب مخلوط با روغن، و یک گاو نر جوان دیگر را به عنوان قربانی گناه بپذیری.\n۹. و لاویان را به خیمه جماعت بیاور، و همه مجمع بنی اسرائیل را گرد هم آورد:\n۱۰. و لاویان را نزد خداوند خواهی آورد و بنی اسرائیل دست بر لاویان خواهند گذاشت:\n۱۱. و هارون لاویان را پیش خداوند تقدیم خواهد کرد {برا} قربانی بنی اسرائیل تا بتوانند خدمت خداوند را انجام دهند. {پیشنهاد: عبری. دست تکان دادن} {پیشنهاد: عبری. تقدیم تکان دادن} {آن ها...: عبری. ممکن است برای اجرا و غیره باشد}\n۱۲. و لاویان دست خود را بر سر گاوها خواهند گذاشت و تو یکی را به عنوان قربانی گناه و دیگری را قربانی سوختن به خداوند خواهی داد تا برای لاویان کفاره دهد.\n۱۳. و لاویان را پیش هارون و پسرانش قرار می دهی و آن ها را به عنوان قربانی به خداوند تقدیم می کنی.\n۱۴. بدین گونه لاویان را از میان بنی اسرائیل جدا خواهی کرد و لاویان از آن من خواهند بود.\n۱۵. و پس از آن، لاویان وارد خواهند شد تا مراسم خیمه جماعت را انجام دهند؛ و تو آنان را پاک کن و به عنوان قربانی تقدیم خواهی کرد.\n۱۶. زیرا آن ها کاملا از میان بنی اسرائیل به من داده شده اند؛ به جای آن هایی که هر رحم را باز کنند، {حتی} نخستین فرزند همه فرزندان اسرائیل، آن ها را نزد خود برده ام.\n۱۷. زیرا همه نخستین فرزندان بنی اسرائیل از آن من هستند، هم انسان و هم حیوان: در روزی که هر نخست زاده ای را در سرزمین مصر زدم، آن ها را برای خود تقدیس کردم.\n۱۸. و من لاویان را برای همه نخستین فرزندان بنی اسرائیل پذیرفته ام.\n۱۹. و من به لاویان هدیه ای به هارون و پسرانش از میان بنی اسرائیل داده ام تا در خیمه جماعت به بنی اسرائیل خدمت کنند و برای بنی اسرائیل کفاره دهند، تا در میان بنی اسرائیل بلایی نیفتد،  وقتی بنی اسرائیل به حرم نزدیک می شوند. {یک هدیه: عبری. داده شده}\n۲۰. و موسی و هارون و همه جماعت بنی اسرائیل، طبق آنچه خداوند به موسی درباره لاویان فرمان داده بود، با لاویان چنین کردند.\n۲۱. و لاویان پاک شدند و لباس های خود را شستند؛ و هارون آن ها را به عنوان قربانی در برابر خداوند تقدیم کرد؛ و هارون برای آن ها کفاره داد تا آن ها را پاک کند.\n۲۲. و پس از آن، لاویان برای انجام خدمت در خیمه جماعت در برابر هارون و پیش از پسرانش وارد شدند؛ همان گونه که خداوند به موسی درباره لاویان فرمان داده بود، آنان نیز به آنان دستور دادند.\n۲۳. و خداوند به موسی گفت:\n۲۴. این {است} که {متعلق است} به لاویان است: از بیست و پنج سالگی به بالا وارد خواهند شد تا در خدمت در خیمه جماعت منتظر بمانند: {به...: عبرانی. برای جنگ، جنگ و غیره}\n۲۵. و از سن پنجاه سالگی دیگر منتظر خدمت نخواهند بود و دیگر خدمت نخواهند کرد: {تمام...: عبرانی. بازگشت از جنگ خدمت}\n۲۶. اما باید با برادران خود در خیمه جماعت خدمت کنند تا مسئولیت را حفظ کنند و هیچ خدمتی انجام ندهند. چنین خواهی کرد تا لاویان را که به آن ها دست می زنند، بپذیری.","۱. و خداوند در بیابان سینا، در ماه اول سال دوم پس از خروج از سرزمین مصر، به موسی گفت:\n۲. بگذار فرزندان اسرائیل نیز عید فصح را در زمان مقرر او برگزار کنند.\n۳. در چهاردهم روز این ماه، در حس، آن را در زمان مقرر خود نگه دارید: مطابق با تمام آیین ها و همه آیین های آن، آن را رعایت کنید. {در حفت: عبری. بین دو شب}\n۴. و موسی به بنی اسرائیل گفت که باید عید فصح را حفظ کنند.\n۵. و عید فصح را در روز چهاردهم ماه اول حتی در بیابان سینا برگزار کردند: طبق همه آنچه خداوند به موسی فرمان داده بود، بنی اسرائیل نیز چنین کردند.\n۶. و مردانی بودند که توسط جسد مرده ای آلوده شده بودند و نتوانستند در آن روز عید فصح را برگزار کنند؛ و آن روز پیش موسی و هارون آمدند:\n۷. و آن مردان به او گفتند: ما به خاطر جسد مرده یک انسان آلوده شده ایم: چرا ما را نگه داشته اند تا نتوانیم قربانی خداوند را در زمان مقرر او در میان بنی اسرائیل تقدیم کنیم؟\n۸. و موسی به آنان گفت: «بی حرکت بمانید و من خواهم شنید که خداوند دربارهٔ شما چه فرمان خواهد داد.»\n۹. و خداوند به موسی گفت:\n۱۰. به بنی اسرائیل بگویید و بگویید: اگر هر یک از شما یا نسل های شما به خاطر جسد ناپاک شود یا در سفری دور باشد، پسح را نزد خداوند نگه دارد.\n11. روز چهاردهم ماه دوم حتی آن را نگه دارند و با نان بدون خمیر و سبزیجات تلخ می خورند.\n۱۲. هیچ کدام از آن را تا صبح نگذارند و هیچ استخوانی از آن را بشکنند؛ طبق همه مقررات عید فصح آن را نگه دارند.\n۱۳. اما مردی که پاک است و در سفر نیست و از حفظ عید فصح خودداری کند، همان جان از میان قومش قطع خواهد شد: زیرا قربانی خداوند را در زمان مقرر خود نیاورد، آن انسان گناه خود را خواهد پذیرفت.\n۱۴. و اگر غریبه ای در میان شما اقامت کند و عید فصح را نزد خداوند برگزار کند؛ طبق آیین عید فصح و نحوه آن، چنین خواهد بود: شما یک فرمان خواهید داشت، هم برای غریبه و هم برای کسی که در سرزمین به دنیا آمده است.\n۱۵. و در روزی که خیمه مقدس برپا شد، ابر خیمه را پوشاند، یعنی خیمه شهادت؛ و حتی بر خیمه مانند آتش ظاهر می شد، تا صبح.\n۱۶. همیشه همین طور بود: ابر آن را {در روز} پوشانده بود و شب ها آتش ظاهر می شد.\n۱۷. و وقتی ابر از خیمه برداشته شد، پس از آن بنی اسرائیل حرکت کردند؛ و در جایی که ابر استقرار داشت، بنی اسرائیل خیمه های خود را برپا کردند.\n۱۸. به فرمان خداوند، فرزندان اسرائیل سفر کردند و به فرمان خداوند برپا شدند: تا زمانی که ابر بر خیمه نشین بود، در چادرهای خود استراحت کردند.\n۱۹. و زمانی که ابر روزهای زیادی بر خیمه نشین ماند، آنگاه بنی اسرائیل مسئولیت خداوند را حفظ کردند و سفر نکردند. {تأخیر...: عبری. طولانی}\n۲۰. و {همین} بود، وقتی ابر چند روزی بر تابوت بود؛ طبق فرمان خداوند در چادرهای خود اقامت داشتند و طبق فرمان خداوند سفر کردند.\n۲۱. و چنین بود، وقتی ابر از صبح تا صبح باقی ماند و صبح ابر برداشته شد، سپس سفر کردند؛ چه در روز و چه در شب که ابر برداشته می شد، سفر می کردند. {اقامت: عبری. بود}\n۲۲. یا چه دو روز، یا یک ماه، یا یک سال، که ابر بر خیمه باقی ماند و در آنجا ماندند، بنی اسرائیل در چادرهای خود ماندند و سفر نکردند؛ اما وقتی ابر برداشته شد، حرکت کردند.\n۲۳. به فرمان خداوند در چادرها آرام گرفتند و به فرمان خداوند سفر کردند: آنها مسئولیت خداوند را نگه داشتند، به فرمان خداوند به دست موسی.","۱. و خداوند به موسی گفت و گفت:\n۲. دو شیپور نقره ای بساز؛ از یک قطعه کامل آن ها را بسازی: تا بتوانی از آن ها برای دعوت مجمع و سفر اردوگاه ها استفاده کنی.\n۳. و زمانی که با آن ها فوت می کنند، همه جماعت در دروازه خیمه جماعت به سوی تو جمع می شوند.\n۴. و اگر با یک {شیپور} بنوازند، شاهزادگان {که سران هزاران اسرائیل} هستند، به سوی تو جمع خواهند شد.\n۵. وقتی زنگ خطر را به صدا درآوردید، اردوگاه هایی که در بخش شرقی قرار دارند باید به جلو حرکت کنند.\n۶. وقتی بار دوم زنگ خطر را به صدا درآوردید، اردوگاه هایی که در سمت جنوب قرار دارند سفر خود را آغاز می کنند: آن ها برای سفرهایشان زنگ خطر به صدا درمی آورند.\n۷. اما وقتی جماعت جمع می شود، باید زنگ بزنی اما نباید هشدار بده.\n۸. و پسران هارون، کاهنان، با شیپورها خواهند نواخت؛ و آن ها برای شما به عنوان یک مأمور برای نسل های شما خواهند بود.\n۹. و اگر در سرزمین خود علیه دشمنی که شما را ظلم می کند به جنگ بروید، با شیپورها زنگ خطر را به صدا درآورید؛ و در برابر خداوند خدای خود به یاد آورده خواهید شد و از دشمنانتان نجات خواهید یافت.\n۱۰. همچنین در روز شادی و روزهای باشکوه و در آغاز ماه هایت، با شیپورها بر قربانی های سوختنی و قربانی های صلح خود بکوبید؛ تا برای یادبودی در برابر خدای شما باشد: من {هستم} خداوند خدای شما.\n۱۱. و در روز بیستم ماه دوم، سال دوم، ابر از خیمه شهادت برداشته شد.\n۱۲. و بنی اسرائیل سفرهای خود را از بیابان سینا آغاز کردند؛ و ابرها در بیابان پاران آرام گرفته بودند.\n۱۳. و نخستین بار طبق فرمان خداوند به دست موسی سفر کردند.\n۱۴. در ابتدا پرچم اردوگاه فرزندان یهودا بر اساس لشکرهایشان قرار گرفت و بر لشکر او ناحشون پسر امیناداب قرار داشت.\n۱۵. و بر لشکر قبیله فرزندان یساکار {بود} نتانئیل پسر زوار.\n۱۶. و بر لشکر قبیله فرزندان زبولون، الیاب پسر حلون بود.\n۱۷. و خیمه مقدس پایین آورده شد؛ و پسران گرشون و پسران مراری با تابناک به جلو رفتند.\n۱۸. و پرچم اردوگاه روبن مطابق لشکرهایشان پیش رفت؛ و بر لشکرش الیزور پسر شدیور قرار داشت.\n۱۹. و بر لشکر قبیله فرزندان سیمئون {شلومیئل} پسر زوریشادای بود.\n۲۰. و بر لشکر قبیله فرزندان گاد، الیاساف، پسر دوئل بود.\n۲۱. و کوحاتی ها با بردن حرم پیش رفتند؛ و {دیگری} خیمه را در برابر آمدن برپا کردند. {دیگری: یعنی گرشونی ها و مراری ها}\n۲۲. و پرچم اردوگاه فرزندان افرایم بر اساس لشکریانشان قرار گرفت؛ و بر لشکرش الیشمه پسر امیهود قرار داشت.\n۲۳. و بر لشکر قبیله فرزندان منسی، جمالئیل پسر پدازور بود.\n۲۴. و بر لشکر قبیله فرزندان بنیامین {بود} عابدان، پسر جدعونی.\n۲۵. و پرچم اردوگاه فرزندان دان به جلو گذاشته شد که پاداش همه اردوگاه ها در سراسر لشکرهایشان بود؛ و بر لشکرش آحیزر پسر امیشادای بود.\n۲۶. و بر لشکر قبیله فرزندان آشر، پاگیل پسر اوکران بود.\n۲۷. و بر لشکر قبیله فرزندان نفتالی {بود} آهیرا، پسر عنان.\n۲۸. چنین بود سفرهای بنی اسرائیل بر اساس سپاه هایشان هنگام پیشروی آن. {پس: عبری. این ها}\n۲۹. و موسی به حباب، پسر راگوئیل مدیانی، پدر شوهر موسی گفت: «ما به سوی جایی که خداوند فرمود سفر می کنیم، آن را به تو خواهم داد: با ما بیا و به تو نیکی خواهیم کرد؛ زیرا خداوند درباره اسرائیل نیکی گفته است.»\n۳۰. و به او گفت: من نمی روم؛ اما من به سرزمین خودم و به خویشاوندانم خواهم رفت.\n۳۱. و او گفت: «ما را رها نکن، از تو می خواهم؛ زیرا می دانی چگونه باید در بیابان اردو بزنیم، و شاید تو برای ما باشی نه چشم ها.\n۳۲. و اگر با ما بروی، بله، همان نیکی خواهد بود که خداوند با ما خواهد کرد، همان نیکی را که ما با تو خواهیم کرد.\n۳۳. و آن ها از کوه خداوند سه روز راه رفتند؛ و تابوت عهد خداوند در این سه روز پیش از آنان آمد تا جای آرامشی برایشان بیابد.\n۳۴. و ابر خداوند روزها بر آن ها بود، وقتی از اردوگاه بیرون می رفتند.\n۳۵. و زمانی که تابوت به جلو آمد، موسی گفت: ای خداوند، برخیز و دشمنانت را پراکنده کن؛ و بگذار کسانی که از تو نفرت دارند پیش تو فرار کنند.\n۳۶. و وقتی آرام گرفت، گفت: «بازگرد، ای خداوند، به هزاران اسرائیل. {هزاران نفر: عبری. ده هزار هزار}","۱. و {وقتی} مردم شکایت کردند، خداوند را خشمگین کرد؛ و خداوند آن را شنید؛ و خشمش شعله ور شد؛ و آتش خداوند در میان آنان سوخت و {کسانی که بودند} را در دورترین نقاط اردوگاه سوزاند. {شکایت: یا، به نوعی شکایت کننده بودند} {ناراضی است: عبری. در گوش ها، شرارت بود\n۲. و مردم به موسی فریاد زدند؛ و وقتی موسی به خداوند دعا کرد، آتش خاموش شد. {بود...: عبری. غرق شد}\n۳. و نام این مکان را نامید: زیرا آتش خداوند در میان آن ها می سوخت. {تبره: یعنی، آ سوختن}\n۴. و جمعیت مختلط که در میان آن ها بود، هوس کردند؛ و بنی اسرائیل نیز دوباره گریه کردند و گفتند: چه کسی به ما گوشت می دهد تا بخوریم؟ {افتاد...: عبری. هوس داشت} {گریس...: عبری. بازگشت و گریست}\n۵. ماهی را به یاد می آوریم که در مصر آزادانه می خوردیم؛ خیارها، خربزه ها، تره فرنگی، پیازها و سیرها:\n۶. اما اکنون روح ما {خشکی} شده است: {هیچ چیز} جز این مانا، {در برابر چشمان} ما نیست.\n۷. و مانا {بود} مانند دانه گشنیز و رنگ آن به رنگ بدلیوم. {رنگ آن...: عبری. چشم آن به عنوان چشم\n۸. و مردم دور می زدند، آن را جمع می کردند و در آسیاب ها آسیاب می کردند، یا در هاون می زدند و در ماهیتابه ها می پختند و کیک می ساختند؛ و طعمش مانند طعم روغن تازه بود.\n۹. و وقتی شبنم شب بر اردوگاه می بارید، مانا بر آن می بارید.\n۱۰. سپس موسی شنید که مردم در سراسر خانواده هایشان گریه می کردند، هر مردی در در چادرش؛ و خشم خداوند به شدت شعله ور شد؛ موسی نیز ناراضی بود.\n۱۱. و موسی به خداوند گفت: چرا بنده ات را آزار دادی؟ و چرا در نظر تو لطف نیافتم که بار همه این مردم را بر دوش من می گذاری؟\n۱۲. آیا من همه این افراد را باردار شده ام؟ آیا من آن ها را به دنیا آورده ام که به من بگویی: «آن ها را در آغوش خود حمل کن، همان گونه که پدری شیرخوار کودک شیرده را به دنیا می آورد، به سرزمینی که تو به پدرانشان بخشیده ای؟»\n۱۳. از کجا باید گوشت داشته باشم تا به همه این مردم بدهم؟ زیرا آن ها به من گریه می کنند و می گویند: به ما گوشت بده تا بخوریم.\n۱۴. من نمی توانم این همه آدم را به تنهایی تحمل کنم، چون {این} برای من خیلی سنگین است.\n۱۵. و اگر چنین با من رفتار کردی، مرا بکش، از تو خواهش می کنم، اگر نزد تو لطف یافته ام؛ و نگذار بدبختی ام را ببینم.\n۱۶. و خداوند به موسی گفت: هفتاد مرد از بزرگان اسرائیل را که می دانی بزرگان قوم و فرماندهان آنان هستند، برای من جمع کن؛ و آن ها را به خیمه جماعت بیاور، تا آنجا با تو بایستند.\n۱۷. و من پایین می آیم و آنجا با تو سخن می گویم: و از روحی که بر تو است می گیرم و بر آنان می گذارم؛ و آن ها بار مردمی را که با تو هستند به دوش خواهند کشید، در حالی که تو به تنهایی آن را به دوش نمی کشی.\n۱۸. و به مردم بگو: فردا خود را تقدیس کنید و گوشت بخورید: زیرا در گوش های خداوند گریه کردید و گفتید: چه کسی به ما گوشت می دهد تا بخوریم؟ زیرا در مصر با ما خوب بود؛ پس خداوند به شما گوشت خواهد داد و شما خواهید خورد.\n۱۹. یک روز، دو روز، پنج روز، ده روز و بیست روز نخورید؛\n۲۰. {اما} حتی یک ماه کامل، تا زمانی که از بینی تان بیرون بیاید و برای شما نفرت انگیز باشد: زیرا خداوند را که {هست} در میان خود تحقیر کرده اید و در برابر او گریه کرده اید و می گویید: چرا از مصر بیرون آمدیم؟ {کل...: عبری. ماه روزها}\n۲۱. و موسی گفت: مردمی که من در میان آن ها هستم، ششصد هزار پیاده نظام هستند؛ و تو گفته ای، به آن ها گوشت خواهم داد تا یک ماه کامل بخورند.\n۲۲. آیا گله ها و گله ها برای آن ها ذبح خواهند شد تا کافی باشند؟ یا همه ماهی های دریا برای آن ها جمع آوری می شوند تا برایشان کافی باشد؟\n۲۳. و خداوند به موسی گفت: آیا دست خداوند کوتاه شده است؟ اکنون خواهی دید که آیا کلام من به تو خواهد رسید یا نه.\n۲۴. و موسی بیرون رفت و سخنان خداوند را به مردم گفت و هفتاد مرد از بزرگان مردم را جمع کرد و آن ها را در اطراف خیمه قرار داد.\n۲۵. و خداوند در ابری فرود آمد و با او سخن گفت و از روحی که بر او بود گرفت و آن را به هفتاد پیر سپرد؛ و این اتفاق افتاد، {که} وقتی روح بر آنان نازل شد، پیشگویی کردند و دست برنداشتند.\n۲۶. اما دو نفر از مردان در اردوگاه باقی ماندند، نام یکی {بود} الداد و نام دیگری مداد؛ و روح بر آنان نازل شد؛ و آن ها از جمله کسانی بودند که نوشته شده بودند اما به خیمه نرفتند: و در اردوگاه پیشگویی کردند.\n۲۷. و جوانی دوید و به موسی گفت و گفت: الداد و مداد در اردوگاه پیشگویی می کنند.\n۲۸. و یوشع پسر نون، بنده موسی، یکی از جوانانش، پاسخ داد و گفت: ای موسی، آن ها را منع کن.\n۲۹. و موسی به او گفت: آیا به خاطر من حسادت می کنی؟ ای کاش خداوند همه مردم خداوند پیامبران بودند، {و} که خداوند روح خود را بر آن ها بگذارد!\n۳۰. و موسی او را به اردوگاه برد، او و بزرگان اسرائیل.\n۳۱. و بادی از جانب خداوند وزید و بلدرچین ها را از دریا آورد و آن ها را کنار اردوگاه انداخت، گویی یک روز راه در این طرف و آن سوی اردوگاه یک روز راه است، دور اردوگاه و دو ذراع بر سطح زمین ارتفاع داشت. {مثل یک روز...: عبری. انگار این روزها بود}\n۳۲. و مردم تمام آن روز و تمام آن شب و تمام روز بعد ایستادند و بلدرچین ها را جمع کردند: هر که کمتر جمع شد، ده هومر جمع کرد و همه را برای خود در اطراف اردوگاه پخش کردند.\n۳۳. و در حالی که گوشت هنوز بین دندان هایشان بود، پیش از آنکه جویده شود، خشم خداوند بر مردم شعله ور شد و خداوند مردم را با طاعونی بسیار بزرگ فرو برد.\n۳۴. و او نام آن مکان را کیبروتهاتاوا نامید: زیرا در آنجا مردمی را که هوس می کردند دفن کردند. {کیبروتهاتاوا: یعنی قبرهای شهوت}\n۳۵. {و} مردم از کیبراثتاوا به هازروت سفر کردند؛ و در هازروث اقامت داشت. {ساکن در: عبری. آن ها وارد شدند","۱. و مریم و هارون به خاطر زن اتیوپیایی که موسی با او ازدواج کرده بود، علیه موسی سخن گفتند؛ زیرا او با زنی اتیوپیایی ازدواج کرده بود. {اتیوپیایی: یا، کوشیت} {متأهل: عبری. گرفته شده}\n۲. و آن ها گفتند: آیا خداوند فقط موسی سخن گفته است؟ آیا او نیز با ما سخن نگفته است؟ و خداوند آن را شنید.\n۳. (مردی که موسی {بود} بسیار فروتن بود، بالاتر از همه مردانی که بر روی زمین بودند.)\n۴. و خداوند ناگهان به موسی و به هارون و به مریم گفت: سه نفر به خیمه جماعت بیرون بیایید. و آن سه نفر بیرون آمدند.\n۵. و خداوند در ستون ابر فرود آمد و در دروازه خیمه ایستاد و هارون و مریم را فراخواند و هر دو بیرون آمدند.\n۶. و او گفت: اکنون سخنانم را بشنوید: اگر پیامبری در میان شما باشد، {من} خداوند خود را در رؤیا به او معرفی خواهد کرد و در خواب با او سخن خواهد گفت.\n۷. بنده ام موسی چنین نیست، که در تمام خانه من وفادار است.\n۸. با او دهان به دهان صحبت خواهم کرد، حتی ظاهرا، و نه به صورت تاریک؛ و تمثیل خداوند را خواهد دید: پس چرا از سخن گفتن علیه بنده من موسی نترسیدی؟\n۹. و خشم خداوند بر آنان شعله ور شد؛ و او رفت.\n۱۰. و ابر از کنار تابناک رفت؛ و اینک، مریم {جذامی} شد، {سفید} مانند برف: و هارون به مریم نگاه کرد، و ببین، {او} جذامی بود.\n۱۱. و هارون به موسی گفت: ای پروردگارم، از تو خواهش می کنم گناهی را که در آن احمقانه انجام داده ایم و در آن گناه کرده ایم، بر ما نینداز.\n۱۲. نگذار او مانند مرده ای باشد که وقتی از رحم مادرش بیرون می آید، جسمش نیمه خورده می شود.\n۱۳. و موسی به خداوند فریاد زد و گفت: ای خدا، اکنون او را شفا بده، از تو می خواهم.\n۱۴. و خداوند به موسی گفت: اگر پدرش فقط به صورتش تف کرده بود، آیا هفت روز شرمنده نمی شد؟ بگذارید هفت روز از اردوگاه محروم شود و بعد از آن دوباره پذیرفته شود.\n۱۵. و مریم هفت روز از اردوگاه بیرون رانده شد؛ و مردم تا زمانی که مریم دوباره آورده شد، سفر نکردند.\n۱۶. و پس از آن مردم از هازروت رفتند و در بیابان پاران به زمین خوردند.","۱. و خداوند به موسی گفت و گفت:\n۲. مردانی را بفرست تا سرزمین کنعان را که به بنی اسرائیل می سپارم، جستجو کنند: از هر قبیله ای از نیادرانشان مردی بفرستید که هر یک فرمانروای آنان باشد.\n۳. و موسی به فرمان خداوند آنان را از بیابان پاران فرستاد: همه آن مردان سران بنی اسرائیل بودند.\n۴. و این ها نام های آن ها بودند: از قبیله روبن، شموع پسر زکور.\n۵. از قبیله سیمئون، شافات پسر حوری.\n۶. از قبیله یهودا، کالب پسر یفونه.\n۷. از قبیله یساکار، ایگال پسر یوسف.\n۸. از قبیله افریم، اوشع پسر راهبه. {اوشع: همچنین یوشع نامیده می شود}\n۹. از قبیله بنیامین و پالتی پسر رافو.\n۱۰. از قبیله زبولون، گادیئل پسر سودی.\n۱۱. از قبیله یوسف، {یعنی}، از قبیله مناسی، گدی پسر سوسی.\n۱۲. از قبیله دان، امی ئیل پسر جمالی.\n۱۳. از قبیله آشر، ستور پسر میکائیل.\n۱۴. از قبیله نفتالی، نهبی پسر وفسی.\n۱۵. از قبیله گاد، گئوئل پسر ماچی.\n۱۶. این ها نام مردانی است که موسی برای جاسوسی از سرزمین فرستاد. و موسی اوشع را پسر راهبه یهوشع نامید. {اوشیا: همچنین به نام جاشوا} {یهوشع: یا، یوشع}\n۱۷. و موسی آنان را فرستاد تا سرزمین کنعان را زیر نظر بگیرند و به آنان گفت: «شما را به این طرف جنوب ببرید و به کوه بروید:\n۱۸. و زمین را ببین، آنچه {هست}؛ و مردمی که در آن ساکن اند، چه قوی باشند چه ضعیف، اندک یا زیاد؛\n۱۹. و زمینی که در آن زندگی می کنند چیست، چه خوب باشد چه بد؛ و در چه شهرهایی زندگی می کنند، چه در چادرها و چه در قلعه ها؛\n20. و زمین چیست، آیا چاق است یا لاغر، آیا در آن چوب هست یا نه. و شجاع باشید و میوه زمین را بیاورید. اکنون زمان، زمان اولین انگورهای رسیده بود.\n۲۱. پس آن ها بالا رفتند و زمین را از بیابان زین تا رحوب جستجو کردند، همان طور که مردم به حماط می آیند.\n۲۲. و از جنوب بالا رفتند و به الخلیل رسیدند؛ جایی که آهیمان، ششای و تالمای، فرزندان آنک، {بودند}. (اکنون الخلیل هفت سال پیش از زوآن در مصر ساخته شده است.)\n۲۳. و به جوی اشکول رسیدند و از آنجا شاخه ای با یک خوشه انگور بریدند و آن را میان دو شاخه بر عصا قرار دادند؛ و {آن ها} انار و انجیر را آوردند. {جویبار: اور، دره}\n۲۴. این مکان به دلیل خوشه انگورهایی که بنی اسرائیل از آنجا قطع کردند، به نام جویبار اشکول نامیده می شد. {جویبار: اور، دره} {اشکول: یعنی یک خوشه انگور}\n۲۵. و آن ها پس از چهل روز از جستجو در زمین بازگشتند.\n۲۶. و آن ها رفتند و نزد موسی و هارون و همه جماعت بنی اسرائیل، بیابان پاران و قادش آمدند؛ و به آنان و همه جماعت خبر رساند و میوه زمین را به آنان نشان داد.\n۲۷. و آن ها به او گفتند و گفتند: «ما به سرزمینی آمدیم که تو ما را در آن دیدی و مطمئنا با شیر و عسل جاری است؛ و این میوه آن است.\n۲۸. با این حال، مردمی که در سرزمین زندگی می کنند نیرومند هستند و شهرها دیوارکشی شده اند و بسیار بزرگ اند؛ و علاوه بر آن، فرزندان آنک را آنجا دیدیم.\n۲۹. عمالیک ها در سرزمین جنوب ساکن اند؛ و هیتی ها و جبوسی ها و اموریان در کوه ها ساکن اند؛ و کنعانیان در کنار دریا و ساحل اردن ساکن اند.\n۳۰. و کالب مردم را پیش موسی آرام کرد و گفت: بیایید فورا بالا برویم و آن را تصاحب کنیم؛ زیرا ما به خوبی قادر به غلبه بر آن هستیم.\n۳۱. اما مردانی که با او بالا رفتند گفتند: ما قادر به مقابله با مردم نیستیم؛ زیرا آن ها از ما قوی ترند.\n۳۲. و آن ها خبر بدی از سرزمینی که جستجو کرده بودند به بنی اسرائیل آوردند و گفتند: سرزمینی که ما برای جستجو از آن عبور کرده ایم، سرزمینی است که ساکنان آن را می خورد؛ و همه کسانی که در آن دیدیم مردانی با جایگاه بزرگ بودند. {مردان...: عبری. مردان با جثه}\n۳۳. و آنجا غول ها، پسران آنک را دیدیم، {که آمده اند} از غول ها؛ و ما همچون ملخ در برابر خود بودیم، و این گونه در دید آن ها بودیم.","۱. و همه جماعت صدای خود را بلند کردند و فریاد زدند؛ و مردم آن شب گریه کردند.\n۲. و همه بنی اسرائیل بر موسی و هارون زمزمه کردند و همه جماعت به آنان گفتند: ای کاش خدایا در سرزمین مصر مرده بودیم! یا خدا، کاش در این بیابان می مردیم!\n۳. و چرا خداوند ما را به این سرزمین آورده است تا با شمشیر کشته شویم تا همسران و فرزندانمان شکار شوند؟ آیا بهتر نبود که به مصر بازگردیم؟\n۴. و به یکدیگر گفتند: بیایید فرمانده ای کنیم و به مصر بازگردیم.\n۵. سپس موسی و هارون در برابر همه جماعت بنی اسرائیل به صورت خود افتادند.\n۶. و یوشع پسر نون و کالب پسر یفونه، که از آنان بودند که زمین را جست وجو کردند، لباس هایشان را پاره کردند:\n۷. و به همه جمع بنی اسرائیل گفتند: سرزمینی که برای جستجو از آن گذشتیم، سرزمینی بسیار نیکو است.\n۸. اگر خداوند در ما شاد باشد، ما را به این سرزمین خواهد آورد و آن را به ما خواهد داد؛ سرزمینی که با شیر و عسل جاری است.\n۹. فقط علیه خداوند شورش نکنید و از مردم سرزمین نترسید؛ زیرا آن ها برای ما نان هستند: دفاعشان از آن ها دور شده و خداوند با ماست: از آن ها نترسید. دفاع: عبری. شادو}\n۱۰. اما همه جماعت به آن ها دستور دادند که با سنگ سنگ بخورند. و جلال خداوند در خیمه جماعت در برابر همه بنی اسرائیل ظاهر شد.\n۱۱. و خداوند به موسی گفت: این مردم تا کی مرا تحریک خواهند کرد؟ و چقدر طول می کشد تا آن ها به من باور کنند، با تمام نشانه هایی که در میان آن ها نشان داده ام؟\n۱۲. آن ها را با طاعون نابود خواهم کرد و از ارث محروم خواهم کرد و تو را ملتی بزرگ تر و قدرتمندتر از آن ها خواهم ساخت.\n۱۳. و موسی به خداوند گفت: آنگاه مصریان خواهند شنید، (زیرا تو این مردم را با قدرت از میان آنان برخاستی؛)\n۱۴. و آن را به ساکنان این سرزمین خواهند گفت: زیرا شنیده اند که تو خداوند در میان این مردم هستی، که تو رو در رو دیده می شوی و ابر تو بر فراز آنان ایستاده است و تو در روز در ستونی از ابر و شب در ستون آتش پیش از آن ها می روی.\n۱۵. اکنون {اگر} همه این مردم را به عنوان یک نفر بکشی، آنگاه ملت هایی که شهرت تو را شنیده اند، خواهند گفت:\n۱۶. زیرا خداوند نتوانست این مردم را به سرزمینی که به آنان سوگند خورده بود بیاورد، پس آنان را در بیابان کشت.\n۱۷. و اکنون، از تو می خواهم، قدرت پروردگارم بزرگ باشد، همان طور که گفتی و گفتی:\n۱۸. خداوند صبور و بسیار بخشنده است، گناه و خطا را می بخشد و به هیچ وجه گناهکاران را پاک نمی کند، گناه پدران را بر فرزندان تا نسل سوم و چهارم می سپارد.\n۱۹. از تو می خواهم که گناه این مردم را بر اساس عظمت رحمت تو و چنان که این مردم را از مصر تا کنون بخشیده ای، ببخش. {تا اینکه...: یا، تا حالا}\n۲۰. و خداوند گفت: من طبق کلام تو بخشیده ام:\n۲۱. اما {چنان} واقعا {چنان که زندگی می کنم} تمام زمین با جلال خداوند پر خواهد شد.\n۲۲. زیرا همه آن مردانی که جلال و معجزه های من را که در مصر و بیابان انجام دادم دیده اند و اکنون ده بار مرا وسوسه کرده اند و به صدای من گوش نداده اند؛\n۲۳. مطمئنا آن ها سرزمینی را که به پدرانشان قسم خورده ام نخواهند دید، و هیچ یک از کسانی که مرا تحریک کردند آن را نخواهند دید: {البته...: عبرانی. اگر زمین را ببینند}\n۲۴. اما بنده ام کالب، چون روح دیگری با خود داشت و کاملاً مرا دنبال کرد، او را به سرزمینی که به آن رفت خواهم برد؛ و نسل او آن را خواهد داشت.\n۲۵. (اکنون عمالقیان و کنعانیان در دره ساکن بودند.) فردا تو را تبدیل می کند و از راه دریای سرخ به بیابان می برد.\n۲۶. و خداوند به موسی و هارون گفت و گفت:\n۲۷. تا کی باید با این جماعت شرور که علیه من زمزمه می کنند، تحمل کنم؟ من زمزمه های بنی اسرائیل را شنیده ام که آن ها علیه من زمزمه می کنند.\n۲۸. به آنان بگو: «همان قدر که من زنده ام، خداوند می گوید، همان گونه که تو در گوش من سخن گفتی، من نیز به تو خواهم گفت:\n۲۹. لاشه های شما در این بیابان سقوط خواهد کرد؛ و همه کسانی که از تو به حساب تمام شما، از بیست سالگی و بالاتر، که بر من زمزمه کرده اند،\n۳۰. بی شک به سرزمینی که قسم خورده ام شما را در آنجا ساکن کنم، به جز کالب پسر یفوننه و یوشع پسر راهبه وارد نخواهید شد. دستم را بالا برد}\n۳۱. اما کوچولوهایت که گفتی باید شکار شوند، آن ها را می آورم و سرزمینی را که از آن بیزار بودی خواهند شناخت.\n۳۲. اما {و درباره} تو، لاشه هایتان، در این بیابان سقوط خواهند کرد.\n۳۳. و فرزندانت چهل سال در بیابان سرگردان خواهند بود و فاحشه های شما را تحمل خواهند کرد، تا لاشه هایتان در بیابان هدر شود. {سرگردان: یا، تغذیه کن}\n۳۴. پس از تعداد روزهایی که در سرزمین جستجو کردید، {حتی} چهل روز، هر روز به مدت یک سال، گناهان خود را تحمل خواهید کرد، {حتی} چهل سال، و خواهید دانست که وعده ام را شکسته ام. {نقض...: یا، تغییر هدفم}\n۳۵. من، خداوند، گفته ام، حتما این کار را با همه این جماعت شرور که علیه من گرد آمده اند انجام خواهم داد: در این بیابان بلعیده خواهند شد و آنجا خواهند مرد.\n۳۶. و مردانی که موسی برای جستجوی سرزمین فرستاد، بازگشتند و همه جماعت را به زمزمه علیه او واداشتند، با افترا بر سرزمین،\n۳۷. حتی آن مردانی که خبر بد را درباره سرزمین آوردند، در برابر خداوند بر اثر طاعون مردند.\n۳۸. اما یوشع پسر نون و کالب پسر یفونه، {که بودند} از مردانی که برای جستجوی سرزمین رفتند، هنوز زنده بودند.\n۳۹. و موسی این گفته ها را به همه بنی اسرائیل گفت و مردم بسیار سوگواری کردند.\n۴۰. و آن ها صبح زود برخاستند و آن ها را به بالای کوه بردند و گفتند: ببین، ما [اینجا خواهیم بود} و به جایی که خداوند وعده داده بالا خواهیم رفت: زیرا ما گناه کرده ایم.\n۴۱. و موسی گفت: «چرا اکنون فرمان خداوند را زیر پا می گذاری؟» اما موفق نخواهد شد.\n۴۲. بالا نروید، زیرا خداوند در میان شما نیست؛ که در برابر دشمنانتان شیفته نشوید.\n۴۳. زیرا عمالقیان و کنعانیان پیش روی شما هستند و شما با شمشیر خواهید کشت: زیرا از خداوند رانده شده اید، پس خداوند با شما نخواهد بود.\n۴۴. اما آن ها تصمیم گرفتند به بالای تپه بروند؛ با این حال تابوت عهد خداوند و موسی از اردوگاه خارج نشدند.\n۴۵. سپس عمالیک ها پایین آمدند و کنعانیانی که در آن تپه ساکن بودند، آن ها را زدند و حتی تا هورما آشفته کردند.","۱. و خداوند به موسی گفت و گفت:\n۲. به بنی اسرائیل سخن بگو و به آنان بگو: وقتی به سرزمین خانه های خود که به شما می دهم، وارد شدید،\n۳. و قربانی آتش به خداوند، قربانی سوخته، یا قربانی در انجام نذر، یا قربانی آزادانه یا در جشن های باشکوه خود، برای مزه شیرین به خداوند، گله یا گله تقدیم می کند: {انجام می دهد: عبرانی. جدا شدن}\n۴. آنگاه کسی که قربانی خود را به خداوند تقدیم می کند، نذری گوشتی از یک دهم آرد مخلوط با قسمت چهارم یک هین روغن خواهد آورد.\n۵. و چهارمین قسمت از یک هین شراب برای نوشیدنی نذری که باید با قربانی سوختنی یا قربانی برای یک بره آماده کنی.\n۶. یا برای قوچ، باید برای نذری گوشتی دو دهم آرد مخلوط با سومین قسمت یک هین روغن آماده کنی.\n۷. و برای نذری نوشیدنی، سومین قسمت یک هین شراب را تقدیم کن، {زیارتگاه شیرین} به خداوند.\n۸. و زمانی که گاوی را برای قربانی سوخته، یا قربانی در انجام نذر، یا نذورات صلح به خداوند آماده می کنی:\n۹. سپس با گاوی نذری گوشتی از سه دهم آرد مخلوط با نیم هین روغن بیاورد.\n۱۰. و برای نوشیدنی، نیم یک هین شراب را به عنوان نذری که با آتش تقدیم شده، از عطری شیرین به خداوند بیاوری.\n۱۱. این کار برای یک گاو، یا یک قوچ، یا بره یا بچه انجام می شود.\n۱۲. بر اساس تعداد، به هر بر اساس تعدادشان نیز عمل خواهی کرد.\n۱۳. همه کسانی که از سرزمین زاده می شوند این کارها را پس از این انجام خواهند داد، با تقدیم قربانی ای که از آتش تقدیم شده و عطری شیرین به خداوند است.\n۱۴. و اگر غریبه ای نزد شما یا هر در نسل های شما اقامت کند و قربانی ای از عطر شیرین به خداوند تقدیم کند؛ همان طور که تو می کنی، او نیز خواهد کرد.\n۱۵. یک آیین {باید هم باشد} برای شما از جماعت و هم برای غریبه ای که {با شما} اقامت دارد، این آیین برای همیشه در نسل های شما خواهد بود: همانطور که شما {هستید}، غریبه نیز در برابر خداوند خواهد بود.\n۱۶. یک قانون و یک راه برای تو و غریبه ای که با تو اقامت دارد، خواهد بود.\n۱۷. و خداوند به موسی گفت:\n۱۸. به بنی اسرائیل سخن بگو و به آنان بگو: وقتی به سرزمینی که من شما را می آورم به آن می آیید،\n۱۹. آنگاه وقتی از نان زمین می خورید، قربانی ای به خداوند تقدیم خواهید کرد.\n۲۰. باید کیک از اولین خمیر خود را برای قربانی تقدیم کنید: همان طور که قربانی کف خرمن کوبی را انجام می دهید، آن را نیز بلند خواهید کرد.\n۲۱. از نخستین پول خود نذری به خداوند در نسل های بعدی بدهید.\n۲۲. و اگر اشتباه کرده اید و همه این فرمان ها را که خداوند به موسی گفته است، رعایت نکرده اید،\n۲۳. {حتی} همه آنچه خداوند به دست موسی به شما فرمان داده است، از روزی که خداوند {موسی} فرمان داد، و از آن پس در میان نسل های شما؛\n24. پس اگر به دلیل نادانی و بدون اطلاع جماعت انجام شود، همه جماعت یک گاو نر جوان را به عنوان قربانی سوخته، به عنوان عطر شیرین به خداوند، همراه با قربانی گوشت و نذر نوشیدنی اش، طبق آداب، و یک بچه بز را به عنوان قربانی گناه تقدیم کنند. {بدون...: عبری. از چشم ها} {رفتار: یا، آیین نام}\n۲۵. و کشیش برای همه جماعت بنی اسرائیل کفاره خواهد داد و آن ها بخشیده خواهد شد؛ زیرا این نادانی است: و آن ها قربانی خود را، قربانی ای که با آتش به خداوند تقدیم شده، و قربانی گناه خود را نزد خداوند به خاطر نادانی شان خواهند آورد:\n۲۶. و همه جماعت بنی اسرائیل و بیگانه ای که در میان آنان اقامت دارد، بخشیده خواهد شد؛ دیدن اینکه همه مردم {بودند} در نادانی.\n۲۷. و اگر کسی از نادانی گناه کند، باید بز ماده سال اول را برای قربانی گناه بیاورد.\n۲۸. و کشیش باید برای روحی که بی آگاهانه گناه می کند، زمانی که در حضور خداوند گناه می کند، کفاره دهد تا برای او کفاره دهد؛ و او بخشیده خواهد شد.\n۲۹. یک قانون برای کسی که به دلیل نادانی گناه می کند، هم برای کسی که در میان بنی اسرائیل به دنیا آمده و هم برای غریبه ای که در میان آن ها اقامت دارد، خواهی داشت. {sinneth: عبری. doth}\n۳۰. اما جانی که با گستاخی عمل می کند، چه در سرزمین زاده شده باشد یا بیگانه، خداوند را نیز سرزنش می کند؛ و آن روح از میان مردمش قطع خواهد شد. {با جسارت: عبری. با دست بالا}\n۳۱. زیرا او کلام خداوند را تحقیر کرده و فرمان خود را شکسته است، آن روح به طور کامل قطع خواهد شد؛ گناه او بر او خواهد بود.\n۳۲. و هنگامی که بنی اسرائیل در بیابان بودند، مردی را یافتند که در روز شنبه چوب جمع می کرد.\n۳۳. و آنان که او را در حال جمع آوری چوب یافتند، او را نزد موسی و هارون و به همه جماعت بردند.\n۳۴. و او را در قیمه گذاشتند، چون مشخص نشده بود که چه باید با او رفتار شود.\n۳۵. و خداوند به موسی گفت: آن مرد حتما کشته خواهد شد؛ همه جماعت او را بدون اردوگاه با سنگ سنگسار خواهند کرد.\n۳۶. و همه جماعت او را بدون اردوگاه آوردند و با سنگ به او سنگسار کردند و او مرد؛ چنان که خداوند به موسی فرمان داد.\n۳۷. و خداوند به موسی گفت و گفت:\n۳۸. به بنی اسرائیل سخن بگو و به آن ها بگو که در طول نسل ها حاشیه های لباس هایشان را حاشیه دار کنند و بر لبه لبه ها یک نوار آبی بگذارند:\n۳۹. و این برای تو به عنوان حاشیه ای خواهد بود تا به آن نگاه کنی و همه فرمان های خداوند را به یاد داشته باشی و انجام دهی؛ و اینکه به دنبال قلب و چشمان خود نروید، که به دنبال آن ها به فاحشه گری می روید:\n۴۰. تا به یاد داشته باشی و همه فرمان هایم را انجام دهی و نزد خدای خود مقدس باشی.\n۴۱. من خداوند خدای شما هستم که شما را از سرزمین مصر بیرون آورد تا خدای شما باشید: من خداوند خدای شما هستم.","۱. اکنون قارح، پسر ایزهار، پسر کوهات، پسر لاوی، و داتان و ابیرام، پسران الیاب، و عون، پسر پلت، پسران روبن، {مردم} را گرفتند:\n۲. و آنان در برابر موسی برخاستند، همراه با برخی از بنی اسرائیل، دویست و پنجاه شاهزاده مجمع که در جماعت مشهور و مردان مشهور بودند:\n۳. و آنان علیه موسی و هارون جمع شدند و به آنان گفتند: {شما بیش از حد بر دوش خود می گیرید، زیرا همه جماعت همه آن ها مقدس اند و خداوند در میان آنان است: پس چرا خود را بر جماعت خداوند برمی دارید؟» {می گیری...: عبری. برای تو خیلی مهم است}\n۴. و وقتی موسی آن را شنید، روی صورتش افتاد:\n۵. و به قارح و همه همراهانش گفت و گفت: فردا خداوند نشان خواهد داد که چه کسی از آن او است و چه کسی مقدس است؛ و {او} را به او نزدیک خواهد کرد: حتی {او} را که انتخاب کرده است نیز به او نزدیک خواهد کرد.\n۶. این کار را می کند؛ بفرمایید، قورح، و همه همراهانش؛\n۷. و در آن آتش بگذار و در آن ها بخور بگذار پیش خداوند فردا، و آن مرد خواهد بود که خداوند انتخاب کند، مقدس خواهد بود: ای فرزندان لاوی، بیش از حد بر دوش خود می گیرید.\n۸. و موسی به قورح گفت: بشنوید، ای پسران لاوی، از شما خواهش می کنم:\n۹. {به نظر می رسد} که خدای اسرائیل شما را از جماعت اسرائیل جدا کرده تا شما را به خود نزدیک کند تا خدمت در خیمه خداوند را انجام دهد و در برابر جماعت بایستد و به آنان خدمت کند؟\n۱۰. و او تو و همه برادرانت و فرزندان لاوی را با خود نزدیک کرده است، و تو نیز به دنبال کشیشی هستی؟\n۱۱. به چه دلیلی تو و همهٔ همراهانتان علیه خداوند متحد شده اید؟ و هارون چیست که علیه او زمزمه می کنید؟\n۱۲. و موسی فرستاد تا داتان و ابیرام، پسران الیاب، را فرا بخواند و گفت: «ما بالا نخواهیم آمد:\n۱۳. آیا چیز کوچکی است که ما را از سرزمینی که با شیر و عسل جاری است پرورش داده ای تا در بیابان ما را بکشی، مگر اینکه خودت را بر ما شاهزاده کنی؟\n۱۴. علاوه بر این، تو ما را به سرزمینی که با شیر و عسل جاری است نیاورده ای یا به ما ارث مزارع و تاکستان ها نداده ای: آیا چشم این مردان را خاموش می کنی؟ ما بالا نمی آییم. {بگذار...: عبری. بور اوت}\n۱۵. و موسی بسیار خشمگین شد و به خداوند گفت: «به قربانی شان احترام نگذار: من حتی یک خر از آنان نگرفته ام و به هیچ یک از آن ها آسیب نرسانده ام.»\n۱۶. و موسی به قارح گفت: تو و همه همراهانت در برابر خداوند باش، تو و آنان و هارون، فردا بگرد:\n۱۷. و هر بخورش را بردار و در آن ها بخور بگذار و هر را پیش خداوند بگذار، دویست و پنجاه بخور. تو و هارون، هر یک از شما عودپاش او هستید.\n۱۸. و هر مرد عود خود را برداشتند و در آن آتش گذاشتند و عود بر آن گذاشتند و در دروازه خیمه جماعت با موسی و هارون ایستادند.\n۱۹. و قورح همه جماعت را علیه آنان به دروازه خیمه جماعت جمع کرد و جلال خداوند بر همه جماعت آشکار شد.\n۲۰. و خداوند به موسی و هارون گفت و گفت:\n۲۱. خود را از میان این جماعت جدا کنید تا بتوانم در لحظه ای آن ها را مصرف کنم.\n۲۲. و بر روی صورتشان افتادند و گفتند: ای خدا، خدای ارواح همه انسانان، آیا یک نفر گناه خواهد کرد و آیا تو از همه جماعت خشمگین خواهی شد؟\n۲۳. و خداوند به موسی گفت:\n۲۴. به جماعت سخن بگو و بگو: «از اطراف خیمه کورح، داتان و ابیرام بلند شوید.»\n۲۵. و موسی برخاست و نزد داتان و ابیرام رفت؛ و بزرگان اسرائیل نیز او را دنبال کردند.\n۲۶. و او به جماعت گفت: از چادرهای این مردان شرور بروید و به هیچ چیز دست نزنید، مبادا در همه گناهانشان غرق شوید.\n۲۷. پس از خیمه قورح، داتان و ابیرام، از هر طرف برخاستند و داتان و ابیرام بیرون آمدند و در در چادرهایشان ایستادند، و همسرانشان، پسران و فرزندان خردسالشان را.\n۲۸. و موسی گفت: «بدین وسیله خواهید دانست که خداوند مرا فرستاده تا همه این کارها را انجام دهم؛ زیرا {من} خودم آن ها را انجام نداده ام.\n۲۹. اگر این مردان مرگ مشترک همه انسان ها را از دست بدهند، یا اگر پس از دیدار همه انسان ها ملاقات شوند؛ {پس} خداوند مرا نفرستاده است. {معمولی...: عبری. همان طور که هر مردی می خواهد}\n۳۰. اما اگر خداوند چیز جدیدی آفرید و زمین دهان خود را باز کند و آن ها را با همه آنچه به آن ها مربوط است ببلعد و سریع به گودال بروند؛ آنگاه خواهید فهمید که این مردان خداوند را تحریک کرده اند. {make...: عبری. یک موجود خلق کن}\n۳۱. و چنین شد، همان طور که او تمام این سخنان را به پایان رسانده بود، که تکه زمینی که زیر آن ها بود، از هم پاشید:\n۳۲. و زمین دهانش را باز کرد و آن ها و خانه هایشان و همه مردانی که به قورح تعلق داشتند و همه اموالشان را بلعید.\n۳۳. آنان و همه کسانی که به آن ها تعلق داشت، زنده به گودال سقوط کردند و زمین بر رویشان بسته شد و از میان جماعت جان باختند.\n۳۴. و همه اسرائیلی که اطرافشان بودند، با فریاد آن ها گریختند؛ زیرا گفتند: مبادا زمین ما را هم ببلعد.\n۳۵. و آتشی از خداوند بیرون آمد و دویست و پنجاه مردی را که عود تقدیم کردند، سوزاند.\n۳۶. و خداوند به موسی گفت:\n۳۷. به الیعازر، پسر هارون کاهن، بگو که بخورها را از آتش بردارد و آتش را آنجا پراکنده کند؛ زیرا آن ها مقدس اند.\n۳۸. عودکاران این گناهکاران را بر جان خود بگذارند، بگذار آن ها را لوح های پهن بسازند [زیارت] برای پوششی بر محراب؛ زیرا آن ها را نزد خداوند تقدیم کردند، پس مقدس اند و نشانه ای برای بنی اسرائیل خواهند بود.\n۳۹. و الیعازر کاهن بخورهای برزن را که سوختگان با آن تقدیم کرده بودند، برداشت؛ و آن ها به صورت صفحات عریض برای پوششی از محراب ساخته شدند:\n۴۰. {تا یادبودی برای بنی اسرائیل باشد} که هیچ غریبه ای که {از نسل هارون} نیست، نزد خداوند برای تقدیم عود نزدیک شود؛ که او مانند قورح نباشد و به عنوان همراهش نباشد: همان گونه که خداوند به دست موسی به او گفت.\n۴۱. اما فردا همه جماعت بنی اسرائیل علیه موسی و هارون زمزمه کردند و گفتند: شما قوم خداوند را کشته اید.\n۴۲. و زمانی که جماعت علیه موسی و هارون جمع شدند، به سوی خیمه جماعت نگاه کردند؛ و اینک، ابر آن را پوشاند و جلال خداوند ظاهر شد.\n۴۳. و موسی و هارون در برابر خیمه جماعت آمدند.\n۴۴. و خداوند به موسی گفت:\n۴۵. تو را از میان این جماعت بلند کن تا بتوانم آن ها را در لحظه ای بخورم. و روی صورتشان افتادند.\n۴۶. و موسی به هارون گفت: یک عود بردار و از قربانگاه آتش در آن بگذار و عود بگذار و سریع به جماعت برو و برای آنان کفاره بده، زیرا خشم خداوند فروکش کرده است؛ طاعون آغاز شده است.\n۴۷. و هارون همان طور که موسی فرمان داده بود، گرفت و به میان جماعت دوید؛ و ناگهان، طاعون در میان مردم آغاز شد: و او عود زد و برای مردم کفاره داد.\n۴۸. و میان مردگان و زندگان ایستاد؛ و طاعون متوقف شد.\n۴۹. کسانی که در طاعون مردند، چهارده هزار و هفتصد نفر بودند، علاوه بر آنان که به خاطر مسئله قورح جان باختند.\n۵۰. و هارون به سوی موسی به دروازه خیمه جماعت بازگشت: و طاعون متوقف شد.","۱. و خداوند به موسی گفت و گفت:\n۲. با بنی اسرائیل سخن بگو و از هر یک از آن ها عصایی به نام خانه پدران شان و از همه شاهزادگانشان به اندازه خانه پدران دوازده چوب بردارید: نام هر مرد را بر عصایش بنویس.\n۳. و نام هارون را بر عصای لاوی بنویس: زیرا یک عصا {خواهد بود} برای سر خاندان پدرانشان.\n۴. و تو آن ها را در خیمه جماعت پیش شهادت خواهی گذاشت، جایی که من با تو ملاقات خواهم کرد.\n۵. و این اتفاق خواهد افتاد که عصای مردی که من او را انتخاب خواهم کرد، شکوفا خواهد شد؛ و من زمزمه های بنی اسرائیل را که با آن ها علیه تو زمزمه می کنند، از من قطع خواهم کرد.\n۶. و موسی به بنی اسرائیل گفت و هر یک از شاهزادگانشان به او یک عصا دادند، برای هر شاهزاده، طبق خاندان پدرشان، دوازده عصا؛ و عصای هارون در میان عصاهایشان بود. {یک چوب...: عبری. یک عصا برای یک شاهزاده، یک چوب برای یک شاهزاده}\n۷. و موسی عصاها را در خیمه شاهد پیش خداوند گذاشت.\n۸. و اتفاق افتاد که فردا موسی وارد خیمه شاهد شد؛ و اینگونه بود که عصای هارون برای خاندان لاوی جوانه زد و جوانه زد و شکوفه ها را شکوفا کرد و بادام داد.\n۹. و موسی همه عصاها را از حضور خداوند برای همه بنی اسرائیل آورد و آنان نگاه کردند و هر مرد عصایش را برداشتند.\n۱۰. و خداوند به موسی گفت: عصای هارون را دوباره پیش شهادت بیاور تا به عنوان نشانه ای علیه شورشیان نگه دارد؛ و تو باید زمزمه هایشان را از من بگیری، تا نمیرند. {شورشیان: عبری. فرزندان شورش}\n۱۱. و موسی چنین کرد: چنان که خداوند به او فرمان داد، او نیز چنین کرد.\n۱۲. و بنی اسرائیل به موسی گفتند: ببین، ما می میریم، هلاک می شویم، همه ما هلاک می شویم.\n۱۳. هر که به خیمه خداوند نزدیک شود، خواهد مرد: آیا ما با مرگ غرق خواهیم شد؟","۱. و خداوند به هارون گفت: تو و پسرانت و خاندان پدرت با تو گناه مقدس را به دوش خواهی کشید؛ و تو و پسرانت با تو گناه کاهنیت خود را به دوش خواهید کشید.\n۲. و برادرانت نیز از قبیله لاوی، قبیله پدرت، تو را با خود بیاور تا به تو بپیوندند و به تو خدمت کنند؛ اما تو و پسرانت با تو در برابر خیمه شهادت خدمت خواهی کرد.\n۳. و آن ها مسئولیت تو و همه خیمه نشینان را نگه خواهند داشت؛ تنها کسانی که به ظروف محراب و محراب نزدیک نخواهند شد، نه آن ها و نه تو نخواهند مرد.\n۴. و آن ها به تو خواهند پیوست و مسئول خیمه جماعت خواهند بود، برای تمام خدمات خیمه؛ و هیچ غریبه ای به تو نزدیک نخواهد شد.\n۵. و مسئولیت محراب و قربانگاه را حفظ کنید تا دیگر خشم بر بنی اسرائیل نازل نشود.\n۶. و من، اینک، برادران تو لاویان را از میان بنی اسرائیل گرفته ام: به تو {آنان} به عنوان هدیه ای برای خداوند داده شده اند تا در خیمه جماعت خدمت کنند.\n۷. پس تو و فرزندانت با تو منصب کشیشی خود را برای هر چیز در محراب و درون پرده نگه دارید؛ و شما خدمت خواهید کرد: من مقام کشیشی شما را به عنوان هدیه داده ام؛ و هر غریبه ای که نزدیک شود، کشته خواهد شد.\n۸. و خداوند به هارون گفت: «اینک، من نیز تو را مأمور نذورات بلند کردن همه چیزهای مقدس بنی اسرائیل کرده ام؛ آن ها را به خاطر تدهین به تو داده ام و به پسرانت را به واسطه یک فرمان برای همیشه داده ام.\n۹. این یکی از مقدس ترین چیزهای تو خواهد بود، {محفوظ} از آتش: هر قربانی آن ها، هر قربانی گوشتی از طرف آن ها، هر قربانی گناه از طرف آن ها، و هر قربانی خطا که به من تقدیم می کنند، برای تو و پسرانت مقدس ترین خواهد بود.\n۱۰. در مقدس ترین مکان آن را خواهی خورد؛ هر مرد آن را خواهد خورد: برای تو مقدس خواهد بود.\n۱۱. و این {هست} مال تو؛ قربانی هدیه شان، همراه با همه قربانی های بنی اسرائیل: آن ها را به تو و به پسرانت و دخترانت با تو داده ام، طبق قانونی برای همیشه: هر که در خانه ات پاک باشد، از آن خواهد خورد.\n۱۲. بهترین های روغن و بهترین شراب و گندم، نخستین میوه هایی که به خداوند تقدیم خواهند کرد، آن ها را به تو داده ام. {بهترین: عبری. چاق}\n۱۳. {و} هر آنچه در زمین نخستین برسد و آن را نزد خداوند بیاورند، مال تو خواهد بود؛ هر که در خانه ات پاک است، از آن خواهد خورد.\n۱۴. هر چیزی که در اسرائیل وقف شده باشد، مال تو خواهد بود.\n۱۵. هر چیزی که ماتریکس را در تمام جسم باز کند و آن را نزد خداوند می آورند، چه انسان باشد چه حیوانات، مال تو خواهد بود؛ اما نخست زاده انسان را حتما رهایی خواهی داد و نخستین حیوانات ناپاک را رهایی خواهی داد.\n۱۶. و کسانی که قرار است از یک ماه گذشته رهایی یابند، طبق تخمین تو، به مبلغ پنج شکل، پس از شکل مقدس که معادل بیست گره است، بازخرید خواهی کرد.\n۱۷. اما نخست زاده گاو، یا نخست زاده گوسفند، یا نخست زاده بز، نباید رهایی بدهی؛ آن ها مقدس هستند: خونشان را بر محراب بپاشید و چربی شان را بسوزانید {برای} قربانی ای که با آتش تقدیم شده، به عنوان طعمی شیرین برای خداوند.\n۱۸. و گوشت آن ها از آن تو خواهد بود، همان طور که سینه موج دار و شانه راست از آن توست.\n۱۹. تمام نذورات مقدس که بنی اسرائیل به خداوند تقدیم می کنند، به تو و پسران و دخترانت را به عنوان قانونی برای همیشه به تو داده ام: این عهدی از نمک است که برای همیشه نزد خداوند به تو و نسل تو با تو خواهد بود.\n۲۰. و خداوند به هارون گفت: تو در سرزمین آن ها ارثی نخواهی داشت، و هیچ سهمی در میان آن ها نخواهی داشت: من سهمی تو و میراث تو در میان بنی اسرائیل هستم.\n۲۱. و اینک، من به فرزندان لاوی تمام یک دهم زمین اسرائیل را برای ارث دادم، برای خدمتی که خدمت می کنند، {حتی} خدمت در خیمه جماعت.\n۲۲. از این پس نباید فرزندان اسرائیل به خیمه جماعت نزدیک شوند، مبادا گناه کنند و بمیرند. {و بمیرم: عبری. تا بمیرم}\n۲۳. اما لاویان باید خدمت به خیمه جماعت را انجام دهند و گناه خود را تحمل کنند: این قانون برای نسل های شما خواهد بود که در میان بنی اسرائیل هیچ میراثی ندارند.\n۲۴. اما عشر بنی اسرائیل که آن را به عنوان قربانی به خداوند تقدیم می کنند، به لاویان داده ام تا ارث ببرند؛ بنابراین به آنان گفته ام: در میان بنی اسرائیل هیچ میراثی نخواهند داشت.\n۲۵. و خداوند به موسی گفت و گفت:\n۲۶. پس با لاویان سخن بگو و به آنان بگو: وقتی از بنی اسرائیل دهکده هایی را که به عنوان ارث به تو داده ام برداشتی، پس یک نذر بزرگ از آن را برای خداوند تقدیم کن، حتی یک دهم بخش.\n۲۷. و {این} قربانی تو برای تو حساب خواهد شد، گویی که غله خرمن کوبی است و به عنوان پر بودن پرس شراب.\n۲۸. بدین ترتیب، نذری بلند برای همه دهکده های خود که از بنی اسرائیل دریافت می کنید، به خداوند تقدیم خواهید کرد؛ و از آن، قربانی خداوند را به هارون کاهن تقدیم خواهی کرد.\n۲۹. از میان همه هدایای خود، هر قربانی خداوند و بهترین های آن را تقدیم خواهی کرد، {حتی} بخش مقدس آن را. {بهترین: عبری. چاق}\n۳۰. پس به آن ها بگو: وقتی بهترین آن را از آن برداشتید، آن را برای لاویان به عنوان افزایش کف خرمن و به عنوان افزایش پرس شراب شمرده خواهد شد. {بهترین: عبری. چاق}\n۳۱. و شما آن را در هر جایی، شما و خانواده هایتان، خواهید خورد؛ زیرا این پاداش شما برای خدمتتان در خیمه جماعت است.\n۳۲. و اگر بهترین ها را از آن بیرون کشیده اید، گناهی به خاطر آن نخواهید داشت: و مقدس های بنی اسرائیل را آلوده نخواهید کرد، مبادا بمیرید.","۱. و خداوند به موسی و هارون گفت و گفت:\n۲. این {است} فرمان قانونی است که خداوند فرمان داده است: «به بنی اسرائیل بگو که برای تو گاو سرخ بی لکه بیاورند، که در آن هیچ لکه ای نباشد {و} که هرگز بر آن نیامده است:\n۳. و تو او را به الیعازر کاهن بدهی تا او را بدون اردوگاه بیرون بیاورد، و {یکی} او را در برابر خود خواهد کشت:\n۴. و الیعازر کشیش با انگشت خود از خون او می گیرد و هفت بار از خونش را درست جلوی خیمه جماعت می پاشد:\n۵. و {یکی} گوساله را جلوی چشمش خواهد سوزاند؛ پوست و گوشتش و خونش را با کودش خواهد سوزاند:\n۶. و کشیش چوب سدر، زفا و سرخ را برمی دارد و آن را در میان آتش گاو می اندازد.\n۷. سپس کشیش لباس هایش را می شوید و گوشتش را با آب می شوید و سپس وارد اردوگاه می شود و کشیش تا روز صبح ناپاک خواهد بود.\n۸. و کسی که او را بسوزاند، لباس هایش را با آب می شوید و گوشت خود را با آب می شوید و تا روز یکشنبه ناپاک خواهد بود.\n۹. و مردی {که پاک باشد} خاکستر گاو را جمع می کند و آن ها را بدون اردوگاه در مکانی پاک می گذارد و آن را برای جماعت بنی اسرائیل نگه می دارد تا آب جدایی باشد؛ این پاک کننده گناه است.\n۱۰. و کسی که خاکستر گاو را جمع کند، لباس هایش را می شوید و تا زمان تولد ناپاک می ماند؛ و این برای بنی اسرائیل و غریبه ای که در میان آن ها اقامت دارد، برای همیشهٔ قانونی خواهد بود.\n۱۱. کسی که جسد مرده کسی را لمس کند، هفت روز ناپاک خواهد بود. {مرد: عبری. روح انسان}\n۱۲. روز سوم با آن خود را تطهیر خواهد کرد و روز هفتم پاک خواهد بود؛ اما اگر روز سوم خود را پاک نکند، روز هفتم پاک نخواهد بود.\n۱۳. هر که به بدن مرده ای دست بزند و خود را پاک نکند، خیمه خداوند را آلوده می کند؛ و آن روح از اسرائیل قطع خواهد شد: چون آب جدایی بر او پاشیده نشد، ناپاک خواهد شد؛ ناپاکی او هنوز بر او است.\n۱۴. این قانون است، وقتی مردی در خیمه می میرد: هر آنچه وارد خیمه شود و هر آنچه در خیمه است، هفت روز ناپاک خواهد بود.\n۱۵. و هر ظرف باز که پوششی ندارد، ناپاک است.\n۱۶. و هر به کسی که در دشت های باز با شمشیر یا جسد مرده یا استخوان انسان یا قبر کشته شده دست بزند، هفت روز ناپاک خواهد بود.\n۱۷. و برای شخص ناپاک از خاکستر گوساله سوخته تطهیر برای گناه برداشته می شود و آب جاری در ظرف به آن ریخته می شود: خاکستر: عبری. گرد و غبار} {در حال دویدن...: عبری. آب های زنده داده خواهد شد}\n۱۸. و یک فرد پاک باید هیسپ را بردارد، در آب فرو ببرد و بر چادر، بر همه ظروف و کسانی که آنجا بودند و بر کسی که به استخوان، یا کشته شده، یا مرده یا قبر دست زده باشد، بپاشد:\n۱۹. و پاک روز سوم و روز هفتم بر ناپاک می پاشد؛ و روز هفتم خود را پاک می کند، لباس هایش را می شوید، با آب غسل می کند و در برابر پاک می شود.\n۲۰. اما کسی که ناپاک باشد و خود را پاک نکند، آن روح از میان جماعت جدا خواهد شد، زیرا حرم خداوند را آلوده کرده است؛ آب جدایی بر او پاشیده نشده است؛ او ناپاک است.\n۲۱. و برای آن ها قانون دائمی خواهد بود که کسی که آب جدایی را بپاشد، لباس هایش را بشوید؛ و کسی که آب جدایی را لمس کند، تا یکنواخت ناپاک خواهد بود.\n۲۲. و هر آنچه شخص ناپاک لمس کند، ناپاک است؛ و روحی که آن را لمس کند، تا زمانی که یکنواخت شود، ناپاک خواهد بود.","۱. سپس بنی اسرائیل و حتی کل جماعت در ماه اول به بیابان زین آمدند و مردم در قادش ساکن شدند؛ و مریم در آنجا درگذشت و در آنجا به خاک سپرده شد.\n۲. و برای جماعت آبی نبود و آن ها علیه موسی و هارون متحد شدند.\n۳. و مردم با موسی همراه شدند و گفتند: ای خدا، کاش ما در حالی که برادرانمان در برابر خداوند مردند، مرده بودیم!\n۴. و چرا جماعت خداوند را به این بیابان آورده ای تا ما و گاوایمان آنجا بمیریم؟\n۵. و چرا ما را از مصر بیرون آوردید تا به این مکان پلید بیاورید؟ نه جای بذر، نه انجیر، نه تاک، نه انار است؛ هیچ کدام هم آبی برای نوشیدن وجود ندارد.\n۶. و موسی و هارون از حضور جماعت به دروازه خیمه جماعت رفتند و روی صورتشان افتادند و جلال خداوند بر آنان پدیدار شد.\n۷. و خداوند به موسی گفت:\n۸. عصا را بردار و جمع را جمع کن، تو و آرون برادرت، و به صخره ای که در چشمانشان است سخن بگو؛ و آب او را خواهد داد و تو از صخره برایشان آب می آوری؛ پس جماعت و حیواناتشان را نیز می نوشی.\n۹. و موسی عصا را از حضور خداوند برداشت، همان طور که به او فرمان داده بود.\n۱۰. و موسی و هارون جماعت را در برابر صخره جمع کردند و او به آنان گفت: ای شورشیان، اکنون بشنوید؛ باید از این سنگ برایت آب بیاوریم؟\n۱۱. و موسی دستش را بالا برد و با عصایش دو بار به سنگ کوبید، و آب فراوان بیرون آمد و جماعت نوشیدند و حیوانات شان نیز نوشیدند.\n۱۲. و خداوند به موسی و هارون گفت: چون به من ایمان نداشتید تا مرا در چشم بنی اسرائیل تقدیس کنید، پس این جماعت را به سرزمینی که به آن ها داده ام نیاورید.\n۱۳. این {است} آب مریبه؛ زیرا بنی اسرائیل با خداوند جنگیدند و او در آنان تقدیس شد. {مریبه: یعنی، استرایف}\n۱۴. و موسی فرستادگانی از قادش نزد پادشاه ادوم فرستاد، چنین می گوید برادرت اسرائیل، تو از تمام رنج هایی که بر ما گذشته آگاه هستی: {بر ما آمده است...: عبری. ما را پیدا کرد}\n۱۵. چگونه پدران ما به مصر رفتند و ما مدت طولانی در مصر زندگی کرده ایم؛ و مصریان ما و پدرانمان را آزرده کردند:\n۱۶. و وقتی به خداوند دعا کردیم، صدای ما را شنید و فرشته ای فرستاد و ما را از مصر بیرون آورد؛ و اینک ما در قادش هستیم، شهری در دورترین مرز تو:\n۱۷. بگذار از سرزمین تو عبور کنیم: نه از مزارع و نه از تاکستان ها عبور خواهیم کرد، نه از آب چاه ها خواهیم نوشید: از راه پادشاه خواهیم رفت، نه به راست و نه به چپ خواهیم چرخید، تا زمانی که از مرزهای تو عبور نکرده ایم.\n۱۸. و ادوم به او گفت: «از کنار من عبور نکن، وگرنه با شمشیر بر تو حمله می کنم.»\n۱۹. و بنی اسرائیل به او گفتند: ما از راه بزرگ خواهیم رفت؛ و اگر من و گاودانم از آب تو بنوشیم، تاوانش را خواهم داد؛ فقط بدون انجام هیچ کار دیگری، روی پاهایم عبور خواهم کرد.\n۲۰. و او گفت: تو عبور نخواهی کرد. و ادوم با افراد زیاد و دستی قوی علیه او بیرون آمد.\n۲۱. بدین ترتیب ادوم از عبور اسرائیل از مرز خود خودداری کرد؛ بنابراین اسرائیل از او روی گرداند.\n۲۲. و بنی اسرائیل، حتی تمام جماعت، از قادش آمدند و به کوه هور آمدند.\n۲۳. و خداوند به موسی و هارون در کوه هور، در ساحل سرزمین ادوم گفت:\n۲۴. هارون به مردمش جمع خواهد شد، زیرا او وارد سرزمینی که من به بنی اسرائیل داده ام نخواهد شد، زیرا شما در آب مریبا بر فرمان من سرپیچی کردید. {کلمه: عبری. دهان}\n۲۵. هارون و الیعازر پسرش را ببر و آن ها را به کوه هور ببر:\n۲۶. و آرون را از لباس هایش درآورید و بر سر الیعازر پسرش بگذارید، و هارون به قوم خود جمع خواهد شد و در آنجا خواهد مرد.\n۲۷. و موسی همان گونه که خداوند فرمان داده بود، عمل کرد و در حضور همه جماعت به کوه هور رفتند.\n۲۸. و موسی لباس های هارون را از تن آورد و آن را بر الیعازر پسرش پوشید؛ و هارون در بالای کوه درگذشت و موسی و العازر از کوه پایین آمدند.\n۲۹. و وقتی همه جماعت دیدند که هارون مرده است، سی روز برای هارون عزاداری کردند، {حتی} برای تمام خاندان اسرائیل.","۱. و {وقتی} پادشاه عراد کنعانی که در جنوب ساکن بود، شنید که اسرائیل از راه جاسوسان آمده است؛ سپس علیه اسرائیل جنگید و برخی از آن ها را اسیر گرفت.\n۲. و اسرائیل به خداوند سوگند خورد و گفت: اگر واقعا این مردم را به دست من بسپاری، شهرهایشان را کاملا نابود خواهم کرد.\n۳. و خداوند به صدای اسرائیل گوش داد و کنعانیان را رها کرد؛ و آن ها آن ها و شهرهایشان را کاملا ویران کردند؛ و او نام این مکان را هورما نامید. {هورما: یعنی، ویرانی کامل}\n۴. و آنان از کوه هور از راه دریای سرخ حرکت کردند تا سرزمین ادوم را احاطه کنند؛ و روح مردم به خاطر راه بسیار دلسرد شد. {ناامید: یا، غمگین: عبری. کوتاه شده}\n۵. و مردم علیه خدا و موسی سخن گفتند، چرا ما را از مصر بیرون آوردی تا در بیابان بمیریم؟ زیرا نه نان هست، نه آبی هست؛ و روح ما از این نان سبک بیزار است.\n۶. و خداوند مارهای آتشین را در میان مردم فرستاد و آن ها مردم را نیش زدند؛ و بسیاری از مردم اسرائیل جان باختند.\n۷. بنابراین مردم نزد موسی آمدند و گفتند: ما گناه کرده ایم، زیرا علیه خداوند و علیه تو سخن گفته ایم؛ به خداوند دعا کنید که مارها را از ما بگیرد. و موسی برای مردم دعا کرد.\n۸. و خداوند به موسی گفت: تو را مار آتشین بساز و آن را بر میله ای بگذار تا هر که نیش زده شود، وقتی به آن نگاه کند، زنده خواهد ماند.\n۹. و موسی ماری از برنج ساخت و آن را بر تیرک گذاشت و چنین شد که اگر مار کسی را نیش می زد، وقتی مار برنجی را دید، زنده می ماند.\n۱۰. و بنی اسرائیل جلو آمدند و در اوبوت کوبیدند.\n۱۱. و از اوبوت حرکت کردند و در ایجاباریم، در بیابانی که پیش از موآب است، به سوی طلوع آفتاب رفتند. {ایجاباریم: یا، توده هایی از آباریم}\n۱۲. از آنجا حرکت کردند و در دره زرد ساکن شدند.\n۱۳. از آنجا رفتند و در سوی دیگر آرنون که {هست} در بیابان هایی که از سواحل اموریان بیرون می آید فرود آمدند؛ زیرا آرنون {است} مرز موآب، میان موآب و اموریان.\n۱۴. به همین دلیل در کتاب جنگ های خداوند آمده است، آنچه او در دریای سرخ و جویبارهای آرنون انجام داد، {چه...: یا، وهب در سوفا}\n۱۵. و در کنار جویبارهایی که به اقامتگاه آر می ریزد و بر مرز موآب قرار دارد. {lieth: عبری. leaneth}\n۱۶. و از آنجا {رفت} به بیر: همان چاه ای که خداوند به موسی گفت: مردم را جمع کنید تا به آن ها آب بدهم.\n۱۷. سپس اسرائیل این سرود را خواند: «بشک، ای چاه»؛ برایش بخوانید: {بهار...: عبری. صعود} {خواندن: یا، پاسخ دادن}\n۱۸. شاهزادگان چاه را کندند، اشراف مردم به دستور قانون گذار، با عصاهایشان آن را کندند. و از بیابان {رفتند} به متانه:\n۱۹. و از متانا تا نهالیئل؛ و از نهالئیل تا باموث:\n۲۰. و از باموت {در} دره، که {است} در سرزمین موآب، تا بالای پیسگاه که به سوی یشیمون نگاه می کند. {کشور: عبی. دشت} {پیسگاه: یا، تپه} {یشیمون: یا، بیابان}\n۲۱. و اسرائیل فرستادگانی نزد سیحون، پادشاه آموری ها فرستاد و گفت:\n۲۲. بگذار از سرزمین تو عبور کنم: ما به مزارع یا تاکستان ها نخواهیم رفت؛ ما آب های چاه را نمی نوشیم: {اما} از راه {بلند} پادشاه پیش خواهیم رفت تا از مرزهای تو عبور کنیم.\n۲۳. و سیحون اجازه نداد اسرائیل از مرز او عبور کند، اما سیحون همه قوم خود را گرد آورد و به بیابان علیه اسرائیل رفت، و نزد جهاز آمد و علیه اسرائیل جنگید.\n۲۴. و اسرائیل با نوک شمشیر به او ضربه زد و سرزمینش را از آرنون تا یابوک و حتی تا فرزندان آمون تصرف کرد؛ زیرا مرز فرزندان آمون {بود} استوار بود.\n۲۵. و اسرائیل همه این شهرها را گرفت؛ و اسرائیل در همه شهرهای اموری، در هشبون و همه روستاهای آن ساکن شد. {روستاها: عبری. دختران}\n۲۶. زیرا هشبون شهر سیحون پادشاه آموری ها بود که علیه پادشاه پیشین موآب جنگیده بود و تمام زمین هایش را از دست خود گرفت، حتی تا آرنون.\n۲۷. به همین دلیل کسانی که در امثال سخن می گویند «به هشبون بیا، شهر سیحون ساخته و آماده شود:\n۲۸. زیرا آتشی از هشبون خاموش شده است، شعله ای از شهر سیهون: این شعله آر موآب و اربابان ارتفاعات آرنون را بلعیده است.\n۲۹. وای بر تو، موآب! ای مردم کموش، تو نابود شده ای: او پسرانش را که گریخته بودند و دخترانش را به اسارت سیهون، پادشاه آموری ها داده است.\n۳۰. به آن ها شلیک کردیم؛ هشبون حتی تا دیبون نابود شد و ما آن ها را تا نوفا، که به مدبا می رسد، نابود کردیم.\n۳۱. بدین ترتیب اسرائیل در سرزمین اموریان ساکن شد.\n۳۲. و موسی برای جاسوسی یازر فرستاد و آن ها روستاهای آن را گرفتند و آموری هایی که آنجا بودند را بیرون راندند.\n۳۳. و آن ها برگشتند و از راه باشان بالا رفتند؛ و اوگ، پادشاه باشان، او و همه قومش به سوی نبرد ادره رفت.\n۳۴. و خداوند به موسی گفت: از او نترس، زیرا او را به دست تو سپردم، و همه مردم و سرزمینش؛ و با او همان گونه رفتار خواهی کرد که با سیهون، پادشاه آموریان، که در هشبون ساکن بود، انجام دادی.\n۳۵. پس او و پسرانش و همه مردمش را کشتند تا هیچ زنده از او باقی نماند و سرزمینش را تصاحب کردند.","۱. و بنی اسرائیل پیش رفتند و در دشت های موآب در این سوی اردن [توسط اریحا] زمین را بستند.\n۲. و بالاق پسر زیپور همه آنچه اسرائیل بر آموری ها کرده بود را دید.\n۳. و موآب از مردم به شدت می ترسید، زیرا آن ها بسیار بودند؛ و موآب به خاطر بنی اسرائیل ناراحت بود.\n۴. و موآب به بزرگان مدیان گفت: اکنون این گروه همه کسانی را که اطراف ما هستند لیس خواهند زد، همان طور که گاو علف های مزرعه را لیس می زند. و بالاک پسر زیپور در آن زمان پادشاه موآب ها بود.\n۵. بنابراین فرستادگانی نزد بلعام پسر بئور به پتور فرستاد، که در کنار رود سرزمین فرزندان قومش است، تا او را فرا بخوانند و بگویند: اینک مردمی از مصر بیرون آمده اند: آگاه، آن ها روی زمین را می پوشانند و در برابر من ایستاده اند: {چهره: عبری. چشم}\n۶. پس اکنون بیا، از تو می خواهم، این مردم را نفرین کن؛ زیرا آن ها برای من بیش از حد قدرتمندند: شاید پیروز شوم، تا آن ها را نابود کنیم و بتوانم آن ها را از زمین بیرون کنم؛ زیرا می خواهم کسی که تو برکت می دهی مبارک باشد و کسی که نفرین می کنی نفرین شود.\n۷. و بزرگان موآب و بزرگان مدیان با پاداش فال در دست خود رفتند؛ و نزد بلعام آمدند و سخنان بالاک را به او گفتند.\n۸. و به آنان گفت: امشب اینجا اقامت کنید و من دوباره به شما خبر خواهم داد، همان گونه که خداوند با من سخن خواهد گفت: و شاهزادگان موآب با بلعام اقامت دارند.\n۹. و خدا نزد بلعام آمد و گفت: این مردان با تو چه کسانی هستند؟\n۱۰. و بلعام به خدا گفت، بالاق پسر زیپور، پادشاه موآب، نزد من فرستاده است و {می گوید}،\n۱۱. بنگر، {آنجا} مردمی از مصر بیرون می آیند که روی زمین را پوشانده اند: اکنون بیا، مرا نفرین کن؛ شاید بتوانم بر آن ها غلبه کنم و بیرون راندم. {من...: عبری. من در مبارزه با او پیروز خواهم شد}\n۱۲. و خدا به بلعام گفت: تو با آنان نخواهی رفت؛ تو نباید مردم را نفرین کنی: زیرا آن ها مبارک هستند.\n۱۳. و بلعام صبح برخاست و به شاهزادگان بالاک گفت: به سرزمین خود بروید، زیرا خداوند اجازه نمی دهد با شما بروم.\n۱۴. و شاهزادگان موآب برخاستند و به بالاک رفتند و گفتند: بلعام از آمدن با ما امتناع می کند.\n۱۵. و بالاک بار دیگر شاهزادگانی فرستاد، بیشتر و شریف تر از آنان.\n۱۶. و آنان نزد بلعام آمدند و به او گفتند: «بلاک پسر زیپور چنین می گوید: «خواهش می کنم هیچ چیز مانع آمدنت نزد من نشود: {بگذار...: عبری. مانع نشو و غیره}\n۱۷. زیرا تو را به شرافت بسیار بزرگی ارتقا خواهم داد و هر آنچه به من بگویی انجام خواهم داد: پس بیا، از تو می خواهم این مردم را نفرین کنم.\n۱۸. و بلعام پاسخ داد و به بندگان بالک گفت: اگر بالک خانه اش را پر از نقره و طلا به من بدهد، نمی توانم فراتر از کلام خداوند خدای من بروم، که کمتر یا بیشتر انجام دهم.\n۱۹. پس اکنون از شما می خواهم که امشب نیز اینجا بمانید تا بدانم خداوند بیشتر چه خواهد گفت.\n۲۰. و خدا شبانه نزد بلعام آمد و به او گفت: اگر مردان آمدند تا تو را صدا بزنند، برخیز و با آن ها برو؛ اما با این حال، سخنی که به تو خواهم گفت، این است که خواهی گفت.\n۲۱. و بلعام صبح برخاست، زین کرد و با شاهزادگان موآب رفت.\n۲۲. و خشم خدا شعله ور شد چون او رفت: و فرشته خداوند در برابر دشمنی علیه او ایستاد. حالا او سوار بر باسنش بود و دو خدمتکارش هم همراهش بودند.\n۲۳. و خر فرشته خداوند را دید که در راه ایستاده و شمشیرش را در دست کشیده بود؛ و الاغ کنار رفت و به دشت رفت؛ و بلعام الاغ را زد تا او را به راه بیندازد.\n۲۴. اما فرشته خداوند در مسیر تاکستان ها ایستاده بود، دیواری در این طرف و دیواری در آن طرف.\n۲۵. و وقتی الاغ فرشته خداوند را دید، خود را به دیوار کوبید و پای بلعام را به دیوار کوبید و او دوباره او را زد.\n۲۶. و فرشته خداوند فراتر رفت و در مکانی باریک ایستاد، جایی که {هیچ راهی نبود} که نه به راست و نه به چپ بچرخد.\n۲۷. و وقتی الاغ فرشته خداوند را دید، زیر بلعام افتاد: و خشم بلعام شعله ور شد و با عصا خر را زد.\n۲۸. و خداوند دهان الاغ را باز کرد و به بلعام گفت: «چه کرده ام که این سه بار مرا زده ای؟»\n۲۹. و بلعام به الاغ گفت: «چون مرا مسخره کردی: کاش شمشیری در دستم بود، چون اکنون تو را می کشم.»\n۳۰. و الاغ به بلعام گفت: آیا من خر تو نیستم که از زمانی که من تا امروز بر او سوار شده ام؟ آیا من هرگز می خواستم این کار را با تو انجام دهم؟ و او گفت: نه. {در...: عبری. کسی که بر من سوار شده است} {از آن زمان...: یا از وقتی که تو غرق شدی، و غیره}\n۳۱. سپس خداوند چشمان بلعام را گشود و فرشته خداوند را دید که سر راهش ایستاده و شمشیرش را در دست کشیده بود، و سرش را خم کرد و روی صورتش افتاد. {افتاد...: یا، خودش را تعظیم کرد}\n۳۲. و فرشته خداوند به او گفت: چرا این سه بار به خرت زده ای؟ ببین، من رفتم تا در برابر تو مقاومت کنم، زیرا راه تو پیش من منحرف است: {به...: عبرانی. تا دشمن تو باشم}\n۳۳. و الاغ مرا دید و سه بار از من روی برگرداند: مگر اینکه از من روی برگردانده باشد، مطمئنا اکنون نیز تو را کشته و زنده نجات داده ام.\n۳۴. و بلعام به فرشته خداوند گفت: من گناه کرده ام؛ زیرا نمی دانستم که تو در برابر من ایستاده ای؛ پس اکنون، اگر این موضوع تو را ناراحت می کند، بازمی گردم. {ناراضی...: عبری. در چشمانت شرور باش}\n۳۵. و فرشته خداوند به بلعام گفت: «با مردم برو، اما فقط کلمه ای که به تو خواهم گفت و تو خواهی گفت.» پس بلعام با شاهزادگان بالاک رفت.\n۳۶. و وقتی بالک شنید که بلعام آمده، برای دیدار با او به شهری به نام موآب رفت که در مرز آرنون قرار دارد، که در دورترین ساحل قرار دارد.\n۳۷. و بالاک به بلعام گفت: آیا من با جدیت به تو نفرستادم تا تو را فرا بخوانم؟ چرا نزد من نیامدی؟ آیا واقعا نمی توانم تو را به مقام احترام ببرم؟\n۳۸. و بلعام به بالاک گفت: «آگاه، من نزد تو آمده ام: آیا اکنون هیچ قدرتی برای گفتن دارم؟» کلمه ای که خدا در دهانم گذاشته، که من خواهم گفت.\n۳۹. و بلعام با بالاک رفت و به کیرجاثوزوت آمدند. {کیرجاثوزوت: یا شهری از خیابان ها}\n۴۰. و بالاق گاو و گوسفند تقدیم کرد و نزد بلعام و شاهزادگانی که با او بودند فرستاد.\n۴۱. و فردا شد که بالاک بلعام را گرفت و به بلندی های بعل برد تا از آنجا بتواند بیشترین بخش مردم را ببیند.","۱. و بلعام به بالاک گفت: برایم اینجا هفت قربانگاه بساز و برایم هفت گاو و هفت قوچ آماده کن.\n۲. و بالاک همان طور که بلعام گفته بود عمل کرد؛ و بالک و بلعام بر هر محراب یک گاو و یک قوچ تقدیم کردند.\n۳. و بلعام به بالاق گفت: کنار قربانی سوختنت بایست و من می روم: شاید خداوند به دیدارم بیاید؛ و هرچه به من نشان دهد، به تو خواهم گفت. و به جایگاه بالایی رفت. {به یک...: یا، انفرادی}\n۴. و خداوند با بلعام دیدار کرد و به او گفت: من هفت قربانگاه آماده کرده ام و بر هر محراب یک گاو و یک قوچ تقدیم کرده ام.\n۵. و خداوند کلمه ای در دهان بلعام گذاشت و گفت: بازگرد به بالاک، و این گونه سخن خواهی گفت.\n۶. و او به سوی او بازگشت و دید که او و همه شاهزادگان موآب بر قربانی سوخته اش ایستادند.\n۷. و او تمثیل خود را برداشت و گفت: بالاک پادشاه موآب مرا از آرام، از کوه های شرق آورده است و {گفت} «بیا، مرا لعنت کن یعقوب، و بیا، اسرائیل را به چالش بکش.»\n۸. چگونه باید نفرین کنم، کسی که خدا نفرین نکرده است؟ یا چگونه باید مخالفت کنم، {کسی که} خداوند در برابر او مقاومت نکرده است؟\n۹. زیرا از بالای صخره ها او را می بینم و از کوه ها او را می بینم: مردم تنها ساکن خواهند شد و در میان ملت ها حساب نخواهند شد.\n۱۰. چه کسی می تواند خاک یعقوب و عدد بخش چهارم اسرائیل را بشمارد؟ بگذار مرگ درستکاران بمیرم و پایان آخرم مثل او باشد! {من: عبری. روح من، یا زندگی من}\n۱۱. و بالک به بلعام گفت: با من چه کرده ای؟ تو را بردم تا دشمنانم را نفرین کنی، و ببین، تو همه آن ها را برکت داده ای.\n۱۲. و او پاسخ داد و گفت: «آیا نباید مراقب باشم آنچه خداوند در دهانم گذاشته است را بگویم؟»\n۱۳. و بالاک به او گفت: بیا، از تو می خواهم با من به جایی دیگر بروی، جایی که آن ها را ببینی: تو فقط بخش اعظم آن ها را خواهی دید و همه را نخواهی دید؛ و از آنجا مرا نفرین کن.\n۱۴. و او را به مزرعه زوفیم، به بالای پسگاه آورد و هفت محراب ساخت و یک گاو نر و یک قوچ بر هر محراب تقدیم کرد. {پیسگاه: یا، تپه}\n۱۵. و او به بالاک گفت: اینجا کنار قربانی سوختنت بایست، در حالی که من آن سوی [خداوند} را ملاقات می کنم.\n۱۶. و خداوند با بلعام روبرو شد و کلمه ای در دهانش گذاشت و گفت: «دوباره به بالاک برو و این را بگو.»\n۱۷. و وقتی نزد او آمد، دید که کنار قربانی سوختنش ایستاده بود و شاهزادگان موآب نیز با او بودند. و بالاک به او گفت: خداوند چه گفته است؟\n۱۸. و او تمثیل خود را برداشت و گفت: برخیز، بالاک، و بشنو؛ به من گوش کن، ای پسر زیپور:\n۱۹. خدا {هست} انسان نیست که دروغ بگوید؛ نه پسر انسان که باید توبه کند: آیا گفته و آیا انجام نخواهد داد؟ یا سخن گفته و آیا آن را خوب نخواهد کرد؟\n۲۰. اینک، من {فرمان} برای برکت دریافت کرده ام: و او برکت داده است؛ و نمی توانم آن را برگردانم.\n۲۱. او در یعقوب گناه ندیده و در اسرائیل انحرافی ندیده است: خداوند خدای او با اوست و فریاد پادشاهی در میان آنهاست.\n۲۲. خدا آن ها را از مصر بیرون آورد؛ او گویی قدرت یک تک شاخ را دارد.\n۲۳. مطمئنا هیچ طلسمی علیه یعقوب نیست و هیچ فال گیری علیه اسرائیل نیست؛ بر اساس این زمان درباره یعقوب و اسرائیل گفته خواهد شد: خدا چه آفریده است! {مخالف: یا، در}\n۲۴. اینک، مردم مانند شیری بزرگ برمی خیزند و خود را مانند شیر جوان بلند می کنند: او تا زمانی که شکار را نخورد و خون کشته شدگان را ننوشد، دراز نخواهد کشید.\n۲۵. و بالاق به بلعام گفت: اصلاً آن ها را نفرین نکن و اصلا آن ها را برکت نده.\n۲۶. اما بلعام پاسخ داد و به بالک گفت: «آیا به تو نگفتم که هر آنچه خداوند می گوید، باید انجام دهم؟»\n۲۷. و بالک به بلعام گفت: بیا، از تو می خواهم تو را به جای دیگری ببرم؛ شاید خدا خوشنود باشد که آن ها را از آنجا نفرین کنم.\n۲۸. و بالاق بلعام را به بالای پئور آورد، که به یشیمون نگاه می کند.\n۲۹. و بلعام به بالاک گفت: برایم اینجا هفت قربانگاه بساز و برایم هفت گاو نر و هفت قوچ آماده کن.\n۳۰. و بالاق همان طور که بلعام گفته بود، عمل کرد و یک گاو و یک قوچ بر هر محراب تقدیم کرد.","۱. و وقتی بلعام دید که خداوند از برکت دادن به اسرائیل خوشایند است، مانند زمان های دیگر برای جستجوی طلسم ها نرفت، بلکه روی خود را به سوی بیابان چرخاند. {برای جستجو...: عبری. به دیدار\n۲. و بلعام چشمانش را بالا آورد و دید که اسرائیل {در خیمه هایش} طبق قبیله هایشان اقامت دارند؛ و روح خدا بر او نازل شد.\n۳. و او تمثیل خود را برداشت و گفت: بلعام پسر بئور گفته است، و مردی که چشمانش باز است گفته است: {که...: عبری. کسی که چشمانش را بسته بود، اما حالا باز شده بود}\n۴. او که سخنان خدا را شنید، که رؤیای قادر مطلق را دید، فرو رفت {در خلسه} اما چشمانش باز بود:\n۵. ای یعقوب، خیمه هایت چه نیکو است، {و} خیمه های تو، ای اسرائیل!\n۶. همان طور که دره ها گسترده اند، مانند باغ هایی در کنار رودخانه، مانند درختان آلوئه وئه که خداوند کاشته است، {و} مانند درختان سدر کنار آب ها.\n۷. او آب را از سطل هایش خواهد ریخت و بذرش در آب های بسیاری خواهد بود و پادشاهش بالاتر از آگاگ خواهد بود و پادشاهی اش بلند خواهد شد.\n۸. خدا او را از مصر بیرون آورد؛ او مانند یک تک شاخ قدرت دارد: ملت ها را دشمنانش خواهد خورد و استخوان هایشان را خواهد شکست و با تیرهایش آن ها را خواهد شکافت.\n۹. او به شکل شیر دراز کشید و مانند شیر بزرگ: چه کسی او را به حرکت درآورد؟ مبارک است کسی که تو را برکت می دهد و نفرین شده کسی که تو را نفرین می کند.\n۱۰. و خشم بالاک بر بلعام شعله ور شد و دستانش را به هم کوبید: و بالک به بلعام گفت: من تو را فراخواندم تا دشمنانم را نفرین کنی و ببین، تو این سه بار همه را برکت داده ای.\n۱۱. پس اکنون به جای خود فرار کن: فکر کردم تو را به مقام بزرگی ارتقا دهم؛ اما خداوند تو را از شرافت بازداشته است.\n۱۲. و بلعام به بالاک گفت: «من نیز به فرستادگانت که برایم فرستادی نگفتم:\n۱۳. اگر بالاک خانه اش را پر از نقره و طلا به من بدهد، نمی توانم فراتر از فرمان خداوند بروم، نه خیر و نه بدی در دل خودم؛ {اما} آنچه خداوند می گوید که من سخن می گویم؟\n۱۴. و اکنون، اینک، من به سوی مردمم می روم: بیایید {بنابراین} و به تو اعلام خواهم کرد که این مردم در روزهای آخر با مردم تو چه خواهند کرد.\n۱۵. و او تمثیل خود را برداشت و گفت: بلعام پسر بئور گفته و مردی که چشمانش باز است گفته است:\n۱۶. او که سخنان خدا را شنید و دانش خداوند متعال را دانست، {که دیدگاه} قادر مطلق را دید که {در خلسه فرو رفت} اما چشمانش باز بود:\n۱۷. او را خواهم دید، اما نه اکنون: او را خواهم دید، اما نزدیک نخواهد بود: ستاره ای از یعقوب بیرون خواهد آمد و عصایی از اسرائیل برخواهد آمد و گوشه های موآب را خواهد درنوردید و همه فرزندان شث را نابود خواهد کرد. {ضربه بزن...: یا، شاهزادگان را بزن}\n۱۸. و ادوم دارایی خواهد بود، سعیر نیز دارایی دشمنانش خواهد بود؛ و اسرائیل شجاعانه عمل خواهد کرد.\n۱۹. از یعقوب هر که فرمانروایی کند بیرون خواهد آمد و باقی مانده های شهر را نابود خواهد کرد.\n۲۰. و وقتی به عمالیق نگاه کرد، تمثیل خود را برداشت و گفت: عمالیق نخستین ملت بود؛ اما سرانجام او {خواهد بود} که برای همیشه نابود خواهد شد. {ملت ها: ملت هایی که علیه اسرائیل جنگیدند} {آن...: یا حتی به نابودی}\n۲۱. و او به کنیان نگاه کرد، تمثیل خود را برداشت و گفت: اقامتت قوی است و تو لانه ات را در صخره می گذاری.\n۲۲. با این حال، کنیان هدر خواهند رفت، تا زمانی که آشور تو را اسیر کند. {کنیتی: عبری. کاین} {تا اینکه...: وگرنه چقدر طول می کشد تا آشور تو را اسیر کند}\n۲۳. و او تمثیل خود را برداشت و گفت: ای وای، چه کسی زنده خواهد ماند وقتی خدا این کار را بکند!\n۲۴. و کشتی ها از ساحل چیتیم خواهند آمد و آشور را آزار خواهند داد و ابر را رنج خواهند داد و او نیز برای همیشه نابود خواهد شد.\n۲۵. و بلعام برخاست، رفت و به جای خود بازگشت؛ و بالاق نیز به راه خود رفت.","۱. و اسرائیل در شیتیم ساکن شد و مردم شروع به فحشا با دختران موآب کردند.\n۲. و مردم را به قربانی های خدایانشان فراخواندند: و مردم خوردند و به خدایان خود تعظیم کردند.\n۳. و اسرائیل به بعلپور پیوست و خشم خداوند بر اسرائیل شعله ور شد.\n۴. و خداوند به موسی گفت: همه سرهای مردم را بردار و آن ها را در برابر خورشید پیش خداوند آویزان کن تا خشم شدید خداوند از اسرائیل دور شود.\n۵. و موسی به داوران اسرائیل گفت: «هر یک از مردانش که به بعلپور پیوسته بودند را بکشید.\n۶. و اینگاه، یکی از فرزندان اسرائیل آمد و زنی مدیانی را نزد برادرانش آورد، در برابر موسی و در برابر همه جماعت بنی اسرائیل که {در برابر} در خیمه جماعت گریه می کردند.\n۷. و وقتی فینه حاس، پسر العازر، پسر هارون کاهن، آن را دید، از میان جماعت برخاست و نیزه ای در دست گرفت؛\n۸. و مرد اسرائیل را به داخل خیمه برد و هر دو را از میان آن ها فرو کرد، مرد اسرائیل و زن را از شکمش عبور داد. بنابراین طاعون از دست بنی اسرائیل بازداشته شد.\n۹. و کسانی که در طاعون مردند، بیست و چهار هزار نفر بودند.\n۱۰. و خداوند به موسی گفت:\n۱۱. فینحاس، پسر العازر، پسر هارون کاهن، خشم مرا از بنی اسرائیل برداشته است، در حالی که او برای من در میان آنان به خاطر من تعصب داشت که من در حسادت خود بنی اسرائیل را نخورم. {برای...: عبری. با شور و اشتیاقم}\n۱۲. پس بگو، اینک، عهد صلح خود را به او می سپارم:\n۱۳. و او آن را خواهد داشت و نسل خود پس از او، {حتی} عهد کاهنی جاودان؛ زیرا برای خدای خود تعصب داشت و برای بنی اسرائیل کفاره داد.\n۱۴. اکنون نام اسرائیلی که کشته شد، {حتی} که با زن مدیانی کشته شد، {بود} زیمری، پسر سالو، شاهزاده یکی از خاندان های اصلی سیمئونیان. {رئیس...: عبری. خانه یک پدر}\n۱۵. و نام زن مدیانی که کشته شد، کوزبی، دختر زور بود؛ او رئیس یک قوم و خاندان رئیس در مدیان بود.\n۱۶. و خداوند به موسی گفت:\n۱۷. مدیانی ها را آزار بده و آن ها را نابود کن:\n۱۸. زیرا آن ها با حیله های خود که در موضوع پیئور و در مورد کوزبی، دختر شاهزاده ای از مدیان، خواهرشان، که در روز طاعون به خاطر پیئور کشته شد، تو را آزار می دهند.","۱. و پس از طاعون چنین شد که خداوند به موسی و الیعازر پسر هارون کاهن گفت:\n۲. مجموع همه جماعت بنی اسرائیل، از بیست سال به بعد، در سراسر خانه پدران شان، همه کسانی که قادر به جنگ در اسرائیل هستند را در نظر بگیرید.\n۳. و موسی و الیعازر کاهن در دشت های موآب در نزدیکی اردن اریحا با آنان گفتند:\n۴. {مجموع مردم را بگیر}، از بیست سال به بالا؛ چنان که خداوند به موسی و بنی اسرائیل فرمان داد که از سرزمین مصر بیرون آمدند.\n۵. روبن، پسر ارشد اسرائیل: فرزندان روبن؛ حنوخ، {که از آن ها می آید} خانواده هانوخیت ها: از پالو، خانواده پالوئی:\n۶. از حسرون، خانواده حزرونی: از کارمی، خانواده کارمیت ها.\n۷. این ها خانواده های روبنی ها هستند: و شمارش آن ها چهل و سه هزار و هفتصد و سی نفر بود.\n۸. و پسران پالو؛ الیاب.\n۹. و پسران الیاب؛ نموئل و داتان و ابیرام. این همان داتان و ابیرام است که در جماعت مشهور بودند و در جمع قورح علیه موسی و هارون جنگیدند، زمانی که علیه خداوند جنگیدند:\n۱۰. و زمین دهانش را باز کرد و آن ها را همراه با قورح بلعید، وقتی آن گروه مردند، همان زمانی که آتش دویست و پنجاه مرد را بلعید: و آن ها نشانه ای شدند.\n۱۱. با این حال، فرزندان قورح نمردند.\n۱۲. پسران شمعون به نام خانواده هایشان: نموئیل، خاندان نموئیلی ها؛ یامین، خاندان یامینی ها: یاخین، خانواده یاخینیان: {نمعیل: همچنین یموئیل} {یاخین: همچنین جریب}\n۱۳. از زرح، خاندان زرهی: خاندان شائول، خاندان شائولیان. {زراه: همچنین زوهار نامیده می شود}\n۱۴. این ها خانواده های سیمئونیان، بیست و دو هزار و دویست نفر هستند.\n۱۵. فرزندان گاد بر اساس خانواده هایشان: زفون، خانواده زفونیان: خانواده حگی، خانواده حگی: شونی، خانواده شونی ها: {زفون: همچنین زیفیون}\n۱۶. از اوزنی، خانواده اوزنیت ها: از اری، خانواده اریت: {اوزنی: همچنین به نام ازبون}\n۱۷. از آرود، خانواده آرودی ها: از آرلی، خانواده آرلی ها. {آرود: همچنین آرودی نامیده می شود}\n۱۸. این ها خانواده های فرزندان گاد طبق شمارش آن ها چهل هزار و پانصد نفر هستند.\n۱۹. پسران یهودا ار و اونان بودند: و ار و اونان در سرزمین کنعان درگذشتند.\n۲۰. و پسران یهودا پس از خانواده هایشان عبارت بودند از؛ از شلا، خاندان شلانیان؛ از فارز، خانواده فارزیان: از زراه، خاندان زرحیان.\n۲۱. و پسران فارز عبارت بودند از؛ از حسرون، خانواده حزرونی ها؛ از حمول، خانواده حمولیان.\n۲۲. این ها خانواده های یهودا بر اساس شمارش آن ها، سیصد و شانزده هزار و پانصد هستند.\n۲۳. {از} پسران ایساکار پس از خانواده هایشان: {از} تولا، خانواده تولای ها: پوآ، خانواده پونیته: {پوآ: یا، فووا}\n۲۴. از یاشوب، خانواده یشوبیت ها: از شیمرون، خانواده شیمرونی ها. {یا، ایوب}\n۲۵. این ها خانواده های یساکار به گفته کسانی که شمارش شده اند، سیصد و چهار هزار و سیصد هستند.\n۲۶. {از} پسران زبولون به نام خانواده هایشان: از سرد، خانواده ساردیت ها؛ از ایلون، خانواده الونی ها: از جهلیل، خانواده جاهلی ها.\n۲۷. این ها خانواده های زبولونی ها بر اساس شمارش آن ها، سیصد هزار و پانصد نفر هستند.\n۲۸. پسران یوسف پس از خانواده هایشان منشه و افرایم بودند.\n۲۹. از پسران منسی: از ماخیر، خاندان ماخیریان؛ و ماخیر گیلعاد را به دنیا آورد: از گلعاد {بیایید} خانواده گیلعادیان.\n۳۰. این ها پسران جلعاد: {از} جیزر، خانواده یعزری: از هلک، خانواده هلکی ها: {جیزر: همچنین ابیعازر نامیده می شود}\n۳۱. و {از} آسرئیل، خانواده عسریلیان؛ و {از} شخم، خانواده شکیمیان:\n۳۲. و {از} شمیدا، خانواده شمیدایان؛ و {از} هفر، خانواده هفریت.\n۳۳. و زلوفه هاد پسر هفر پسری جز دختر نداشت؛ و نام های دختران زلوفهاد مهله و نوح، حوغلا، میلکه و تیرزا بود.\n۳۴. این ها خانواده های منسی و کسانی که شمارش شده اند، پنجاه و دو هزار و هفتصد نفر هستند.\n۳۵. این ها پسران افرایم پس از خانواده هایشان هستند: از شوثلا، خانواده شوتالی ها؛ از بخر، خانواده بکریت ها: از تاهان، خانواده تهانی. {بخر: همچنین به نام برد شناخته می شود}\n۳۶. و این ها پسران شوتله هستند: از اران، خاندان ارنی.\n۳۷. این ها خانواده های پسران افرایم طبق شمارش سی و دو هزار و پانصد نفر هستند. این ها پسران یوسف به نام خانواده هایشان هستند.\n۳۸. پسران بنیامین به نام خانواده هایشان: از بلا، خاندان بلایی ها: از اشبل، خانواده اشبلیت ها: از آهیرام، خانواده آهیرامیان: {آهیرام: همچنین به نام ایحی یا آهارا}\n۳۹. از شوفام، خانواده شوفامی ها: از هوفام، خانواده هوفامی ها. {شافام... هوفام: همچنین به نام های موپیم و هوپیم شناخته می شود.\n۴۰. و پسران بلا، ارد و نعمان: {از ارد}، خانواده اردیت ها؛ {و} از نعمان، خاندان نعمیان. {آرد: همچنین آدار نامیده می شود}\n۴۱. این ها پسران بنیامین بر اساس خانواده هایشان هستند؛ و شمارش آن ها چهل و پنج هزار و ششصد نفر بود.\n۴۲. این ها پسران دان به نام خانواده هایشان هستند: از شوهام، خانواده شوهامیان. این ها خانواده های دن پس از خانواده هایشان هستند. {شوهام: یا، هوشیم}\n۴۳. تمام خانواده های شوهامیان، طبق شمارش آن ها، سیصد و چهار هزار و چهارصد نفر بودند.\n۴۴. {از} فرزندان آشر به نام خانواده هایشان: از جیمنا، خانواده جمنی ها؛ از یسوئی، خانواده یسوعیان: از بریاه، خانواده بریایی.\n۴۵. از پسران بریا: از حبر، خانواده هبری ها: از مالکیل، خانواده مالکیلیان.\n۴۶. و نام دختر آشر {بود} سارا.\n۴۷. این ها خانواده های پسران آشر طبق شمارش آن ها هستند؛ {که بودند} پنجاه و سه هزار و چهارصد.\n۴۸. {از} پسران نفتالی بر اساس خانواده هایشان: از جهزیل، خانواده جاهزلیت ها: از گونی، خانواده گونیت ها:\n۴۹. از یزر، خانواده یزری ها: از شیلم، خانواده شیلمی ها. {شیلم: همچنین شلوم نامیده می شود}\n۵۰. این ها خانواده های نفتالی بر اساس خانواده هایشان هستند؛ و شمارش آن ها چهل و پنج هزار و چهارصد نفر بود.\n۵۱. این ها شمار بنی اسرائیل بودند، ششصد هزار و هزار و هفتصد و سی نفر.\n۵۲. و خداوند به موسی گفت:\n۵۳. زمین بر اساس تعداد نام ها برای ارث تقسیم می شود.\n۵۴. به بسیاری ارث بیشتری خواهی داد و به تعداد کمی ارث کمتر خواهی داد: به هر ارث خود را بر اساس کسانی که از او شمرده شده اند، خواهد داد. {بیشتر بده...: عبری. ارث او را ضرب کن} {کمتر بده...: عبری. ارثیه اش را کاهش دهد}\n۵۵. با این حال، زمین به صورت قرعه تقسیم می شود: بر اساس نام قبایل نیانشان که به ارث می برند.\n۵۶. بر اساس قطعه زمین، مالکیت آن بین تعداد زیاد و تعداد کمی تقسیم خواهد شد.\n۵۷. و این ها کسانی هستند که از لاویان بر اساس خانواده هایشان شمارش شده اند: از گرشون، خانواده گرشونیان؛ از کوحات، خانواده کوهاتی: از مراری، خانواده مراری.\n۵۸. این ها عبارتند از: خانواده لیبنی، خانواده هبرونیان، خانواده محلیان، خانواده موشیت ها، خانواده قراطیان. و کوهات عمرام را به دنیا آورد.\n۵۹. و نام همسر عمرام، یوچبد، دختر لاوی بود که مادرش او را در مصر به لاوی رساند؛ و او به عمرام، هارون و موسی و خواهرشان مریم را به دنیا آورد.\n۶۰. و از هارون نادب، و ابیهو، الیعازر و ایثمار به دنیا آمدند.\n۶۱. و نداب و آبیهو مردند، زمانی که آتش عجیبی را پیش خداوند تقدیم کردند.\n۶۲. و آنان که شمارش شدند بیست و سه هزار نفر بودند، همه نر از یک ماهه و بالاتر؛ زیرا در میان بنی اسرائیل شمارش نشدند، زیرا در میان بنی اسرائیل هیچ میراثی به آنان داده نشده بود.\n۶۳. این ها کسانی هستند که توسط موسی و الیعازر کاهن شماره گذاری شدند، کسانی که بنی اسرائیل را در دشت های موآب در نزدیکی اردن {نزدیک} اریحا شمارش کردند.\n۶۴. اما در میان آنان هیچ مردی نبود که موسی و هارون کاهن را زمانی که بنی اسرائیل را در بیابان سینا می شمردند، بشمارند.\n۶۵. زیرا خداوند درباره آن ها گفته بود: آن ها حتما در بیابان خواهند مرد. و هیچ مردی از آن ها باقی نماند، جز کالب، پسر یفونه، و یوشع پسر راهبه.","۱. سپس دختران زلوفحد، پسر هفر، پسر جلعاد، پسر ماخیر، پسر مناسی، از خاندان های منسی پسر یوسف آمدند؛ و این ها نام دختران او هستند؛ محله، نوح، و هوغلا، و میلکه و تیرزا.\n۲. و در برابر موسی و در برابر الیعازر کاهن و در برابر شاهزادگان و همه جماعت، {کنار در} خیمه جماعت ایستادند و گفتند:\n۳. پدر ما در بیابان مرد، و او در جمع کسانی نبود که در جمع قورح علیه خداوند متحد شدند؛ اما در گناه خود درگذشت و پسری نداشت.\n۴. چرا باید نام پدر ما در میان خانواده اش حذف شود، چون او پسری ندارد؟ به ما دارایی ای در میان برادران پدرمان عطا کن. {تمام...: عبری. کاهش یافته}\n۵. و موسی علت آن ها را نزد خداوند آورد.\n۶. و خداوند به موسی گفت:\n۷. دختران زلفهاد درست می گویند: تو قطعا به آن ها دارایی ارثی در میان برادران پدرشان خواهی داد؛ و تو ارث پدرشان را به آن ها منتقل خواهی کرد.\n۸. و به بنی اسرائیل بگو که اگر مردی مرد و پسری نداشت، ارثش را به دخترش منتقل کن.\n۹. و اگر دختری نداشت، ارثش را به برادرانش می دهی.\n۱۰. و اگر برادر ندارد، ارثش را به برادران پدرش می دهی.\n۱۱. و اگر پدرش برادری ندارد، ارث او را به خویشاوند او که در کنار او از خانواده اش است می دهی و او مالک آن خواهد بود؛ و این برای بنی اسرائیل قانون داوری خواهد بود، همان گونه که خداوند به موسی فرمان داده است.\n۱۲. و خداوند به موسی گفت: «به این کوه اباریم برو و سرزمینی را که به بنی اسرائیل داده ام ببین.\n۱۳. و وقتی آن را دیدی، تو نیز به قوم خود جمع خواهی شد، همان گونه که هارون برادرت گرد آمده بود.\n۱۴. زیرا شما در بیابان زین، در نزاع جماعت، بر فرمان من شورش کردید تا مرا در برابر آب پیش از چشمانشان تقدیس کنید: یعنی آب مریبا در قادش در بیابان زین.\n۱۵. و موسی به خداوند گفت:\n۱۶. بگذار خداوند، خدای ارواح همه انسانان، مردی را بر جماعت بنشاند،\n۱۷. که می تواند پیش از آن ها بیرون برود، و پیش از آن ها وارد شود، و آن ها را بیرون ببرد و آن ها را به داخل بیاورد؛ که جماعت خداوند مانند گوسفندانی که چوپان ندارند نباشند.\n۱۸. و خداوند به موسی گفت: یوشع پسر راهبه را بگیر، مردی که در او روح است، و دستت را بر او بگذار؛\n۱۹. و او را پیش العازر کشیش و در برابر همه جماعت قرار بده؛ و به او حمله ای در دید آن ها بدهد.\n۲۰. و بخشی از عزت خود را بر او بگذار تا همه جماعت بنی اسرائیل مطیع باشند.\n۲۱. و او در برابر الیعازر کشیش خواهد ایستاد، که پس از داوری اوریم نزد خداوند از او مشورت خواهد خواست: به فرمان او خواهند رفت و به فرمان او وارد خواهند شد، هم او و هم همه بنی اسرائیل با او، حتی همه جماعت.\n۲۲. و موسی همان طور که خداوند به او فرمان داده بود، عمل کرد: و یوشع را گرفت و در برابر الیعازر کاهن و در برابر همه جماعت قرار داد:\n۲۳. و او دست هایش را بر او گذاشت و به او فرمان داد، همان طور که خداوند به دست موسی فرمان داده بود.","۱. و خداوند به موسی گفت و گفت:\n۲. به بنی اسرائیل فرمان بده و به آنان بگو: قربانی من، و نان من برای قربانی هایی که در آتش انجام شده اند، برای من عطری شیرین است، و در زمان مناسب به من تقدیم کن. {یک شیرین...: عبری. طعم استراحتم}\n۳. و به آنان خواهی گفت: این همان قربانی ای است که با آتش به خداوند تقدیم می کنی؛ دو بره سال اول بدون لکه روز به روز، {برای} قربانی سوخته مداوم. {روز به روز: عبری. در یک روز}\n۴. یک بره را صبح نذر کن و بره دیگر را در برابر نذر کنی؛ {در حفت: عبری. بین دو شب}\n۵. و یک دهم بخش از یک افه آرد برای نذری گوشت، مخلوط با قسمت چهارم یک هین روغن زده شده.\n۶. {این} قربانی سوختنی مداوم است که در کوه سینا برای عطر شیرین مقدر شده است، قربانی ای که با آتش به خداوند تقدیم می شود.\n۷. و قربانی آن {باید چهارمین {قسم} یک هین برای یک بره باشد: در {جایگاه} مقدس باید شراب قوی را به خداوند {برا} قربانی بریز.\n۸. و بره دیگر را در برابر تقدیم خواهی کرد: به عنوان قربانی گوشت صبح و به عنوان نذری نوشیدنی آن، قربانی ای که در آتش تقدیم شده و عطری شیرین به خداوند است.\n۹. و در روز شنبه، دو بره سال اول بدون لکه و دو دهم آرد {برای} نذری گوشتی مخلوط با روغن و نذر آن بود:\n۱۰. {این} قربانی سوختن هر شنبه است، به جز قربانی سوخته مداوم و نذر نوشیدنی او.\n۱۱. و در آغاز ماه های خود قربانی سوخته ای به خداوند تقدیم کنید؛ دو گاو نر جوان و یک قوچ، هفت بره سال اول بدون خال؛\n۱۲. و سه دهم آرد {برای} قربانی گوشت، مخلوط با روغن، برای یک گاو؛ و دو دهم آرد {برای} نذری گوشت، مخلوط با روغن، برای یک قوچ؛\n۱۳. و چند دهم آرد مخلوط شده با روغن {برای} نذری گوشتی به یک بره؛ برای قربانی سوخته ای از عطر شیرین، قربانی ای که با آتش به خداوند تقدیم می شود.\n۱۴. و نذورات نوشیدنی آن ها نصف یک هین شراب به یک گاو و یک سوم یک هین به قوچ و یک چهارم یک هین به بره خواهد بود: این همان قربانی سوختن هر ماه در طول سال است.\n۱۵. و یک بچه بز به عنوان قربانی گناه به خداوند تقدیم خواهد شد، علاوه بر قربانی سوختنی مداوم و قربانی نوشیدنی اش.\n۱۶. و در چهاردهمین روز ماه اول {است} فصح خداوند.\n۱۷. و در پانزدهمین روز این ماه جشن است: هفت روز نان بدون خمیر خورده خواهد شد.\n۱۸. در روز اول یک مراسم مقدس برگزار خواهد شد؛ شما هیچ نوع کار خدمتگزارانه ای انجام نخواهید داد {در آن}:\n۱۹. اما قربانی ای را که با آتش تقدیم می شود {برای} قربانی سوختنی به خداوند تقدیم می کنی؛ دو گاو نر جوان، یک قوچ و هفت بره سال اول: آن ها برای شما بی عیب خواهند بود:\n۲۰. و نذری گوشتشان از آردی مخلوط با روغن خواهد بود: سه دهم برای یک گاو و دو دهم برای قوچ تقدیم کنید؛\n۲۱. برای هر بره، در میان هفت بره، چند دهم بده:\n۲۲. و یک بز {برای} قربانی گناه، تا برای تو کفاره باشد.\n۲۳. این ها را کنار قربانی سوختنی صبح که {است} برای قربانی سوختن دائمی است، تقدیم کن.\n۲۴. پس از این روش، روزانه و در طول هفت روز، گوشت قربانی آتشین را که طعمی شیرین برای خداوند است، تقدیم خواهید کرد؛ این قربانی کنار قربانی سوختنی مداوم و نذر نوشیدنی او تقدیم خواهد شد.\n۲۵. و در روز هفتم، مراسم مقدس برگزار می شود؛ هیچ کار برده داری نخواهید کرد.\n۲۶. همچنین در روز نخستین میوه ها، زمانی که قربانی گوشتی جدیدی به خداوند می آورید، پس از هفته های حضور، مراسم مقدس برگزار خواهید کرد؛ هیچ کار بندگی ای نخواهید کرد:\n۲۷. اما قربانی سوختن را به عنوان عطری شیرین به خداوند تقدیم کن؛ دو گاو نر جوان، یک قوچ، هفت بره سال اول؛\n۲۸. و نذری گوشتشان از آرد مخلوط با روغن، سه دهم به یک گاو و دو دهم به یک قوچ،\n۲۹. تقسیم چند دهم به یک بره، در سراسر هفت بره؛\n۳۰. {و} یک بچه بز، برای جبران تو.\n۳۱. باید کنار قربانی سوختنی مداوم و قربانی گوشت او (که بی عیب برای شما خواهد بود) و نذری های نوشیدنی شان را تقدیم کنید.","۱. و در ماه هفتم، در اولین {روز} ماه، مراسم مقدس برگزار می شود؛ هیچ کار برده داری نکن: امروز روز دمیدن شیپورهاست.\n۲. و شما قربانی سوخته ای برای عطر شیرین به خداوند تقدیم کنید؛ یک گاو نر جوان، یک قوچ و هفت بره سال اول بی نقص:\n۳. و نذری گوشتشان باید از آرد مخلوط با روغن، سه دهم برای یک گاو، و دو دهم برای یک قوچ باشد،\n۴. و یک دهم برای یک بره، در میان هفت بره:\n۵. و یک بچه بز {برای} قربانی گناه، تا برای تو کفاره بدهد:\n۶. علاوه بر قربانی سوختنی ماه، و قربانی گوشت، و قربانی روزانه سوخته، و نذورات گوشتی و نذورات نوشیدنی آن ها، مطابق آداب شان، برای عطری شیرین، قربانی ای که با آتش به خداوند تقدیم می شود.\n۷. و در روز دهم این ماه هفتم، مراسم مقدس برگزار خواهید کرد؛ و شما جان خود را آزار خواهید داد: هیچ کاری در آنجا انجام نخواهید داد:\n۸. اما قربانی سوخته ای به خداوند تقدیم کن {برای} عطری شیرین؛ یک گاو نر جوان، یک قوچ و هفت بره سال اول؛ آن ها برای تو بی عیب خواهند بود:\n۹. و نذری گوشتشان باید از آرد مخلوط با روغن باشد، سه دهم به هر گاو، و دو دهم به یک قوچ،\n۱۰. یک معامله چند دهم برای یک بره، در میان هفت بره:\n۱۱. یک بچه بز {برای} قربانی گناه؛ علاوه بر قربانی گناه برای کفاره، و قربانی سوختن مداوم و نذورات گوشتی آن و نذورات نوشیدنی شان.\n۱۲. و در پانزدهم ماه هفتم، مراسم مقدس برگزار می کنید؛ هیچ کار بندگی نخواهید کرد و هفت روز ضیافتی برای خداوند برگزار خواهید کرد:\n۱۳. و قربانی سوخته، قربانی ای که با آتش تقدیم شده، با عطری شیرین به خداوند تقدیم خواهی کرد؛ سیزده گاو نر جوان، دو قوچ و چهارده بره سال اول؛ آن ها بی عیب خواهند بود:\n۱۴. و نذری گوشتشان از آرد مخلوط با روغن خواهد بود، سه دهم به هر گاو از سیزده گاو، دو دهم به هر قوچ از دو قوچ،\n۱۵. و چند دهم به هر بره از چهارده بره تقسیم می شود:\n۱۶. و یک بچه بز {به خاطر} قربانی گناه؛ علاوه بر قربانی سوخته مداوم، نذر گوشت و نذر نوشیدنی اش.\n۱۷. و در روز دوم دوازده گاو نر جوان، دو قوچ و چهارده بره سال اول بدون لکه را تقدیم کنید:\n۱۸. و قربانی گوشت و نوشیدنی هایشان برای گاوها، قوچ ها و بره ها، بر اساس تعدادشان، طبق روش:\n۱۹. و یک بچه بز {برای} قربانی گناه؛ علاوه بر قربانی سوختگی مداوم و نذورات گوشتی آن و نذورات نوشیدنی هایشان.\n۲۰. و در روز سوم، یازده گاو، دو قوچ، چهارده بره سال اول بدون نقص؛\n۲۱. و قربانی گوشت و نوشیدنی هایشان برای گاوها، قوچ ها و بره ها، بر اساس تعدادشان، به ترتیب:\n۲۲. و یک بز {برای} قربانی گناه؛ علاوه بر قربانی سوختن مداوم، نذورات گوشت و نذر نوشیدنی اش.\n۲۳. و در روز چهارم، ده گاو، دو قوچ و چهارده بره سال اول بی نقص:\n۲۴. قربانی گوشت و نوشیدنی هایشان برای گاوها، قوچ ها و بره ها، بر اساس تعدادشان، به ترتیب:\n۲۵. و یک بچه بز {به خاطر}قربانی گناه؛ علاوه بر قربانی سوخته مداوم، نذر گوشت و نذر نوشیدنی اش.\n۲۶. و در روز پنجم، نه گاو، دو قوچ و چهارده بره سال اول بدون خال:\n۲۷. و قربانی گوشت و نوشیدنی هایشان برای گاوها، قوچ ها و بره ها، بر اساس تعدادشان، به ترتیب:\n۲۸. و یک بز {برای} قربانی گناه؛ علاوه بر قربانی سوختن مداوم، نذورات گوشت و نذر نوشیدنی اش.\n۲۹. و در روز ششم هشت گاو، دو قوچ و چهارده بره سال اول بدون نقص:\n۳۰. و نذری گوشت و نوشیدنی هایشان برای گاوها، قوچ ها و بره ها، بر اساس تعدادشان، به ترتیب:\n۳۱. و یک بز {برای} قربانی گناه؛ علاوه بر قربانی سوخته مداوم، نذر گوشت و نذر نوشیدنی اش.\n۳۲. و در روز هفتم، هفت گاو، دو قوچ و چهارده بره سال اول بی نقص:\n۳۳. و قربانی گوشت و نوشیدنی هایشان برای گاوها، قوچ ها و بره ها، بر اساس تعدادشان، به ترتیب:\n۳۴. و یک بز {برای} قربانی گناه؛ علاوه بر قربانی سوخته مداوم، نذر گوشت و نذر نوشیدنی اش.\n۳۵. در روز هشتم مجمع باشکوهی خواهید داشت: هیچ کار خدمتگزارانه ای انجام نخواهید داد {در آن}:\n۳۶. اما قربانی سوخته، قربانی ای که با آتش تقدیم شده، با عطری شیرین به خداوند تقدیم کن: یک گاو، یک قوچ، هفت بره سال اول بی نقص:\n۳۷. قربانی گوشت و نوشیدنی هایشان برای گاو، قوچ و بره ها، بر اساس تعدادشان، طبق روش:\n۳۸. و یک بز {برای} قربانی گناه؛ علاوه بر قربانی سوختن مداوم، نذورات گوشت و نذر نوشیدنی اش.\n۳۹. این ها را در جشن های تعیین شده خود به خداوند انجام خواهید داد، علاوه بر نذرها و نذورات آزاد، برای قربانی های سوخته، برای نذورات گوشت، برای نذورات نوشیدنی و نذورات صلح. {انجام بده: یا، پیشنهاد بده}\n۴۰. و موسی به بنی اسرائیل طبق همه آنچه خداوند به موسی فرمان داده بود، گفت.","۱. و موسی به سران قبایل درباره بنی اسرائیل گفت و گفت: این همان چیزی است که خداوند فرمان داده است.\n۲. اگر مردی به خداوند سوگند بخورد یا سوگند بخورد که روح خود را با پیوند ببندد؛ او قول خود را نخواهد شکست، بلکه طبق هر آنچه از دهانش بیرون می آید عمل خواهد کرد. {وقفه: عبری. بی ادب}\n۳. اگر زنی نیز به خداوند نذر کند و خود را با پیوند ببندد، {در جوانی در خانه پدر} باشد؛\n۴. و پدرش نذر او و پیمانی را که با آن روحش را بسته بود بشنود و پدرش در برابر او سکوت خواهد کرد: آنگاه همه سوگندهایش پابرجا خواهد ماند و هر پیوندی که روحش را به آن بسته است، پابرجا خواهد ماند.\n۵. اما اگر پدرش در روزی که می شنود، اجازه ندهد؛ هیچ یک از سوگندهایش یا پیوندهایی که روحش را به آن بسته است، پابرجا نخواهد ماند: و خداوند او را خواهد بخشید، زیرا پدرش اجازه نداده است.\n۶. و اگر اصلا شوهری داشت، وقتی که سوگند خورد یا از لبانش بگوید و روحش را به آن پیوند دهد؛ {او قسم خورد: عبری. سوگندهایش بر او بود}\n۷. و شوهرش شنید و در روزی که شنید در برابر او سکوت کرد: آنگاه سوگندهای او پابرجا خواهند ماند و بندهایی که روحش را به آن بسته بود، پابرجا خواهند ماند.\n۸. اما اگر شوهرش در روزی که او را شنید اجازه نداده باشد؛ آنگاه او سوگندی را که سوگند خورده و آنچه با لب هایش گفته و با آن روحش را بسته، بی اثر خواهد بود و خداوند او را خواهد بخشید.\n۹. اما هر نذر بیوه و مطلقه ای که جان خود را به آن گره زده اند، در برابر او خواهد ایستاد.\n۱۰. و اگر در خانه شوهرش سوگند خورده یا روحش را با سوگند بسته باشد؛\n۱۱. و شوهرش آن را شنید و در برابر او سکوت کرد و اجازه نداد: آنگاه همه سوگندهایش پابرجا خواهد بود و هر پیوندی که با آن جان خود را بسته، پابرجا خواهد بود.\n۱۲. اما اگر شوهرش در روزی که آن ها را شنید، آن ها را کاملا باطل کرده باشد؛ پس آنچه از دهانش درباره نذرهایش یا بند روحش بیرون آمده، پابرجا نخواهد ماند: شوهرش آن ها را باطل کرده است؛ و خداوند او را خواهد بخشید.\n۱۳. هر نذر و هر سوگند الزام آور برای آسیب رساندن به روح، شوهر می تواند آن را برقرار کند یا شوهرش آن را باطل کند.\n۱۴. اما اگر شوهرش روز به روز کاملا در برابر او سکوت کند؛ سپس همه عهدها یا همه پیوندهایش را که بر او است برقرار می کند: آن ها را تأیید می کند، زیرا در روزی که آن ها را شنید، در برابر او سکوت کرد.\n۱۵. اما اگر به هر طریقی پس از شنیدن آن ها را باطل کند؛ آنگاه او گناه او را خواهد پذیرفت.\n۱۶. این ها قوانین هستند که خداوند به موسی فرمان داده بود، بین مرد و همسرش، بین پدر و دخترش، که هنوز در جوانی در خانه پدرش بود.","۱. و خداوند به موسی گفت و گفت:\n۲. انتقام بنی اسرائیل مدیانی ها را بگیر: پس از آن به قوم خود جمع خواهی شد.\n۳. و موسی به مردم گفت: «برخی از خود را برای جنگ مسلح کنید و بگذارید علیه مدیانی ها بجنگند و انتقام خداوند مدیان را بگیرند.»\n۴. از هر قبیله، هزار نفر را در سراسر قبایل اسرائیل به جنگ بفرستید. {از...: عبری. هزار نفر از یک قبیله، هزار نفر از یک قبیله}\n۵. پس از هزاران اسرائیل، هزار نفر از {هم} قبیله، دوازده هزار مسلح برای جنگ نجات یافتند.\n۶. و موسی آن ها را به جنگ فرستاد، هزار نفر از {هم} قبیله، آن ها و فینحاس پسر العازر کاهن، با سازهای مقدس و شیپورها برای نواختن در دستش.\n۷. و آنان با مدیانی ها جنگیدند، همان گونه که خداوند به موسی فرمان داد؛ و همه نرها را کشتند.\n۸. و پادشاهان مدیان را کشتند، علاوه بر بقیه کشته شدگان؛ {یعنی}، اوی، و رکم، و زور، و هور، و ربا، پنج پادشاه مدیان: بلعام نیز پسر بئور بود که با شمشیر کشتند.\n۹. و بنی اسرائیل همه زنان مدیان را اسیر کردند و فرزندانشان را گرفتند و غنیمت همه دام ها و گله ها و اموالشان را گرفتند.\n۱۰. و همه شهرهای خود را که در آن زندگی می کردند و همه قلعه های زیبای خود را با آتش سوزاندند.\n۱۱. و همه غنائم و همه شکارها، هم انسان ها و هم حیوانات را گرفتند.\n۱۲. و اسیران و شکار و غنیمت را نزد موسی و الیعازر کاهن و جماعت بنی اسرائیل به اردوگاه دشت های موآب بردند که در نزدیکی اردن اریحا هستند.\n۱۳. و موسی و الیعازر کاهن و همه شاهزادگان جماعت بدون اردوگاه به استقبال آنان رفتند.\n۱۴. و موسی از افسران سپاه خشمگین شد، از فرماندهان هزاران نفر و فرماندهان بر صدها نفر که از نبرد آمده بودند. {نبرد: عبری. میزبان جنگ}\n۱۵. و موسی به آن ها گفت: آیا همه زنان را زنده نجات داده اید؟\n۱۶. اینگونه بود که این ها باعث شد بنی اسرائیل به واسطه مشورت بلعام، در موضوع پعور به خداوند تجاوز کنند و در میان جماعت خداوند بلایی به وجود آمد.\n۱۷. پس هر مرد کوچک را بکش و هر زنی را که مرد را دیده با او بکش. {او: عبری. یک مرد}\n۱۸. اما همه زنان، کودکان، که با دراز کشیدن مردی را نشناخته اند، برای خودتان زنده بمانید.\n۱۹. و هفت روز بدون اردوگاه بمانید: هر که کسی را کشته و به کشته ها دست زده باشد، خود و اسیران خود را در روز سوم و هفتم پاک کنید.\n۲۰. و همه لباس هایت و هر آنچه از پوست ساخته شده و همه کارهای بزها و همه چیزهای چوبی را پاک کن. {آن...: عبری. ابزار، یا، ظرف پوست ها}\n۲۱. و الیعازر کاهن به مردان جنگی که به نبرد رفتند گفت: این {است} فرمان شریعی است که خداوند به موسی فرمان داده بود؛\n۲۲. فقط طلا، و نقره، برنج، آهن، قلع و سرب،\n۲۳. هر چیزی که در آتش باقی بماند، باید آن را از میان آتش عبور دهی و پاک خواهد شد؛ اما با آب جدایی پاک خواهد شد؛ و هر آنچه باقی نماند، آتش را از میان آب عبور خواهی داد.\n۲۴. و در روز هفتم لباس هایت را بشویید و پاک خواهید شد و سپس وارد اردوگاه خواهید شد.\n۲۵. و خداوند به موسی گفت و گفت:\n۲۶. مجموع طعمه ای که گرفته شد، {هم} انسان و حیوان، تو، و الیعازر کاهن و پدران ارشد جماعت را بگیر: {که...: عبری. از اسارت}\n۲۷. و شکار را به دو بخش تقسیم کن؛ میان کسانی که جنگ را بر عهده گرفتند، کسانی که به نبرد رفتند، و میان همه جماعت:\n۲۸. و به خداوند مردان جنگی که به جنگ رفتند، خراج بده: یک نفر از پانصد نفر، از هر دو، از گاوها، از الاغ ها و گوسفندان:\n۲۹. آن را از نیمه خود بگیر و به الیعازر کاهن بده، {برای} قربانی بلند خداوند.\n۳۰. و از نیمه بنی اسرائیل، یک سهم از پنجاه نفر از اشخاص، گاوها، الاغ ها و گله ها و انواع حیوانات را بردار و به لاویان بدهی که مراقب خیمه خداوند هستند. {گله ها: یا بزها}\n۳۱. و موسی و العازر کاهن چنان انجام دادند که خداوند به موسی فرمان داد.\n۳۲. و غنیمت، که باقی شکار بود که مردان جنگ گرفته بودند، ششصد هزار و هفتاد هزار و پنج هزار گوسفند بود،\n۳۳. و سیصد و دوازده هزار گاو،\nسی و چهار. و سیصد و هزار خر،\n۳۵. و در مجموع سی و دو هزار نفر، از زنانی که با او مرد را نشناخته بودند.\n۳۶. و نیمی که همان بخشی از آنان بود که به جنگ رفتند، به تعداد سیصد هزار و هفت و سی هزار و پانصد گوسفند بود:\n۳۷. و خراج خداوند بر گوسفندان ششصد و شصت و پانزده بود.\n۳۸. و گاوها سی و شش هزار بودند؛ که خراج خداوند از آن ها سیصد و دوازده بود.\n۳۹. و خرها سی هزار و پانصد بودند؛ که مبلغ خراج خداوند {شصت و یک} بود.\n۴۰. و افراد شانزده هزار نفر بودند؛ که خراج خداوند سی و دو نفر بود.\n۴۱. و موسی خراج را که قربانی خداوند بود، به الیعازر کاهن داد، همان گونه که خداوند به موسی فرمان داده بود.\n۴۲. و از نیمه بنی اسرائیل که موسی آن را از مردان جنگ طلب جدا کرد،\n۴۳. (اکنون نیمی که مربوط به جماعت بود، سیصد هزار و سی هزار و هفت هزار و پانصد گوسفند بود،\n۴۴. و سی و شش هزار گاو،\n۴۵. و سی هزار خر و پانصد،\n۴۶. و شانزده هزار نفر؛)\n۴۷. حتی از نیمه بنی اسرائیل، موسی یک سهم از پنجاه، {هم} انسان و حیوان را گرفت و آن ها را به لاویان داد که مسئول خیمه خداوند بودند؛ چنان که خداوند به موسی فرمان داد.\n۴۸. و افسرانی که بیش از هزاران نفر از لشکر، فرماندهان هزاران و فرماندهان صدها نفر بودند، به موسی نزدیک شدند:\n۴۹. و به موسی گفتند: بندگانت مجموع مردان جنگی که تحت فرمان ما هستند را گرفته اند و هیچ از ما کم نیست. {شارژ: عبری. دست}\n۵۰. بنابراین ما قربانی ای برای خداوند آورده ایم، آنچه هر انسان به دست آورده است، از جواهرات طلا، زنجیرها و دستبندها، انگشترها، گوشواره ها و لوح ها، تا کفاره ای برای جان های ما در برابر خداوند باشد. {گرفتم: عبری. یافت شد}\n۵۱. و موسی و العازر کاهن طلای آن ها را گرفتند، {حتی} همه جواهرات ساخته شده.\n۵۲. و تمام طلای قربانی که به خداوند تقدیم کردند، از فرماندهان هزاران و فرماندهان صدها، شانزده هزار و هفتصد و پنجاه شکل بود. {تقدیم می کند: عبری. نذر بالا آوردن}\n۵۳. ({زیرا} مردان جنگ غنیمت گرفته بودند، هر برای خود.)\n۵۴. و موسی و الیعازر کاهن، طلای فرماندهان هزاران و صدها نفر را گرفتند و به خیمه جماعت آوردند، {برا} یادبودی برای بنی اسرائیل در برابر خداوند.","۱. اکنون فرزندان روبن و فرزندان گاد گله های بسیار زیادی داشتند: و وقتی سرزمین یازر و سرزمین جلعاد را دیدند، آن مکان مکانی برای دام ها بود؛\n۲. فرزندان گاد و فرزندان روبن آمدند و با موسی و الیعازر کاهن و شاهزادگان جماعت گفتند:\n۳. آتاروت، و دیبون، و یازر، و نیمره، و هشبون، و الیاله، و شبام، و نبو، و بئون، {نیمره: همچنین به نام بثنیمرا} {شبم: همچنین به نام شیبمه} {بئون: همچنین به نام بعلمئون}\n۴. {حتی} سرزمینی که خداوند در برابر جماعت اسرائیل تصرف کرد، {است} سرزمینی برای دام ها و بندگان تو گاوهایی دارند:\n۵. بنابراین، آن ها گفتند، اگر در نظر تو لطف یافته ایم، بگذار این سرزمین به بندگانت برای مالکیت داده شود، {و} ما را از اردن عبور نده.\n۶. و موسی به بنی گاد و به فرزندان روبن گفت: آیا برادرانتان به جنگ می روند و اینجا می نشینید؟\n۷. و چرا دل بنی اسرائیل را از رفتن به سرزمینی که خداوند به آن ها داده بازمی دارید؟ {دلسرد: عبری. وقفه}\n۸. پدرانتان نیز چنین بودند، وقتی من آن ها را از کادشبرنه فرستادم تا سرزمین را ببینند.\n۹. زیرا وقتی به دره اشکول رفتند و زمین را دیدند، دل بنی اسرائیل را دلسرد کردند تا وارد سرزمینی نشوند که خداوند به آن ها داده بود.\n۱۰. و خشم خداوند همزمان شعله ور شد و قسم خورد و گفت:\n11. مطمئنا هیچ یک از مردانی که از مصر از بیست سالگی به بالا آمده اند، سرزمینی را نخواهند دید که من به ابراهیم، به اسحاق و به یعقوب قسم خورده ام؛ چون آن ها کاملا از من پیروی نکرده اند: {کاملا...: عبری. بعد از من انجام شد}\n۱۲. کالب، پسر یفوننه کنزی، و یوشع پسر راهبه را نجات دهید؛ زیرا آن ها کاملا از خداوند پیروی کرده اند.\n۱۳. و خشم خداوند بر اسرائیل شعله ور شد و او آنان را چهل سال در بیابان سرگردان ساخت، تا اینکه تمام نسلی که در برابر خداوند بدی کرده بود، نابود شد.\n۱۴. و اینک، شما به جای پدرانتان برخاسته اید، مردان گناهکار افزایش یافته اید، تا خشم شدید خداوند نسبت به اسرائیل را افزایش دهید.\n۱۵. زیرا اگر از او روی برگردانید، او باز هم آن ها را در بیابان رها خواهد کرد؛ و تو همه این مردم را نابود خواهی کرد.\n۱۶. و آن ها نزد او آمدند و گفتند: ما اینجا برای دام هایمان اصطبل و برای کوچکمان شهر خواهیم ساخت:\n۱۷. اما خود ما مسلح در برابر بنی اسرائیل خواهیم رفت، تا زمانی که آن ها را به جای خود بیاوریم؛ و کودکان ما به خاطر ساکنان سرزمین در شهرهای محصور ساکن خواهند شد.\n۱۸. تا زمانی که بنی اسرائیل ارث هر مرد را به ارث نبرده باشد، به خانه های خود باز نخواهیم گشت.\n۱۹. زیرا ما با آن ها در آن سوی اردن یا جلوتر ارث نخواهیم برد؛ چون میراث ما در این سوی اردن به سمت شرق به ما افتاده است.\n۲۰. و موسی به آنان گفت: اگر این کار را انجام دهید، اگر مسلح در برابر خداوند به جنگ بروید،\n۲۱. و همه شما مسلح بر اردن پیش خداوند خواهید رفت، تا دشمنانش را از پیش خود بیرون کند،\n۲۲. و سرزمین در برابر خداوند مطیع شوید؛ سپس بازخواهید گشت و در برابر خداوند و اسرائیل بی گناه خواهید بود؛ و این سرزمین در حضور خداوند مالکیت شما خواهد بود.\n۲۳. اما اگر این کار را نکنی، بنگر که به خداوند گناه کرده ای: و مطمئن باش که گناهت تو را آشکار خواهد کرد.\n۲۴. شهرهایی برای کوچولوهایت بساز و برای گوسفندان خود چین بساز؛ و آنچه از دهانت بیرون آمده را انجام بده.\n۲۵. و فرزندان گاد و فرزندان روبن به موسی گفتند: بندگانت چنان عمل خواهند کرد که خداوند من فرمان دهد.\n۲۶. فرزندان کوچکمان، همسرانمان، گله ها و همه دام های ما در شهرهای جلعاد خواهند بود:\n۲۷. اما بندگانت خواهند گذشت، هر مرد مسلح برای جنگ، در برابر خداوند به نبرد خواهند رفت، همان طور که سرور من می فرماید.\n۲۸. پس موسی درباره آن ها به الیعازر کاهن و یوشع پسر نون و پدران ارشد قبایل بنی اسرائیل فرمان داد:\n۲۹. و موسی به آنان گفت: اگر بنی گاد و بنی روبن با شما از اردن عبور کنند، هر مرد مسلح برای جنگ، در برابر خداوند و سرزمین در برابر شما تسخیر خواهد شد؛ پس سرزمین جلعاد را به عنوان مالکیت به آن ها خواهی داد:\n۳۰. اما اگر با تو مسلح عبور نکنند، در سرزمین کنعان در میان شما مالکیت خواهند داشت.\n۳۱. و فرزندان گاد و فرزندان روبن پاسخ دادند و گفتند: همان طور که خداوند به بندگانت گفته است، ما نیز خواهیم کرد.\n۳۲. ما مسلح در برابر خداوند به سرزمین کنعان عبور خواهیم کرد تا مالکیت میراث ما در این سوی اردن {ممکن است} از آن ما باشد.\n۳۳. و موسی به آنان، حتی، به بنی جاد و به فرزندان روبن و به نیمی از قبیله منسی پسر یوسف، پادشاهی سیحون پادشاه اموری ها و پادشاهی اوگ پادشاه باشان، سرزمین و شهرهای آن در سواحل، و حتی شهرهای اطراف را به آن ها داد.\n۳۴. و فرزندان گاد دیبون، آتاروت و آروئر را ساختند،\n۳۵. و آتروت، شوفان، و یازر و جوگبها، {جازر: همچنین جازر نامیده می شود}\n۳۶. و بثنیمرا و بثهاران، شهرهای محصور و آزارهایی برای گوسفندان. {بثنیمرا: همچنین نیمرا نامیده می شود}\n۳۷. و فرزندان روبن هشبون، العاله و کیرجاتایم را ساختند،\n۳۸. و نبو، و بعلمئون، (نام هایشان تغییر یافت) و شیبمه: و نام های دیگری به شهرهایی که ساختند دادند. {داد...: عبری. آن ها نام شهرها را با نام ها می نامیدند}\n۳۹. و فرزندان ماکیر پسر مناسی به جلعاد رفتند و آن را گرفتند و آموری را که در آن بود، از او گرفتند.\n۴۰. و موسی جلعاد را به ماخیر، پسر منشه، داد؛ و او در آن سکونت داشت.\n۴۱. و یعیر پسر منشه رفت و شهرهای کوچک آن ها را گرفت و آن ها را هاوثیار نامید.\n۴۲. و نوبه رفت و قناث و روستاهای آن را گرفت و آن را نوبه نامید، به نام خودش.","۱. این ها سفرهای بنی اسرائیل است که با ارتش های خود تحت فرمان موسی و هارون از سرزمین مصر خارج شدند.\n۲. و موسی سفرهایشان را مطابق سفرهایشان به فرمان خداوند نوشت؛ و این ها سفرهایشان مطابق با رفت وآمدشان است.\n۳. و آن ها در ماه اول، در پانزدهمین روز ماه اول، از رامسس حرکت کردند؛ فردا پس از عید فصح، بنی اسرائیل با قدرت در برابر همه مصریان بیرون رفتند.\n۴. زیرا مصریان همه نخستین فرزندان خود را که خداوند در میان آنان فرود آورده بود، دفن کردند؛ خداوند نیز بر خدایانشان حکم صادر کرد.\n۵. و بنی اسرائیل از رامسس جدا شدند و در سوکوت زمین زدند.\n۶. و آن ها از ساکوت حرکت کردند و در ایتام که {است} در لبه بیابان است، توقف کردند.\n۷. و از اتام جدا شدند و دوباره به سوی پیحیروت که پیش از بعلزفون است، برگشتند و پیش از میگدول به میدان رفتند.\n۸. و از پیش پیحیروت حرکت کردند و از میان دریا به بیابان رفتند و سه روز در بیابان اتام سفر کردند و در ماراه توقف کردند.\n۹. و از ماراه رفتند و به الیم آمدند؛ و در الیم دوازده چشمه آب و سیصد و ده نخل بود؛ و آن ها آنجا پرتاب کردند.\n۱۰. و از الیم رفتند و کنار دریای سرخ اردو زدند.\n۱۱. و از دریای سرخ جدا شدند و در بیابان گناه اردو زدند.\n۱۲. و سفر خود را از بیابان گناه آغاز کردند و در دوفکا اردو زدند.\n۱۳. و از دوفکا حرکت کردند و در آلوش اردو زدند.\n۱۴. و آنان از آلوش رفتند و در رفیدیم اردو زدند، جایی که آب برای نوشیدن مردم نبود.\n۱۵. و از رفیدیم رفتند و در بیابان سینا به زمین خوردند.\n۱۶. و آن ها از بیابان سینا خارج شدند و در کیبراثتاوا زمین زدند. {کیبروتهاتاوا: یعنی قبرهای شهوت}\n۱۷. و آن ها از کیبروتهاتاوا حرکت کردند و در هازروت اردو زدند.\n۱۸. و از هازروت حرکت کردند و در ریتما فرود آمدند.\n۱۹. و آن ها از ریتما حرکت کردند و در ریمونپارز پرتاب کردند.\n۲۰. و آن ها از ریمونپارز حرکت کردند و لیبنا را وارد کردند.\n۲۱. و آن ها از لیبنه جدا شدند و به سمت ریسا پرتاب کردند.\n۲۲. و آن ها از ریسا سفر کردند و در کهلاثا توپ انداختند.\n۲۳. و آن ها از کهلاثا رفتند و کوه شافر را اضافه کردند.\n۲۴. و از کوه شافر خارج شدند و در حرادا اردو زدند.\n۲۵. و آن ها از حرادا خارج شدند و در ماخلوت زمین انداختند.\n۲۶. و از ماخلوت رفتند و در تحات اردو زدند.\n۲۷. و از تحات حرکت کردند و در تاراه توپ انداختند.\n۲۸. و آن ها از تاراه جدا شدند و میتکا را وارد کردند.\n۲۹. و آن ها از میتکا رفتند و هاشمونا را وارد کردند.\n۳۰. و آن ها از هاشمونا حرکت کردند و در موسروت اردو زدند.\n۳۱. و از موسروت حرکت کردند و در بنجاکان زمین انداختند.\n۳۲. و آن ها از بنجااکان رفتند و در هورهاگیدگاد اردو زدند.\n۳۳. و آن ها از هورهاگیدگاد رفتند و در یوتباثا پرتاب کردند.\n۳۴. و آن ها از یوتباثا رفتند و در ابرونا اردو زدند.\n۳۵. و از ابرونا حرکت کردند و در ایزیونگابر اردو زدند.\n۳۶. و از ایزیونگابر رفتند و در بیابان زین، که {قادش} است، دچار شدند.\n۳۷. و از قادش جدا شدند و در کوه هور، در حاشیه سرزمین ادوم پهلو گرفتند.\n۳۸. و هارون کاهن به فرمان خداوند به کوه هور رفت و در آنجا درگذشت، در سال چهل پس از آنکه بنی اسرائیل از سرزمین مصر بیرون آمدند، در اولین {روز} ماه پنجم.\n۳۹. و هارون زمانی که در کوه هور درگذشت، صد و بیست و سه ساله بود.\n۴۰. و پادشاه عراد کنعانی که در جنوب سرزمین کنعان ساکن بود، از آمدن بنی اسرائیل مطلع شد.\n۴۱. و از کوه هور حرکت کردند و در زالمونا توقف کردند.\n۴۲. و آن ها از زالمونا حرکت کردند و در پونون زمین زدند.\n۴۳. و آن ها از پونون حرکت کردند و در اوبوت توقف کردند.\n۴۴. و از اوبوت حرکت کردند و در ایجاباریم، در مرز موآب، توقف کردند. {ایجاباریم: یا، توده هایی از آباریم}\n۴۵. و از ایم حرکت کردند و در دیبونگاد مستقر شدند.\n۴۶. و آن ها از دیبونگاد خارج شدند و در المندیبلتایم اردو زدند.\n۴۷. و از الموندیبلثایم رفتند و در کوه های آباریم، پیش از نبو زمین انداختند.\n۴۸. و آن ها از کوه های اباریم حرکت کردند و در دشت های موآب کنار اردن {نزدیک} اریحا دفن شدند.\n۴۹. و آن ها از کنار اردن، از بیت جسیموت {حتی} تا ابلشیتیم در دشت های موآب، به زمین پرتاب کردند. {ابلشیتیم: یا دشت های شیتیم}\n۵۰. و خداوند در دشت های موآب در نزدیکی اردن اریحا به موسی گفت:\n۵۱. با بنی اسرائیل سخن بگو و به آنان بگو: وقتی از اردن عبور کردی و وارد سرزمین کنعان شدی؛\n۵۲. آنگاه همه ساکنان سرزمین را از پیش خود بیرون خواهی کرد، همه تصاویر شان را نابود خواهی کرد، همه تندیس های مذاب شان را نابود کردی و همه بلندی هایشان را کاملا پایین برداشتی:\n۵۳. و شما ساکنان سرزمین را از آن محروم خواهید کرد و در آن ساکن خواهید شد؛ زیرا من زمین را به شما داده ام تا مالک آن شوید.\n۵۴. و زمین را به صورت قرعه تقسیم کنید تا بین خانواده هایتان ارث ببرد: {و} هرچه بیشتر ارث بیشتری بدهید و به ارث کمتر بدهید: ارث هر در جایی خواهد بود که قرعه اش می افتد؛ بر اساس قبایل پدرانت، وارث خواهی شد. {بیشتر بده...: عبری. ارث او را ضرب کن} {کمتر بده...: عبری. ارثیه اش را کاهش دهد}\n۵۵. اما اگر ساکنان سرزمین را از پیش خود بیرون نکن؛ آنگاه خواهد شد که آنچه از آن ها باقی می ماند [خارهایی در چشمانتان و خارهایی در پهلوهایتان» خواهند بود و شما را در سرزمینی که در آن زندگی می کنید آزار خواهند داد.\n۵۶. علاوه بر این، این اتفاق خواهد افتاد، {همان} که با تو خواهم کرد، همان طور که فکر می کردم با آن ها انجام دهم.","۱. و خداوند به موسی گفت و گفت:\n۲. به بنی اسرائیل فرمان بده و به آنان بگو: وقتی وارد سرزمین کنعان شدید؛ (این {است} سرزمینی است که برای ارث به تو خواهد رسید، {حتی} سرزمین کنعان با سواحل آن:)\n۳. پس بخش جنوبی شما از بیابان زین در امتداد ساحل ادوم خواهد بود و مرز جنوبی شما دورترین ساحل دریای شور به سمت شرق خواهد بود:\n۴. و مرز تو از جنوب به صعود آکربیم می چرخد و به زین می رسد؛ و خروج از آن از جنوب به کادشبرنه خواهد بود، سپس به هزارادار و سپس به عزمون:\n۵. و مرز باید قطب نما را از آزمون تا رود مصر بیاورد، و خروج از آن در دریا خواهد بود.\n۶. و در مورد مرز غربی، حتی دریای بزرگ را به عنوان مرز خواهید داشت: این مرز غربی شماست.\n۷. و این مرز شمالی تو خواهد بود: از دریای بزرگ کوه هور را برای خود نشان خواهی داد:\n۸. از کوه هور مرز خود را تا ورودی حماث نشان دهید؛ و خروج از مرز به سمت زداد خواهد بود:\n۹. و مرز به سوی زیفرون ادامه خواهد یافت و خروج از آن در هزارنان خواهد بود: این مرز شمالی شما خواهد بود.\n۱۰. و مرز شرقی خود را از هزارنان تا شفام نشان خواهی داد:\n۱۱. و ساحل از شفام به ربله، در سمت شرق آین، پایین خواهد آمد؛ و مرز پایین خواهد آمد و تا کنار دریای چینرث به سمت شرق امتداد خواهد یافت: {طرف دریا: عبری. شانه دریا}\n۱۲. و مرز به سوی اردن خواهد رفت و خروج از آن در دریای شور خواهد بود؛ این سرزمین تو خواهد بود و سواحل اطراف آن نیز همین است.\n۱۳. و موسی به بنی اسرائیل فرمان داد و گفت: این همان سرزمینی است که با قرعه به ارث خواهید برد، که خداوند فرمان داده به نه قبیله و به نیم قبیله بدهید:\n۱۴. زیرا قبیله فرزندان روبن بر اساس خاندان پدرانشان، و قبیله فرزندان گاد بر اساس خاندان پدرانشان، {ارث خود} را دریافت کرده اند؛ و نیمی از قبیله منسی ارث خود را دریافت کرده اند:\n۱۵. دو قبیله و نیم قبیله میراث خود را در این سوی اردن {نزدیک} اریحا به سمت شرق، به سوی طلوع خورشید دریافت کرده اند.\n۱۶. و خداوند به موسی گفت:\n۱۷. این ها نام مردانی هستند که زمین را به تو تقسیم خواهند کرد: الیعازر کاهن و یوشع پسر راهبه.\n۱۸. و تو یک شاهزاده از هر قبیله خواهی گرفت تا زمین را بر اساس ارث تقسیم کنی.\n۱۹. و نام های مردان عبارتند از: قبیله یهودا، کالب پسر یفونه.\n۲۰. و از قبیله فرزندان شمعون، شموئل پسر امیهود.\n۲۱. از قبیله بنیامین، الیداد پسر چیسلون.\n۲۲. و شاهزاده قبیله فرزندان دان، بوکی پسر یوگلی.\n۲۳. شاهزاده فرزندان یوسف، برای قبیله فرزندان منسی، حنیال پسر افود.\n۲۴. و شاهزاده قبیله فرزندان افرایم، کموئل پسر شیفتان.\n۲۵. و شاهزاده قبیله فرزندان زبولون، الیزافان پسر پارناخ.\n۲۶. و شاهزاده قبیله فرزندان یساکار، پالتیئل پسر عزان.\n۲۷. و شاهزاده قبیله فرزندان آشر، آهیهود پسر شلومی.\n۲۸. و شاهزاده قبیله فرزندان نفتالی، پدهال پسر امیهود.\n۲۹. این ها کسانی هستند که خداوند فرمان داد میراث را در سرزمین کنعان به بنی اسرائیل تقسیم کنند.","۱. و خداوند در دشت های موآب در نزدیکی اردن اریحا به موسی گفت:\n۲. به بنی اسرائیل فرمان بده که میراث شهرهای مالک خود را به لاویان بدهند تا در آن ها سکونت کنند؛ و همچنین به حومه لاویان برای شهرهای اطراف آن ها خواهید داد.\n۳. و شهرها باید در آن ها سکونت کنند؛ و حومه های آن ها برای دام هایشان، اموالشان و همه حیواناتشان خواهد بود.\n۴. و حومه های شهرها که به لاویان خواهی داد، از دیوار شهر تا هزار ذراع اطراف آن امتداد خواهد یافت.\n۵. و از بیرون شهر در سمت شرق دو هزار بازو، در سمت جنوب دو هزار بازو، در سمت غرب دو هزار ذراع و در سمت شمال دو هزار ذراع اندازه گیری کنید؛ و شهر {در میان} خواهد بود: این برای آن ها حومه شهرها خواهد بود.\n۶. و در میان شهرهایی که به لاویان خواهی داد شش شهر برای پناه است که برای قاتل تعیین می کنی تا به آنجا فرار کند و به آن ها چهل و دو شهر اضافه می کنی. {به آن ها...: عبری. بالای سرشان خواهی بخشید}\n۷. {پس} همه شهرهایی که به لاویان خواهی داد {باید چهل و هشت شهر باشند} و آن ها {خواهی بخشید} با حومه هایشان.\n۸. و شهرهایی که خواهی بخشید، از مالکیت بنی اسرائیل خواهد بود؛ از آنان که بسیاری دارند، بسیاری خواهی بخشید؛ اما از {کسانی که دارند} اندک خواهید داد؛ هر از شهرهای خود را به لاویان خواهد داد به اندازه میراثی که به ارث می برد. {او...: عبری. آن ها ارث می برند}\n۹. و خداوند به موسی گفت:\n۱۰. به بنی اسرائیل سخن بگو و به آنان بگو: وقتی از اردن به سرزمین کنعان رسیدید؛\n۱۱. سپس شهرهای خود را به عنوان شهرهای پناهگاه خود تعیین خواهید کرد؛ تا قاتل به آنجا فرار کند، که هر کسی را بی خبر می کشد. {در...: عبری. اشتباه}\n۱۲. و آن ها برای شما شهرهایی برای پناه از انتقام گیرنده خواهند بود؛ که قاتل مرد تا زمانی که در برابر جماعت در دادگاه بایستد، نمیرد.\n۱۳. و از این شهرها شش شهر پناه خواهی گرفت.\n۱۴. سه شهر در این سوی اردن خواهید داد و سه شهر در سرزمین کنعان که شهرهای پناهگاه خواهند بود.\n۱۵. این شش شهر پناهگاهی خواهند بود، هم برای بنی اسرائیل و هم برای غریبه و برای مسافران میانشان، تا هر کسی را که بی خبر بکشد، بتواند به آنجا فرار کند.\n۱۶. و اگر او را با ابزار آهنی بزند تا بمیرد، قاتل است: قاتل قطعا اعدام خواهد شد.\n۱۷. و اگر او را با سنگ پرتاب کند تا بمیرد و بمیرد، قاتل است: قاتل قطعا اعدام خواهد شد. {با...: عبری. با سنگ دست}\n۱۸. یا اگر با سلاح دستی چوبی او را بزند تا بمیرد و بمیرد، قاتل است: قاتل قطعا اعدام خواهد شد.\n۱۹. انتقام جوی خون خودش قاتل را خواهد کشت؛ وقتی او را ملاقات کند، خواهد کشت.\n۲۰. اما اگر او را از نفرت رها کند یا با انتظار به او پرتاب کند، بمیرد؛\n۲۱. یا در دشمنی با دستش او را بزن تا بمیرد: هر که به او ضربه بزند، قطعا کشته خواهد شد؛ {زیرا} او {هست} یک قاتل: انتقام جوی خون، قاتل را خواهد کشت، وقتی او را ملاقات کند.\n۲۲. اما اگر او را ناگهان بدون دشمنی رها کند، یا چیزی را بدون انتظار بر او افکنده باشد،\n۲۳. یا با هر سنگی که انسان بمیرد، بدون اینکه او را ببیند و بر او پرتاب کند تا بمیرد و دشمنش نباشد و به دنبال آسیب نباشد:\n۲۴. سپس جماعت باید بین قاتل و انتقام گیرنده خون بر اساس این داوری ها داوری کند:\n۲۵. و جماعت قاتل را از دست انتقام گیرنده خون آزاد می کند و جماعت او را به شهر پناهگاهش بازمی گرداند، جایی که گریخته بود؛ و او تا مرگ کاهن اعظم که با روغن مقدس مسح شده بود، در آنجا خواهد ماند.\n۲۶. اما اگر قاتل در هر زمانی از مرز شهر پناهگاهش که به آنجا گریخته بود بیاید؛\n۲۷. و انتقام گیرنده خون او را بدون مرزهای شهر پناهگاهش بیابد و انتقام گیرنده خون قاتل را بکشد؛ او نباید مرتکب خون شود: {او...: عبری. هیچ خونی به او نخواهد رسید}\n۲۸. زیرا او باید تا زمان مرگ کاهن اعظم در شهر پناهگاهش می ماند؛ اما پس از مرگ کاهن اعظم، قاتل به سرزمین تحت مالکیت خود بازمی گردد.\n۲۹. پس این امور، برای شما در طول نسل ها در همه خانه هایتان حکم داوری خواهد بود.\n۳۰. هر کسی را بکشد، قاتل به زبان شاهدان اعدام خواهد شد؛ اما یک شاهد نباید علیه هیچ شهادت دهد {تا باعث مرگ او شود}.\n۳۱. علاوه بر این، برای جان قاتلی که مرتکب مرگ شده است، هیچ قنایتی نخواهید گرفت؛ اما قطعا اعدام خواهد شد. {گناهکار...: عبری. خراب برای مردن}\n۳۲. و برای کسی که به شهر پناهگاهش گریخته است، تا زمانی که کاهن بمیرد، راضی نخواهید بود که دوباره در سرزمین ساکن شود.\n۳۳. پس زمینی را که در آن هستید آلوده نکنید، زیرا خون زمین را آلوده می کند و زمین از خونی که در آن ریخته می شود پاک نمی شود، بلکه به خون کسی که آن را ریخته است. {سرزمین نمی تواند...: عبری. هیچ کفاره ای برای زمین وجود ندارد}\n۳۴. پس سرزمینی را که در آن ساکن خواهید شد، آلوده نکنید؛ زیرا من، خداوند، در میان بنی اسرائیل ساکن هستم.","۱. و پدران ارشد خانواده های فرزندان جلعاد، پسر ماخیر، پسر منسی، از خاندان های پسران یوسف، نزدیک آمدند و پیش موسی و شاهزادگان، پدران ارشد بنی اسرائیل گفتند:\n۲. و آن ها گفتند: خداوند به ارباب من فرمان داد که زمین را به صورت قرعه به بنی اسرائیل به ارث ببرد؛ و خداوند به او فرمان داد که ارث زلفهاد برادرمان را به دخترانش بدهد.\n۳. و اگر آن ها با هر یک از پسران قبایل دیگر بنی اسرائیل ازدواج کنند، ارثشان از ارث پدران ما گرفته شده و به ارث قبیله ای که به آن می رسند داده خواهد شد؛ و این نیز از سرنوشت ارث ما گرفته خواهد شد. {کجا...: عبری. به چه کسی خواهند رسید}\n۴. و زمانی که یوبیل بنی اسرائیل فرا برسد، میراث آنان به ارث قبیله ای که به آن می رسند منتقل خواهد شد؛ و ارث آنان نیز از میراث قبیله پدران ما گرفته خواهد شد. {کجا...: عبری. به چه کسی خواهند رسید}\n۵. و موسی به بنی اسرائیل فرمان داد به کلام خداوند و گفت: «قبیله پسران یوسف خوب گفته اند.»\n۶. این همان چیزی است که خداوند دربارهٔ دختران زلوفهاد فرمان داده است و می گوید: بگذار با هر که صلاح می دانند ازدواج کنند؛ تنها با خانواده قبیله پدرشان ازدواج خواهند کرد. {ازدواج: عبری. همسر باشید}\n۷. ارث بنی اسرائیل نیز از قبیله ای به قبیله دیگر منتقل نخواهد شد: زیرا هر یک از فرزندان اسرائیل خود را به ارث قبیله پدران خود پایبند خواهد ماند. {نگه دار...: عبری. به آن ها بچسبد و غیره}\n۸. و هر دختری که در هر قبیله ای از فرزندان اسرائیل ارث دارد، همسر یکی از خانواده های قبیله پدرش خواهد بود تا فرزندان اسرائیل از ارث پدران هر مرد بهره مند شوند.\n۹. همچنین ارث از {یک} قبیله به قبیله دیگر منتقل نمی شود؛ اما هر یک از قبایل بنی اسرائیل باید به میراث خود وفادار بماند.\n۱۰. همان طور که خداوند به موسی فرمان داد، دختران زلوفهاد نیز چنین کردند:\n۱۱. زیرا محله، تیرزا، هوغلا، و میلکه و نوح، دختران زلوفهاد، به پسران برادران پدرشان ازدواج کردند:\n۱۲. {و} آن ها به خانواده های پسران منسی، پسر یوسف، ازدواج دادند و ارثشان در قبیله خانواده پدرشان باقی ماند. {در...: عبری. برای برخی که از خانواده ها بودند}\n۱۳. این ها فرمان ها و داوری هایی هستند که خداوند به دست موسی به بنی اسرائیل در دشت های موآب و نزدیک اردن اریحا فرمان داده است."];
